import React, { createContext, useState, useEffect, ReactNode, useContext } from 'react';

interface User {
  name: string;
  email: string;
}

interface AuthContextType {
  user: User | null;
  isAuthenticated: boolean;
  login: (email: string, pass: string) => Promise<void>;
  signup: (name: string, email: string, pass: string) => Promise<void>;
  logout: () => void;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);

  useEffect(() => {
    // Check for a logged-in user in localStorage on initial load
    try {
      const storedUser = localStorage.getItem('vexokart-user');
      if (storedUser) {
        setUser(JSON.parse(storedUser));
      }
    } catch (error) {
      console.error("Could not parse user data from localStorage", error);
      localStorage.removeItem('vexokart-user');
    }
  }, []);

  // Mock login function
  const login = async (email: string, pass: string) => {
    if (email && pass) { // Simple validation
      const userData = { name: 'John Doe', email: email };
      localStorage.setItem('vexokart-user', JSON.stringify(userData));
      setUser(userData);
      return Promise.resolve();
    }
    return Promise.reject(new Error('Invalid credentials'));
  };

  // Mock signup function
  const signup = async (name: string, email: string, pass: string) => {
     if (name && email && pass) { // Simple validation
      const userData = { name: name, email: email };
      localStorage.setItem('vexokart-user', JSON.stringify(userData));
      setUser(userData);
      return Promise.resolve();
    }
    return Promise.reject(new Error('Invalid signup details'));
  };

  const logout = () => {
    localStorage.removeItem('vexokart-user');
    setUser(null);
  };

  const isAuthenticated = !!user;

  return (
    <AuthContext.Provider value={{ user, isAuthenticated, login, signup, logout }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

