                    {user.role !== 'ADMIN' ? (
                        <button onClick={() => handleDelete(user.email, user.name)} className="text-red-400 font-semibold hover:text-red-300">Delete</button>
                    ) : (
                        <span className="text-gray-500 text-xs">Cannot delete</span>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          {users.length === 0 && <p className="text-center p-8 text-gray-500">No users found.</p>}
        </div>
      </GlassmorphicCard>
    </div>
  );
};

export default AdminUsersPage;

