import React from 'react';
import { Order } from '../types';

interface OrderTrackerProps {
  status: Order['status'];
}

const OrderTracker: React.FC<OrderTrackerProps> = ({ status }) => {
  const statuses: Order['status'][] = ['Pending', 'Shipped', 'Delivered'];
  const currentStatusIndex = statuses.indexOf(status);

  if (status === 'Cancelled') {
    return (
        <div className="p-4 bg-red-900/50 border border-red-500/50 rounded-xl text-center">
            <p className="font-bold text-red-400">Order Cancelled</p>
        </div>
    );
  }

  return (
    <div className="p-4 bg-navy-light/50 border border-gray-700/50 rounded-xl">
        <div className="flex justify-between items-center text-xs text-center">
            {statuses.map((step, index) => (
                <React.Fragment key={step}>
                    <div className="flex flex-col items-center">
                        <div className={`w-8 h-8 rounded-full flex items-center justify-center border-2 ${index <= currentStatusIndex ? 'bg-accent border-accent' : 'bg-gray-600 border-gray-500'}`}>
                            {index < currentStatusIndex ? (
                                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" /></svg>
                            ) : (
                                <span className={`w-3 h-3 rounded-full ${index === currentStatusIndex ? 'bg-white animate-pulse' : 'bg-gray-400'}`}></span>
                            )}
                        </div>
                        <p className={`mt-2 font-semibold ${index <= currentStatusIndex ? 'text-white' : 'text-gray-400'}`}>{step === 'Pending' ? 'Placed' : step}</p>
                    </div>
                    {index < statuses.length - 1 && (
                        <div className={`flex-1 h-1 mx-2 ${index < currentStatusIndex ? 'bg-accent' : 'bg-gray-600'}`}></div>
                    )}
                </React.Fragment>
            ))}
        </div>
    </div>
  );
};

