};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

import React, { createContext, useState, useEffect, ReactNode, useContext } from 'react';
import { Product } from '../types';

interface ProductContextType {
  products: Product[];
  getProduct: (id: number) => Product | undefined;
  addProduct: (product: Omit<Product, 'id' | 'rating' | 'reviewCount' | 'reviews' | 'status'>, bySuperAdmin?: boolean) => void;
  updateProduct: (product: Product) => void;
  deleteProduct: (productId: number) => void;
}

export const ProductContext = createContext<ProductContextType | undefined>(undefined);

export const ProductProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [products, setProducts] = useState<Product[]>(() => {
    try {
      const localData = localStorage.getItem('vexokart-products');
      let parsedData = localData ? JSON.parse(localData) : [];

      if (Array.isArray(parsedData)) {
        parsedData = parsedData.map((p: any) => {
          // Backward compatibility: migrate 'features' to 'highlights'
          if (p.features && !p.highlights) {
            p.highlights = p.features;
          }
          // Backward compatibility: add vendorId and status for multi-vendor
          if (!p.vendorId) {
            p.vendorId = 'vexokart_internal'; // Assign to internal store
          }
          if (!p.status) {
            p.status = 'live'; // Assume existing products are live
          }
          return p;
        });
      }
      return parsedData;

    } catch (error) {
      console.error("Could not parse product data from localStorage", error);
      return [];
    }
  });

  useEffect(() => {
    localStorage.setItem('vexokart-products', JSON.stringify(products));
  }, [products]);

  const getProduct = (id: number): Product | undefined => {
    return products.find(p => p.id === id);
  }

  const addProduct = (productData: Omit<Product, 'id' | 'rating' | 'reviewCount' | 'reviews' | 'status'>, bySuperAdmin: boolean = false) => {
    setProducts(prevProducts => {
      const newId = prevProducts.length > 0 ? Math.max(...prevProducts.map(p => p.id)) + 1 : 1;
      const newProduct: Product = { 
        ...productData, 
        id: newId,
        rating: 4.5,
        reviewCount: 0,
        reviews: [],
        status: bySuperAdmin ? 'live' : 'pending_approval',
        stock: productData.stock || 0,
        highlights: productData.highlights || [],
        specifications: productData.specifications || {},
        sellerInfo: productData.sellerInfo || 'VexoKart Direct',
        returnPolicy: productData.returnPolicy || '30-Day Returns',
        warranty: productData.warranty || '1 Year Manufacturer Warranty',
        videoUrl: productData.videoUrl || '',
      };
      return [...prevProducts, newProduct];
    });
  };

  const updateProduct = (updatedProduct: Product) => {
    setProducts(prevProducts =>
      prevProducts.map(p => (p.id === updatedProduct.id ? updatedProduct : p))
    );
  };

  const deleteProduct = (productId: number) => {
    setProducts(prevProducts => prevProducts.filter(p => p.id !== productId));
  };

  return (
    <ProductContext.Provider value={{ products, getProduct, addProduct, updateProduct, deleteProduct }}>
      {children}
    </ProductContext.Provider>
  );
};

export const useProducts = () => {
  const context = useContext(ProductContext);
  if (context === undefined) {
    throw new Error('useProducts must be used within a ProductProvider');
  }
  return context;
};

import React, { createContext, useState, useEffect, ReactNode, useContext } from 'react';
import { Vendor } from '../types';

interface VendorContextType {
  vendors: Vendor[];
  addVendor: (vendorData: { userId: string; storeName: string }) => void;
  updateVendorStatus: (vendorId: string, status: 'approved' | 'rejected' | 'suspended') => void;
  getVendorByUserId: (userId: string) => Vendor | undefined;
  getVendorById: (vendorId: string) => Vendor | undefined;
}

export const VendorContext = createContext<VendorContextType | undefined>(undefined);

export const VendorProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [vendors, setVendors] = useState<Vendor[]>(() => {
    try {
      const localData = localStorage.getItem('vexokart-vendors');
      return localData ? JSON.parse(localData) : [];
    } catch (error) {
      console.error("Could not parse vendor data from localStorage", error);
      return [];
    }
  });

  useEffect(() => {
    localStorage.setItem('vexokart-vendors', JSON.stringify(vendors));
  }, [vendors]);

  const addVendor = (vendorData: { userId: string; storeName: string }) => {
    const newVendor: Vendor = {
      id: new Date().getTime().toString(),
      userId: vendorData.userId,
      storeName: vendorData.storeName,
      status: 'pending',
      kycDetails: {
        pan: '',
        gst: '',
        addressProofUrl: '',
        status: 'pending'
      },
      createdAt: new Date().toISOString()
    };
    setVendors(prev => [...prev, newVendor]);
  };

  const updateVendorStatus = (vendorId: string, status: 'approved' | 'rejected' | 'suspended') => {
    setVendors(prev => prev.map(v => v.id === vendorId ? { ...v, status } : v));
  };

  const getVendorByUserId = (userId: string) => {
    return vendors.find(v => v.userId === userId);
  };

  const getVendorById = (vendorId: string) => {
    return vendors.find(v => v.id === vendorId);
  }

  return (
    <VendorContext.Provider value={{ vendors, addVendor, updateVendorStatus, getVendorByUserId, getVendorById }}>
      {children}
    </VendorContext.Provider>
  );
};

export const useVendors = () => {
  const context = useContext(VendorContext);
  if (context === undefined) {
    throw new Error('useVendors must be used within a VendorProvider');
  }
  return context;
};

