const ProtectedRoute: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { isAuthenticated } = useAuth();
  if (!isAuthenticated) {
    return <Navigate to="/login" replace />;
  }
  return <>{children}</>;
};

const SuperAdminRoute: React.FC = () => {
  const { user } = useAuth();
  if (!user || user.role !== 'SUPER_ADMIN') {
    return <Navigate to="/" replace />;
  }
  return <AdminLayout><Outlet /></AdminLayout>;
};

const VendorRoute: React.FC = () => {
    const { user } = useAuth();
    if(!user || user.role !== 'VENDOR') {
        return <Navigate to="/" replace />;
    }
    return <VendorLayout><Outlet/></VendorLayout>
}

const AppContent: React.FC = () => {
  const location = useLocation();
  const isAuthPage = ['/login', '/signup', '/vendor/signup'].includes(location.pathname);
  const isAdminPage = location.pathname.startsWith('/admin');
  const isVendorPage = location.pathname.startsWith('/vendor');

  const showBottomNav = !isAuthPage && !isAdminPage && !isVendorPage && !['/checkout'].includes(location.pathname) && !location.pathname.startsWith('/order/') && !location.pathname.startsWith('/product/');

  return (
    <div className="min-h-screen bg-navy-charcoal text-gray-100 font-sans">
      <main className={showBottomNav ? "pb-20" : ""}>
        <Routes>
          {/* User Routes */}
          <Route path="/" element={<HomePage />} />
          <Route path="/products" element={<ProductsPage />} />
