import { HomeIcon } from './icons/HomeIcon';
import { CategoryIcon } from './icons/CategoryIcon';
import { CartIcon } from './icons/CartIcon';
import { UserIcon } from './icons/UserIcon';
import { useCart } from '../hooks/useCart';
import { useAuth } from '../context/AuthContext';

const BottomNav: React.FC = () => {
  const { cartCount } = useCart();
  const { isAuthenticated } = useAuth();

  const activeLinkClass = 'text-accent';
  const inactiveLinkClass = 'text-text-muted hover:text-text-main';
  const profileLink = isAuthenticated ? '/profile' : '/login';

  const NavItem: React.FC<{ to: string; children: React.ReactNode }> = ({ to, children }) => (
     <NavLink to={to} className={({ isActive }) => `${isActive ? activeLinkClass : inactiveLinkClass} transform hover:-translate-y-1`}>
       {children}
    </NavLink>
  );

  return (
    <nav className="fixed bottom-0 left-0 right-0 h-16 bg-surface/80 backdrop-blur-md border-t border-gray-700/50 shadow-t-lg z-50">
      <div className="flex justify-around items-center h-full max-w-lg mx-auto">
        <NavItem to="/">
          <div className="flex flex-col items-center justify-center">
            <HomeIcon className="h-6 w-6" />
            <span className="text-xs mt-1">Home</span>
          </div>
        </NavItem>
        <NavItem to="/products">
          <div className="flex flex-col items-center justify-center">
            <CategoryIcon className="h-6 w-6" />
            <span className="text-xs mt-1">Shop</span>
          </div>
        </NavItem>
        <NavItem to="/cart">
          <div className="relative flex flex-col items-center justify-center">
            <CartIcon className="h-6 w-6" />
            {cartCount > 0 && (
              <span className="absolute -top-1 -right-2.5 bg-accent text-white text-xs font-bold rounded-full h-5 w-5 flex items-center justify-center">
                {cartCount}
              </span>
            )}
            <span className="text-xs mt-1">Cart</span>
          </div>
        </NavItem>
        <NavItem to={profileLink}>
          <div className="flex flex-col items-center justify-center">
            <UserIcon className="h-6 w-6" />
            <span className="text-xs mt-1">Profile</span>
          </div>
        </NavItem>
      </div>
    </nav>
  );
};

export default BottomNav;

import React from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { Product } from '../types';
import StarRating from './StarRating';
import GlassmorphicCard from './GlassmorphicCard';
import { useAuth } from '../context/AuthContext';
import { HeartIcon } from './icons/HeartIcon';

interface ProductCardProps {
  product: Product;
}

const ProductCard: React.FC<ProductCardProps> = ({ product }) => {
  const { isAuthenticated, addToWishlist, removeFromWishlist, isInWishlist } = useAuth();
  const navigate = useNavigate();

  const isWishlisted = isInWishlist(product.id);

  const handleToggleWishlist = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (!isAuthenticated) {
        navigate('/login');
        return;
    }
    if (isWishlisted) {
      removeFromWishlist(product.id);
    } else {
      addToWishlist(product.id);
    }
  };

  return (
    <GlassmorphicCard className="transform hover:scale-105 hover:border-accent/50 relative">
        <button 
            onClick={handleToggleWishlist}
            className={`absolute top-2 right-2 z-10 p-1.5 bg-surface/50 rounded-full transition-colors duration-300 ${isWishlisted ? 'text-red-500' : 'text-text-secondary hover:text-red-400'}`}
        >
            <HeartIcon className="w-5 h-5" fill={isWishlisted ? 'currentColor' : 'none'}/>
        </button>

      <Link to={`/product/${product.id}`} className="block">
        <img
          src={product.images[0]}
          alt={product.name}
          className="w-full h-48 object-cover rounded-t-xl bg-gray-700"
        />
        <div className="p-4">
          <h3 className="text-lg font-semibold text-text-main truncate">{product.name}</h3>
          <p className="text-sm text-text-muted mb-2">{product.category}</p>
          <div className="flex items-center justify-between mb-2">
            <p className="text-xl font-bold text-accent">₹{product.price.toFixed(2)}</p>
            {product.originalPrice && (
              <p className="text-sm text-text-muted line-through opacity-75">₹{product.originalPrice.toFixed(2)}</p>
            )}
          </div>
          <div className="flex items-center">
            <StarRating rating={product.rating} />
            <span className="text-xs text-text-muted ml-2">({product.reviewCount})</span>
          </div>
        </div>
      </Link>
    </GlassmorphicCard>
  );
};

export default ProductCard;

import React from 'react';
import { Category } from '../types';

interface CategoryChipProps {
  category: Category;
  isSelected?: boolean;
  onClick?: () => void;
}

const CategoryChip: React.FC<CategoryChipProps> = ({ category, isSelected = false, onClick }) => {
  const baseClasses = "flex-shrink-0 text-center p-4 rounded-lg transition-all duration-300 transform hover:scale-105";
  const selectedClasses = "bg-gradient-to-br from-accent to-accent-secondary shadow-lg";
  const unselectedClasses = "bg-surface/70 backdrop-blur-sm border border-gray-700/50";

  return (
    <div
      onClick={() => onClick && onClick()}
      className={`${baseClasses} ${isSelected ? selectedClasses : unselectedClasses} cursor-pointer`}
    >
      <img src={category.image} alt={category.name} className="w-16 h-16 object-cover rounded-full mx-auto mb-2 border-2 border-accent/50" />
      <span className="font-semibold text-sm text-text-main">{category.name}</span>
    </div>
  );
};

export default CategoryChip;

import React from 'react';
import { useNavigate } from 'react-router-dom';
import Header from '../components/Header';
import CategoryChip from '../components/CategoryChip';
import ProductCard from '../components/ProductCard';
import { useProducts } from '../hooks/useProducts';
import { useCategories } from '../hooks/useCategories';

const HomePage: React.FC = () => {
  const { products } = useProducts();
  const { categories } = useCategories();
  const navigate = useNavigate();

  const handleCategoryClick = (categoryName: string) => {
    navigate(`/products?category=${encodeURIComponent(categoryName)}`);
  };

  return (
    <div>
      <Header title="VexoKart" showSearch />
      <div className="p-4 space-y-8">
        <section>
          <h2 className="text-xl font-bold text-text-main mb-4">Categories</h2>
          {categories.length > 0 ? (
            <div className="flex space-x-4 overflow-x-auto pb-4 -mx-4 px-4">
              {categories.map(category => (
                <CategoryChip key={category.id} category={category} onClick={() => handleCategoryClick(category.name)} />
              ))}
            </div>
          ) : (
            <p className="text-text-muted text-sm">No categories have been added yet.</p>
          )}
        </section>

        <section>
          <h2 className="text-xl font-bold text-text-main mb-4">Featured Products</h2>
          {products.length > 0 ? (
            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
              {products.slice(0, 4).map(product => (
                <ProductCard key={product.id} product={product} />
              ))}
            </div>
          ) : (
             <p className="text-text-muted text-sm">No products have been added yet.</p>
          )}
        </section>
      </div>
    </div>
  );
};

export default HomePage;

import React, { useState, useEffect } from 'react';
import { useSearchParams } from 'react-router-dom';
import Header from '../components/Header';
import ProductCard from '../components/ProductCard';
import { useProducts } from '../hooks/useProducts';
import { useCategories } from '../hooks/useCategories';

const ProductsPage: React.FC = () => {
  const { products } = useProducts();
  const { categories } = useCategories();
  const [searchParams, setSearchParams] = useSearchParams();

  const categoryFromUrl = searchParams.get('category');
  const [selectedCategory, setSelectedCategory] = useState<string>(categoryFromUrl || 'All');

  useEffect(() => {
    setSelectedCategory(categoryFromUrl || 'All');
  }, [categoryFromUrl]);

  const handleCategorySelect = (categoryName: string) => {
    setSelectedCategory(categoryName);
    if (categoryName === 'All') {
      setSearchParams({});
    } else {
      setSearchParams({ category: categoryName });
    }
  };

  const filteredProducts = selectedCategory === 'All'
    ? products
    : products.filter(p => p.category === selectedCategory);

  return (
    <div>
      <Header title="Shop All" />
      <div className="p-4">
        <div className="flex space-x-2 overflow-x-auto pb-4 mb-6">
          <button
            onClick={() => handleCategorySelect('All')}
            className={`px-4 py-2 rounded-full text-sm font-semibold transition ${selectedCategory === 'All' ? 'bg-accent text-white' : 'bg-surface text-text-secondary'}`}
          >
            All
          </button>
          {categories.map(category => (
            <button
              key={category.id}
              onClick={() => handleCategorySelect(category.name)}
              className={`px-4 py-2 rounded-full text-sm font-semibold transition flex-shrink-0 ${selectedCategory === category.name ? 'bg-accent text-white' : 'bg-surface text-text-secondary'}`}
            >
              {category.name}
            </button>
          ))}
        </div>

        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
          {filteredProducts.map(product => (
            <ProductCard key={product.id} product={product} />
          ))}
        </div>
      </div>
    </div>
  );
};

export default ProductsPage;

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import { useProducts } from '../hooks/useProducts';
import StarRating from '../components/StarRating';
import { ChevronLeftIcon } from '../components/icons/ChevronLeftIcon';
import { HeartIcon } from '../components/icons/HeartIcon';
import { ShareIcon } from '../components/icons/ShareIcon';
import { useCart } from '../hooks/useCart';
import { useAuth } from '../context/AuthContext';
import { useRecentlyViewed } from '../context/RecentlyViewedContext';
import ProductCard from '../components/ProductCard';
import { useVendors } from '../context/VendorContext';

type Tab = 'description' | 'highlights' | 'specs' | 'shipping';

const ProductDetailPage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { products, getProduct } = useProducts();
  const { addToCart } = useCart();
  const { user, isAuthenticated, addToWishlist, removeFromWishlist, isInWishlist } = useAuth();
  const { addRecentlyViewed } = useRecentlyViewed();
  const { getVendorById } = useVendors();
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const [activeTab, setActiveTab] = useState<Tab>('description');

  const productId = parseInt(id || '');
  const product = getProduct(productId);
  const vendor = product ? getVendorById(product.vendorId) : null;

  // Define tabs and their visibility logic
  const TABS: { id: Tab; label: string; isVisible: boolean }[] = [
    { id: 'description', label: 'Description', isVisible: !!product?.description },
    { id: 'highlights', label: 'Highlights', isVisible: !!product?.highlights && product.highlights.length > 0 },
    { id: 'specs', label: 'Specifications', isVisible: !!product?.specifications && Object.keys(product.specifications).length > 0 },
    { id: 'shipping', label: 'Shipping & Policy', isVisible: true },
  ];

  const visibleTabs = TABS.filter(t => t.isVisible);

  useEffect(() => {
    if (product && isAuthenticated) {
      addRecentlyViewed(product.id);
    }
     // Reset state on component mount/id change
    setCurrentImageIndex(0);
    // Set active tab to the first visible tab
    setActiveTab(visibleTabs[0]?.id || 'description');
  }, [productId, product, isAuthenticated, addRecentlyViewed]);

  if (!product) {
    return <div className="text-center p-8">Product not found</div>;
  }

  const isWishlisted = isInWishlist(product.id);
  const discount = product.originalPrice && product.originalPrice > product.price 
    ? Math.round(((product.originalPrice - product.price) / product.originalPrice) * 100) 
    : 0;

  const similarProducts = products.filter(p => p.category === product.category && p.id !== product.id).slice(0, 4);
  const recentlyViewedProducts = user?.recentlyViewed.map(id => getProduct(id)).filter(p => p && p.id !== product.id) || [];

  const handleToggleWishlist = () => {
    if (!isAuthenticated) navigate('/login'); else isWishlisted ? removeFromWishlist(product.id) : addToWishlist(product.id);
  };

  const handleShare = () => {
    if (navigator.share) {
      navigator.share({
        title: product.name,
        text: `Check out this product: ${product.name}`,
        url: window.location.href,
      }).catch(console.error);
    } else {
      navigator.clipboard.writeText(window.location.href);
      alert('Link copied to clipboard!');
    }
  };

  const handleAddToCart = () => { addToCart(product); };
  const handleBuyNow = () => { addToCart(product); navigate('/checkout'); };

  const renderTabContent = () => {
    switch (activeTab) {
      case 'description': return <p className="text-text-secondary leading-relaxed text-sm">{product.description}</p>;
      case 'highlights': return <ul className="list-disc list-inside text-text-secondary space-y-2 text-sm">{product.highlights?.map((h, i) => <li key={i}>{h}</li>)}</ul>;
      case 'specs': return <div className="text-sm">{Object.entries(product.specifications || {}).map(([key, value]) => (<div key={key} className="flex border-b border-gray-700/50 py-2"><span className="w-1/3 text-text-muted">{key}</span><span className="w-2/3 text-text-main">{value}</span></div>))}</div>;
      case 'shipping': return <div className="text-sm text-text-secondary space-y-4">
          <div className="flex items-center gap-3">
            <img src={vendor?.storeLogo || 'https://picsum.photos/seed/storelogo/100'} alt={vendor?.storeName} className="w-12 h-12 rounded-full object-cover bg-surface" />
            <div>
              <p className="text-text-muted text-xs">Sold By</p>
              <p className="font-semibold text-text-main">{vendor?.storeName || product.sellerInfo || 'VexoKart'}</p>
            </div>
          </div>
          <p><strong className="text-text-secondary">Return Policy:</strong> {product.returnPolicy || 'N/A'}</p>
          <p><strong className="text-text-secondary">Warranty:</strong> {product.warranty || 'N/A'}</p>
        </div>;
      default: return null;
    }
  };

  return (
    <div className="min-h-screen bg-background pb-24">
      {/* Image Gallery */}
      <div className="relative">
        <img src={product.images[currentImageIndex]} alt={product.name} className="w-full h-80 object-cover" />
        <div className="absolute inset-0 bg-gradient-to-t from-background via-transparent to-transparent"></div>
        <button onClick={() => navigate(-1)} className="absolute top-4 left-4 p-2 bg-black/30 rounded-full text-text-main"><ChevronLeftIcon className="h-6 w-6" /></button>
        <div className="absolute top-4 right-4 flex gap-2">
            <button onClick={handleShare} className="p-2 bg-black/30 rounded-full text-text-main"><ShareIcon className="w-6 h-6" /></button>
            <button onClick={handleToggleWishlist} className={`p-2 bg-black/30 rounded-full transition-colors ${isWishlisted ? 'text-red-500' : 'text-text-main'}`}><HeartIcon className="w-6 h-6" fill={isWishlisted ? 'currentColor' : 'none'}/></button>
        </div>
      </div>
      <div className="flex justify-center gap-2 p-2 -mt-10 relative z-10">
        {product.images.map((img, index) => (
            <img key={index} src={img} onClick={() => setCurrentImageIndex(index)} className={`w-16 h-16 rounded-lg object-cover cursor-pointer border-2 transition-all ${currentImageIndex === index ? 'border-accent' : 'border-transparent opacity-60'}`}/>
        ))}
      </div>

      {/* Product Info */}
      <div className="p-4 space-y-4">
        <h1 className="text-2xl font-bold text-text-main">{product.name}</h1>
        <div className="flex items-center"><StarRating rating={product.rating} /><span className="text-xs text-text-muted ml-2">{product.rating} ({product.reviewCount} reviews)</span></div>
        <div className="flex items-baseline gap-2">
          <p className="text-3xl font-bold text-accent">₹{product.price.toFixed(2)}</p>
          {product.originalPrice && product.originalPrice > product.price && <>
            <p className="text-lg text-text-muted line-through opacity-75">₹{product.originalPrice.toFixed(2)}</p>
            <span className="text-sm font-bold text-green-400 bg-green-900/50 px-2 py-0.5 rounded-md">{discount}% OFF</span>
          </>}
        </div>
        {product.stock !== undefined && product.stock > 0 && product.stock < 10 && <p className="text-sm font-semibold text-orange-400">Hurry, only {product.stock} left!</p>}

        {/* Info Tabs */}
        <div className="pt-2">
          <div className="flex border-b border-gray-700 mb-4 overflow-x-auto">
            {visibleTabs.map(tab => (
              <button key={tab.id} onClick={() => setActiveTab(tab.id)} className={`flex-shrink-0 px-4 py-2 text-sm font-semibold capitalize transition-colors ${activeTab === tab.id ? 'text-accent border-b-2 border-accent' : 'text-text-muted'}`}>{tab.label}</button>
            ))}
          </div>
          <div className="min-h-[100px]">{renderTabContent()}</div>
        </div>

        {/* Similar Products */}
        {similarProducts.length > 0 && <section>
          <h2 className="text-xl font-bold text-text-main mb-4">You Might Also Like</h2>
          <div className="grid grid-cols-2 gap-4">{similarProducts.map(p => <ProductCard key={p.id} product={p} />)}</div>
        </section>}

        {/* Recently Viewed */}
        {recentlyViewedProducts.length > 0 && <section>
          <h2 className="text-xl font-bold text-text-main mb-4">Recently Viewed</h2>
          <div className="grid grid-cols-2 gap-4">{recentlyViewedProducts.map(p => <ProductCard key={p.id} product={p} />)}</div>
        </section>}

      </div>

      {/* Sticky Footer */}
      <div className="fixed bottom-0 left-0 right-0 p-2 bg-surface/90 backdrop-blur-md border-t border-gray-700/50 flex items-center gap-2">
         <button onClick={handleAddToCart} className="w-1/2 bg-white/10 border border-accent text-accent font-bold py-3 rounded-xl shadow-lg">Add to Cart</button>
         <button onClick={handleBuyNow} className="w-1/2 bg-gradient-to-r from-accent to-accent-secondary text-white font-bold py-3 rounded-xl shadow-lg">Buy Now</button>
      </div>
    </div>
  );
};

export default ProductDetailPage;

