import React from 'react';
import { useNavigate } from 'react-router-dom';
import { useProducts } from '../../hooks/useProducts';
import GlassmorphicCard from '../../components/GlassmorphicCard';
import { useVendors } from '../../context/VendorContext';
import { Product } from '../../types';

const getStatusPill = (status: Product['status']) => {
    switch(status) {
        case 'live': return 'text-green-400 bg-green-900/50 border-green-600/50';
        case 'pending_approval': return 'text-yellow-400 bg-yellow-900/50 border-yellow-600/50';
        case 'rejected': return 'text-red-400 bg-red-900/50 border-red-600/50';
        case 'archived': return 'text-gray-400 bg-gray-700/50 border-gray-600/50';
        default: return '';
    }
}

const AdminProductsPage: React.FC = () => {
  const { products, deleteProduct } = useProducts();
  const { getVendorById } = useVendors();
  const navigate = useNavigate();

  return (
    <div>
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-3xl font-bold text-text-main">All Products</h1>
      </div>

      <GlassmorphicCard>
        <div className="overflow-x-auto">
            <table className="w-full text-left">
            <thead>
              <tr className="border-b border-gray-700 text-sm text-text-muted">
                <th className="p-4 font-semibold">Name</th>
                <th className="p-4 font-semibold">Vendor</th>
                <th className="p-4 font-semibold">Category</th>
                <th className="p-4 font-semibold">Price</th>
                <th className="p-4 font-semibold">Status</th>
                <th className="p-4 font-semibold">Actions</th>
              </tr>
            </thead>
            <tbody>
              {products.map(product => {
                const vendor = getVendorById(product.vendorId);
                const vendorName = vendor ? vendor.storeName : (product.vendorId === 'vexokart_internal' ? 'VexoKart' : 'Unknown');

                return (
                    <tr key={product.id} className="border-b border-gray-800 hover:bg-surface/50">
                    <td className="p-4 text-text-main font-semibold">{product.name}</td>
                    <td className="p-4 text-sm text-cyan-400">{vendorName}</td>
                    <td className="p-4 text-sm">{product.category}</td>
                    <td className="p-4 text-sm">₹{product.price.toFixed(2)}</td>
                    <td className="p-4">
                        <span className={`px-2 py-1 rounded-full text-xs font-bold border ${getStatusPill(product.status)}`}>
                            {product.status.replace('_', ' ')}
                        </span>
                    </td>
                    <td className="p-4 space-x-2 text-sm">
                        <button onClick={() => navigate(`/admin/products/edit/${product.id}`)} className="text-accent font-semibold py-1 px-3 rounded-md hover:bg-accent/20">Manage</button>
                        <button onClick={() => deleteProduct(product.id)} className="text-red-400 font-semibold py-1 px-3 rounded-md hover:bg-red-500/20">Delete</button>
                    </td>
                    </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </GlassmorphicCard>
    </div>
  );
};

export default AdminProductsPage;

import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useProducts } from '../../hooks/useProducts';
import { useCategories } from '../../hooks/useCategories';
import GlassmorphicCard from '../../components/GlassmorphicCard';
import { Product } from '../../types';

const AdminProductFormPage: React.FC = () => {
  const { id } = useParams<{ id?: string }>();
  const navigate = useNavigate();
  const { getProduct, addProduct, updateProduct } = useProducts();
  const { categories } = useCategories();

  const isEditing = id !== undefined;

  // FIX: Added missing vendorId and status fields to the initial state to match the Product type.
  const [formData, setFormData] = useState<Omit<Product, 'id' | 'reviews' | 'rating' | 'reviewCount'>>({
    name: '',
    category: categories[0]?.name || '',
    price: 0,
    originalPrice: 0,
    images: [],
    description: '',
    vendorId: 'vexokart_internal',
    status: 'live',
    highlights: [],
    stock: 10,
    specifications: {},
    sellerInfo: 'VexoKart Direct',
    returnPolicy: '30-Day Money Back Guarantee',
    warranty: '1 Year Standard Warranty',
    videoUrl: ''
  });

  const inputClasses = "w-full mt-1 bg-surface text-text-main border border-gray-600 rounded-lg p-3 transition focus:outline-none focus:border-accent focus:ring-2 focus:ring-accent/50";

  useEffect(() => {
    if (isEditing) {
      const productToEdit = getProduct(parseInt(id));
      if (productToEdit) {
        // FIX: Ensured all required fields, including vendorId and status, are set when editing a product.
        setFormData({
            name: productToEdit.name,
            category: productToEdit.category,
            price: productToEdit.price,
            originalPrice: productToEdit.originalPrice,
            images: productToEdit.images,
            description: productToEdit.description,
            vendorId: productToEdit.vendorId,
            status: productToEdit.status,
            highlights: productToEdit.highlights || [],
            stock: productToEdit.stock || 0,
            specifications: productToEdit.specifications || {},
            sellerInfo: productToEdit.sellerInfo,
            returnPolicy: productToEdit.returnPolicy,
            warranty: productToEdit.warranty,
            videoUrl: productToEdit.videoUrl
        });
      }
    } else {
        if (categories.length > 0) {
            setFormData(prev => ({...prev, category: categories[0].name}));
        }
    }
  }, [id, isEditing, getProduct, categories]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: ['price', 'originalPrice', 'stock'].includes(name) ? parseFloat(value) || 0 : value }));
  };

  const handleArrayChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
      const { name, value } = e.target;
      setFormData(prev => ({...prev, [name]: value.split('\n').map(s => s.trim()).filter(Boolean)}));
  }

  const handleSpecChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const specs: { [key: string]: string } = {};
    e.target.value.split('\n').forEach(line => {
      const parts = line.split(':');
      if (parts.length === 2) {
        specs[parts[0].trim()] = parts[1].trim();
      }
    });
    setFormData(prev => ({ ...prev, specifications: specs }));
  };

  const specString = Object.entries(formData.specifications || {}).map(([key, value]) => `${key}: ${value}`).join('\n');

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
        Array.from(e.target.files).forEach(file => {
            const reader = new FileReader();
            reader.onloadend = () => {
                setFormData(prev => ({
                    ...prev,
                    images: [...prev.images, reader.result as string]
                }));
            };
            reader.readAsDataURL(file);
        });
    }
  };

  const removeImage = (index: number) => {
    setFormData(prev => ({ ...prev, images: prev.images.filter((_, i) => i !== index) }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if(formData.images.length === 0) {
        alert("Please upload at least one image for the product.");
        return;
    }
    if (isEditing) {
      const existingProduct = getProduct(parseInt(id));
      const updatedData = { ...existingProduct, ...formData, id: parseInt(id) } as Product;
      updateProduct(updatedData);
    } else {
      // FIX: Correctly call addProduct by destructuring the 'status' property (which is set by the context)
      // and passing the 'bySuperAdmin' flag.
      // eslint-disable-next-line @typescript-eslint/no-unused-vars
      const { status, ...productData } = formData;
      addProduct(productData, true);
    }
    navigate('/admin/products');
  };

  return (
    <div>
      <h1 className="text-3xl font-bold text-text-main mb-6">{isEditing ? 'Edit Product' : 'Add New Product'}</h1>
      <GlassmorphicCard className="p-6">
        <form onSubmit={handleSubmit} className="space-y-4">
            <div><label className="block text-sm font-medium text-text-secondary">Name</label><input type="text" name="name" value={formData.name} onChange={handleChange} required className={inputClasses} /></div>
            <div><label className="block text-sm font-medium text-text-secondary">Category</label><select name="category" value={formData.category} onChange={handleChange} className={inputClasses}>{categories.map(c => <option key={c.id} value={c.name}>{c.name}</option>)}</select></div>
            <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                <div><label className="block text-sm font-medium text-text-secondary">Price (₹)</label><input type="number" name="price" value={formData.price} onChange={handleChange} required className={inputClasses} /></div>
                <div><label className="block text-sm font-medium text-text-secondary">Original Price (₹)</label><input type="number" name="originalPrice" value={formData.originalPrice} onChange={handleChange} className={inputClasses} /></div>
                 <div><label className="block text-sm font-medium text-text-secondary">Stock</label><input type="number" name="stock" value={formData.stock} onChange={handleChange} required className={inputClasses} /></div>
            </div>
            <div><label className="block text-sm font-medium text-text-secondary">Description</label><textarea name="description" value={formData.description} onChange={handleChange} required rows={4} className={inputClasses}></textarea></div>

            <div>
                <label className="block text-sm font-medium text-text-secondary">Images</label>
                <div className="mt-2"><input type="file" id="imageUpload" multiple accept="image/*" onChange={handleImageChange} className="hidden" /><label htmlFor="imageUpload" className="cursor-pointer bg-surface text-text-main font-semibold py-2 px-4 rounded-lg border border-gray-600 hover:bg-gray-700">Choose Files</label></div>
                <div className="mt-4 grid grid-cols-3 sm:grid-cols-4 md:grid-cols-5 gap-4">
                    {formData.images.map((image, index) => (
                        <div key={index} className="relative"><img src={image} alt={`preview ${index}`} className="w-full h-24 object-cover rounded-lg"/><button type="button" onClick={() => removeImage(index)} className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full w-6 h-6 flex items-center justify-center text-xs font-bold">&times;</button></div>
                    ))}
                </div>
            </div>

            <div><label className="block text-sm font-medium text-text-secondary">Highlights (one per line)</label><textarea name="highlights" value={formData.highlights?.join('\n')} onChange={handleArrayChange} rows={4} className={inputClasses}></textarea></div>
            <div><label className="block text-sm font-medium text-text-secondary">Specifications (format: Key: Value)</label><textarea name="specifications" value={specString} onChange={handleSpecChange} rows={5} className={inputClasses} placeholder="e.g.&#10;Color: Black&#10;Material: Aluminum"></textarea></div>
            <div><label className="block text-sm font-medium text-text-secondary">Video URL (optional)</label><input type="url" name="videoUrl" value={formData.videoUrl} onChange={handleChange} className={inputClasses} /></div>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <div><label className="block text-sm font-medium text-text-secondary">Seller Info</label><input type="text" name="sellerInfo" value={formData.sellerInfo} onChange={handleChange} className={inputClasses} /></div>
              <div><label className="block text-sm font-medium text-text-secondary">Return Policy</label><input type="text" name="returnPolicy" value={formData.returnPolicy} onChange={handleChange} className={inputClasses} /></div>
              <div><label className="block text-sm font-medium text-text-secondary">Warranty</label><input type="text" name="warranty" value={formData.warranty} onChange={handleChange} className={inputClasses} /></div>
            </div>
            <div className="flex justify-end gap-4 pt-4">
                <button type="button" onClick={() => navigate('/admin/products')} className="bg-gray-600/50 text-white font-bold py-2 px-4 rounded-lg hover:bg-gray-500/50">Cancel</button>
                <button type="submit" className="bg-accent text-white font-bold py-2 px-4 rounded-lg hover:brightness-110">{isEditing ? 'Update Product' : 'Create Product'}</button>
            </div>
        </form>
      </GlassmorphicCard>
    </div>
  );
};

export default AdminProductFormPage;

import React, { useState } from 'react';
import { useOrders } from '../../context/OrderContext';
import { Order, OrderStatus } from '../../types';
import GlassmorphicCard from '../../components/GlassmorphicCard';
import ShippingDetailsModal from '../../components/admin/ShippingDetailsModal';
import OrderStatusHistoryModal from '../../components/admin/OrderStatusHistoryModal';

const ALL_STATUSES: OrderStatus[] = ['Placed', 'Confirmed', 'Packed', 'Shipped', 'Out for Delivery', 'Delivered', 'Cancelled'];

const AdminOrdersPage: React.FC = () => {
  const { orders, updateOrderStatus } = useOrders();
  const [selectedOrder, setSelectedOrder] = useState<Order | null>(null);
  const [isShippingModalOpen, setShippingModalOpen] = useState(false);
  const [isHistoryModalOpen, setHistoryModalOpen] = useState(false);

  const handleStatusChange = (order: Order, status: OrderStatus) => {
    if (status === 'Shipped' && !order.trackingId) {
      setSelectedOrder(order);
      setShippingModalOpen(true);
    } else {
      updateOrderStatus(order.id, status);
    }
  };

  const handleShippingSubmit = (courierName: string, trackingId: string) => {
    if (selectedOrder) {
      updateOrderStatus(selectedOrder.id, 'Shipped', { courierName, trackingId });
    }
    setShippingModalOpen(false);
    setSelectedOrder(null);
  };

  const openHistoryModal = (order: Order) => {
    setSelectedOrder(order);
    setHistoryModalOpen(true);
  }

  const getStatusColor = (status: OrderStatus) => {
      switch(status) {
          case 'Placed': return 'text-gray-300 bg-gray-700/50 border-gray-600/50';
          case 'Confirmed': return 'text-cyan-400 bg-cyan-900/50 border-cyan-600/50';
          case 'Packed': return 'text-indigo-400 bg-indigo-900/50 border-indigo-600/50';
          case 'Shipped': return 'text-blue-400 bg-blue-900/50 border-blue-600/50';
          case 'Out for Delivery': return 'text-yellow-400 bg-yellow-900/50 border-yellow-600/50';
          case 'Delivered': return 'text-green-400 bg-green-900/50 border-green-600/50';
          case 'Cancelled': return 'text-red-400 bg-red-900/50 border-red-600/50';
          default: return 'text-gray-400 bg-gray-700/50 border-gray-600/50';
      }
  }

  return (
    <div>
      {isShippingModalOpen && selectedOrder && (
        <ShippingDetailsModal
          onClose={() => setShippingModalOpen(false)}
          onSubmit={handleShippingSubmit}
        />
      )}
      {isHistoryModalOpen && selectedOrder && (
        <OrderStatusHistoryModal
          history={selectedOrder.statusHistory}
          onClose={() => setHistoryModalOpen(false)}
        />
      )}
      <h1 className="text-3xl font-bold text-text-main mb-6">Manage Orders</h1>
      <GlassmorphicCard>
        <div className="overflow-x-auto">
            <table className="w-full text-left text-sm">
            <thead>
              <tr className="border-b border-gray-700 text-text-muted">
                <th className="p-4 font-semibold">Order ID</th>
                <th className="p-4 font-semibold">Date</th>
                <th className="p-4 font-semibold">Customer</th>
                <th className="p-4 font-semibold">Total</th>
                <th className="p-4 font-semibold">Status</th>
                <th className="p-4 font-semibold">Update Status</th>
                <th className="p-4 font-semibold">History</th>
              </tr>
            </thead>
            <tbody>
              {orders.map(order => (
                <tr key={order.id} className="border-b border-gray-800 hover:bg-surface/50">
                  <td className="p-4 text-text-main font-mono">#{order.id}</td>
                  <td className="p-4">{new Date(order.date).toLocaleDateString()}</td>
                  <td className="p-4">{order.userEmail}</td>
                  <td className="p-4 font-semibold">₹{order.total.toFixed(2)}</td>
                  <td className="p-4">
                    <span className={`px-2 py-1 rounded-full text-xs font-bold border ${getStatusColor(order.status)}`}>
                        {order.status}
                    </span>
                  </td>
                  <td className="p-4">
                     <select 
                        value={order.status} 
                        onChange={(e) => handleStatusChange(order, e.target.value as OrderStatus)}
                        className="bg-surface border border-gray-600 rounded-md p-1.5 text-text-main focus:ring-accent focus:border-accent"
                     >
                        {ALL_STATUSES.map(status => (
                            <option key={status} value={status}>{status}</option>
                        ))}
                    </select>
                  </td>
                   <td className="p-4">
                    <button onClick={() => openHistoryModal(order)} className="text-accent hover:underline text-xs font-semibold">
                      View History
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          {orders.length === 0 && <p className="text-center p-8 text-text-muted">No orders have been placed yet.</p>}
        </div>
      </GlassmorphicCard>
    </div>
  );
};

export default AdminOrdersPage;

import React, { useState } from 'react';
import { useAuth } from '../../context/AuthContext';
import GlassmorphicCard from '../../components/GlassmorphicCard';
import UserFormModal from '../../components/admin/UserFormModal';
import { User } from '../../types';

const AdminUsersPage: React.FC = () => {
  const { users, deleteUser, addUser } = useAuth();
  const [isModalOpen, setModalOpen] = useState(false);

  const handleDelete = (email: string, name: string) => {
    if (window.confirm(`Are you sure you want to delete user "${name}" (${email})? This action cannot be undone.`)) {
        deleteUser(email);
    }
  }

  const handleCreateUser = async (userData: { name: string; email: string; pass: string; role: User['role'] }) => {
    try {
        await addUser(userData);
        setModalOpen(false);
    } catch (error: any) {
        alert(`Error: ${error.message}`);
    }
  }

  return (
    <div>
      {isModalOpen && <UserFormModal onClose={() => setModalOpen(false)} onSubmit={handleCreateUser} />}
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-3xl font-bold text-text-main">Manage Users</h1>
        <button onClick={() => setModalOpen(true)} className="bg-accent text-white font-bold py-2 px-4 rounded-lg hover:brightness-110 transform hover:scale-105">
          Create User
        </button>
      </div>

      <GlassmorphicCard>
        <div className="overflow-x-auto">
            <table className="w-full text-left text-sm">
            <thead>
              <tr className="border-b border-gray-700 text-text-muted">
                <th className="p-4 font-semibold">Name</th>
                <th className="p-4 font-semibold">Email</th>
                <th className="p-4 font-semibold">Role</th>
                <th className="p-4 font-semibold">Actions</th>
              </tr>
            </thead>
            <tbody>
              {users.map(user => (
                <tr key={user.email} className="border-b border-gray-800 hover:bg-surface/50">
                  <td className="p-4 text-text-main font-medium">{user.name}</td>
                  <td className="p-4">{user.email}</td>
                  <td className="p-4">
                    <span className={`px-2 py-1 rounded-full text-xs font-bold border ${user.role === 'SUPER_ADMIN' ? 'text-yellow-400 bg-yellow-900/50 border-yellow-600/50' : user.role === 'VENDOR' ? 'text-cyan-400 bg-cyan-900/50 border-cyan-600/50' : 'text-text-secondary bg-gray-700/50 border-gray-600/50'}`}>
                        {user.role}
                    </span>
                  </td>
                  <td className="p-4">
                    {user.email !== 'admin@vexokart.com' ? (
                        <button onClick={() => handleDelete(user.email, user.name)} className="text-red-400 font-semibold py-1 px-3 rounded-md hover:bg-red-500/20">Delete</button>
                    ) : (
                        <span className="text-text-muted text-xs">Cannot delete</span>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          {users.length === 0 && <p className="text-center p-8 text-text-muted">No users found.</p>}
        </div>
      </GlassmorphicCard>
    </div>
  );
};

export default AdminUsersPage;

