          {filteredVendors.length === 0 && (
            <p className="text-center p-8 text-text-muted">
                {searchTerm ? `No vendors found for "${searchTerm}".` : 'No vendors have registered yet.'}
            </p>
          )}
        </div>
      </GlassmorphicCard>
    </div>
  );
};

