  const handleSpecChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const specs: { [key: string]: string } = {};
    e.target.value.split('\n').forEach(line => {
      const parts = line.split(':');
      if (parts.length === 2) {
        specs[parts[0].trim()] = parts[1].trim();
      }
    });
    setFormData(prev => ({ ...prev, specifications: specs }));
  };

  const specString = Object.entries(formData.specifications || {}).map(([key, value]) => `${key}: ${value}`).join('\n');

  // FIX: Refactored to use a for...of loop to correctly infer the type of 'file' as File, which is a Blob.
  // The previous forEach loop caused a type error where 'file' was inferred as 'unknown'.
  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      for (const file of e.target.files) {
        const reader = new FileReader();
        reader.onloadend = () => {
          setFormData(prev => ({
            ...prev,
            images: [...prev.images, reader.result as string]
          }));
        };
        reader.readAsDataURL(file);
      }
    }
  };

  const removeImage = (index: number) => {
    setFormData(prev => ({ ...prev, images: prev.images.filter((_, i) => i !== index) }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if(formData.images.length === 0) {
        alert("Please upload at least one image for the product.");
        return;
    }
    if (isEditing) {
      const existingProduct = getProduct(parseInt(id));
      const updatedData = { ...existingProduct, ...formData, id: parseInt(id) } as Product;
      updateProduct(updatedData);
    } else {
      // FIX: Correctly call addProduct by destructuring the 'status' property (which is set by the context)
      // and passing the 'bySuperAdmin' flag.
      // eslint-disable-next-line @typescript-eslint/no-unused-vars
      const { status, ...productData } = formData;
      addProduct(productData, true);
    }
    navigate('/admin/products');
  };

  return (
    <div>
      <h1 className="text-3xl font-bold text-text-main mb-6">{isEditing ? 'Edit Product' : 'Add New Product'}</h1>
      <GlassmorphicCard className="p-6">
        <form onSubmit={handleSubmit} className="space-y-4">
            <div><label className="block text-sm font-medium text-text-secondary">Name</label><input type="text" name="name" value={formData.name} onChange={handleChange} required className={inputClasses} /></div>
            <div><label className="block text-sm font-medium text-text-secondary">Category</label><select name="category" value={formData.category} onChange={handleChange} className={inputClasses}>{categories.map(c => <option key={c.id} value={c.name}>{c.name}</option>)}</select></div>
            <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                <div><label className="block text-sm font-medium text-text-secondary">Price (₹)</label><input type="number" name="price" value={formData.price} onChange={handleChange} required className={inputClasses} /></div>
                <div><label className="block text-sm font-medium text-text-secondary">Original Price (₹)</label><input type="number" name="originalPrice" value={formData.originalPrice} onChange={handleChange} className={inputClasses} /></div>
                 <div><label className="block text-sm font-medium text-text-secondary">Stock</label><input type="number" name="stock" value={formData.stock} onChange={handleChange} required className={inputClasses} /></div>
            </div>
            <div><label className="block text-sm font-medium text-text-secondary">Description</label><textarea name="description" value={formData.description} onChange={handleChange} required rows={4} className={inputClasses}></textarea></div>

            <div>
                <label className="block text-sm font-medium text-text-secondary">Images</label>
                <div className="mt-2"><input type="file" id="imageUpload" multiple accept="image/*" onChange={handleImageChange} className="hidden" /><label htmlFor="imageUpload" className="cursor-pointer bg-surface text-text-main font-semibold py-2 px-4 rounded-lg border border-gray-600 hover:bg-gray-700">Choose Files</label></div>
                <div className="mt-4 grid grid-cols-3 sm:grid-cols-4 md:grid-cols-5 gap-4">
                    {formData.images.map((image, index) => (
                        <div key={index} className="relative"><img src={image} alt={`preview ${index}`} className="w-full h-24 object-cover rounded-lg"/><button type="button" onClick={() => removeImage(index)} className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full w-6 h-6 flex items-center justify-center text-xs font-bold">&times;</button></div>
                    ))}
                </div>
            </div>

            <div><label className="block text-sm font-medium text-text-secondary">Highlights (one per line)</label><textarea name="highlights" value={formData.highlights?.join('\n')} onChange={handleArrayChange} rows={4} className={inputClasses}></textarea></div>
            <div><label className="block text-sm font-medium text-text-secondary">Specifications (format: Key: Value)</label><textarea name="specifications" value={specString} onChange={handleSpecChange} rows={5} className={inputClasses} placeholder="e.g.&#10;Color: Black&#10;Material: Aluminum"></textarea></div>
            <div><label className="block text-sm font-medium text-text-secondary">Video URL (optional)</label><input type="url" name="videoUrl" value={formData.videoUrl} onChange={handleChange} className={inputClasses} /></div>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <div><label className="block text-sm font-medium text-text-secondary">Seller Info</label><input type="text" name="sellerInfo" value={formData.sellerInfo} onChange={handleChange} className={inputClasses} /></div>
              <div><label className="block text-sm font-medium text-text-secondary">Return Policy</label><input type="text" name="returnPolicy" value={formData.returnPolicy} onChange={handleChange} className={inputClasses} /></div>
              <div><label className="block text-sm font-medium text-text-secondary">Warranty</label><input type="text" name="warranty" value={formData.warranty} onChange={handleChange} className={inputClasses} /></div>
            </div>
            <div className="flex justify-end gap-4 pt-4">
                <button type="button" onClick={() => navigate('/admin/products')} className="bg-gray-600/50 text-white font-bold py-2 px-4 rounded-lg hover:bg-gray-500/50">Cancel</button>
                <button type="submit" className="bg-accent text-white font-bold py-2 px-4 rounded-lg hover:brightness-110">{isEditing ? 'Update Product' : 'Create Product'}</button>
            </div>
        </form>
      </GlassmorphicCard>
    </div>
  );
};

export default AdminProductFormPage;

import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useProducts } from '../../hooks/useProducts';
import { useCategories } from '../../hooks/useCategories';
import GlassmorphicCard from '../../components/GlassmorphicCard';
import { Product } from '../../types';
import { useAuth } from '../../context/AuthContext';
import { useVendors } from '../../context/VendorContext';

const VendorProductFormPage: React.FC = () => {
  const { id } = useParams<{ id?: string }>();
  const navigate = useNavigate();
  const { getProduct, addProduct, updateProduct } = useProducts();
  const { categories } = useCategories();
  const { user } = useAuth();
  const { getVendorByUserId } = useVendors();

  const vendor = user ? getVendorByUserId(user.email) : null;
  const isEditing = id !== undefined;

  const [formData, setFormData] = useState<Omit<Product, 'id' | 'reviews' | 'rating' | 'reviewCount' | 'status' | 'vendorId'>>({
    name: '',
    category: categories[0]?.name || '',
    price: 0,
    originalPrice: 0,
    images: [],
    description: '',
    highlights: [],
    stock: 10,
    specifications: {},
    sellerInfo: vendor?.storeName || '',
    returnPolicy: '30-Day Money Back Guarantee',
    warranty: '1 Year Standard Warranty',
    videoUrl: ''
  });

  const inputClasses = "w-full mt-1 bg-surface text-text-main border border-gray-600 rounded-lg p-3 transition focus:outline-none focus:border-accent focus:ring-2 focus:ring-accent/50";

  useEffect(() => {
    if (isEditing) {
      const productToEdit = getProduct(parseInt(id));
      // Security check: ensure vendor owns this product
      if (productToEdit && vendor && productToEdit.vendorId === vendor.id) {
        setFormData({ ...productToEdit });
      } else {
        // Redirect if trying to edit a product they don't own
        navigate('/vendor/products');
      }
    } else {
        if (categories.length > 0) {
            setFormData(prev => ({...prev, category: categories[0].name, sellerInfo: vendor?.storeName || ''}));
        }
    }
  }, [id, isEditing, getProduct, categories, vendor, navigate]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: ['price', 'originalPrice', 'stock'].includes(name) ? parseFloat(value) || 0 : value }));
  };

  const handleArrayChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
      const { name, value } = e.target;
      setFormData(prev => ({...prev, [name]: value.split('\n').map(s => s.trim()).filter(Boolean)}));
  }

  const handleSpecChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const specs: { [key: string]: string } = {};
    e.target.value.split('\n').forEach(line => {
      const parts = line.split(':');
      if (parts.length === 2) {
        specs[parts[0].trim()] = parts[1].trim();
      }
    });
    setFormData(prev => ({ ...prev, specifications: specs }));
  };

  const specString = Object.entries(formData.specifications || {}).map(([key, value]) => `${key}: ${value}`).join('\n');

  // FIX: Refactored to use a for...of loop to correctly infer the type of 'file' as File, which is a Blob.
  // The previous forEach loop caused a type error where 'file' was inferred as 'unknown'.
  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      for (const file of e.target.files) {
        const reader = new FileReader();
        reader.onloadend = () => {
            setFormData(prev => ({
                ...prev,
                images: [...prev.images, reader.result as string]
            }));
        };
        reader.readAsDataURL(file);
      }
    }
  };

  const removeImage = (index: number) => {
    setFormData(prev => ({ ...prev, images: prev.images.filter((_, i) => i !== index) }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!vendor) {
        alert("Vendor information not found. Cannot save product.");
        return;
    }
    if(formData.images.length === 0) {
        alert("Please upload at least one image for the product.");
        return;
    }
    if (isEditing) {
      const existingProduct = getProduct(parseInt(id));
      const updatedData: Product = { ...existingProduct!, ...formData, id: parseInt(id) };
      updateProduct(updatedData);
    } else {
      addProduct({ ...formData, vendorId: vendor.id });
    }
    navigate('/vendor/products');
  };

  return (
    <div>
      <h1 className="text-3xl font-bold text-text-main mb-6">{isEditing ? 'Edit Product' : 'Add New Product'}</h1>
      <GlassmorphicCard className="p-6">
        <form onSubmit={handleSubmit} className="space-y-4">
            <div><label className="block text-sm font-medium text-text-secondary">Name</label><input type="text" name="name" value={formData.name} onChange={handleChange} required className={inputClasses} /></div>
            <div><label className="block text-sm font-medium text-text-secondary">Category</label><select name="category" value={formData.category} onChange={handleChange} className={inputClasses}>{categories.map(c => <option key={c.id} value={c.name}>{c.name}</option>)}</select></div>
            <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                <div><label className="block text-sm font-medium text-text-secondary">Price (₹)</label><input type="number" name="price" value={formData.price} onChange={handleChange} required className={inputClasses} /></div>
                <div><label className="block text-sm font-medium text-text-secondary">Original Price (₹)</label><input type="number" name="originalPrice" value={formData.originalPrice} onChange={handleChange} className={inputClasses} /></div>
                 <div><label className="block text-sm font-medium text-text-secondary">Stock</label><input type="number" name="stock" value={formData.stock} onChange={handleChange} required className={inputClasses} /></div>
            </div>
            <div><label className="block text-sm font-medium text-text-secondary">Description</label><textarea name="description" value={formData.description} onChange={handleChange} required rows={4} className={inputClasses}></textarea></div>
            <div>
                <label className="block text-sm font-medium text-text-secondary">Images</label>
                <div className="mt-2"><input type="file" id="imageUpload" multiple accept="image/*" onChange={handleImageChange} className="hidden" /><label htmlFor="imageUpload" className="cursor-pointer bg-surface text-text-main font-semibold py-2 px-4 rounded-lg border border-gray-600 hover:bg-gray-700">Choose Files</label></div>
                <div className="mt-4 grid grid-cols-3 sm:grid-cols-4 md:grid-cols-5 gap-4">
                    {formData.images.map((image, index) => (
                        <div key={index} className="relative"><img src={image} alt={`preview ${index}`} className="w-full h-24 object-cover rounded-lg"/><button type="button" onClick={() => removeImage(index)} className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full w-6 h-6 flex items-center justify-center text-xs font-bold">&times;</button></div>
                    ))}
                </div>
            </div>
            <div><label className="block text-sm font-medium text-text-secondary">Highlights (one per line)</label><textarea name="highlights" value={formData.highlights?.join('\n')} onChange={handleArrayChange} rows={4} className={inputClasses}></textarea></div>
            <div><label className="block text-sm font-medium text-text-secondary">Specifications (format: Key: Value)</label><textarea name="specifications" value={specString} onChange={handleSpecChange} rows={5} className={inputClasses} placeholder="e.g.&#10;Color: Black&#10;Material: Aluminum"></textarea></div>
            <div className="flex justify-end gap-4 pt-4">
                <button type="button" onClick={() => navigate('/vendor/products')} className="bg-gray-600/50 text-white font-bold py-2 px-4 rounded-lg hover:bg-gray-500/50">Cancel</button>
                <button type="submit" className="bg-accent text-white font-bold py-2 px-4 rounded-lg hover:brightness-110">{isEditing ? 'Update Product' : 'Submit for Approval'}</button>
            </div>
        </form>
      </GlassmorphicCard>
    </div>
  );
};

export default VendorProductFormPage;

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import { useProducts } from '../hooks/useProducts';
import StarRating from '../components/StarRating';
import { ChevronLeftIcon } from '../components/icons/ChevronLeftIcon';
import { HeartIcon } from '../components/icons/HeartIcon';
import { ShareIcon } from '../components/icons/ShareIcon';
import { useCart } from '../hooks/useCart';
import { useAuth } from '../context/AuthContext';
import { useRecentlyViewed } from '../context/RecentlyViewedContext';
import ProductCard from '../components/ProductCard';
import { useVendors } from '../context/VendorContext';

type Tab = 'description' | 'highlights' | 'specs' | 'shipping';

const ProductDetailPage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { products, getProduct } = useProducts();
  const { addToCart } = useCart();
  const { user, isAuthenticated, addToWishlist, removeFromWishlist, isInWishlist } = useAuth();
  const { addRecentlyViewed } = useRecentlyViewed();
  const { getVendorById } = useVendors();
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const [activeTab, setActiveTab] = useState<Tab>('description');
  const [showVideoModal, setShowVideoModal] = useState(false);

  const productId = parseInt(id || '');
  const product = getProduct(productId);
  const vendor = product ? getVendorById(product.vendorId) : null;

  // Define tabs and their visibility logic
  const TABS: { id: Tab; label: string; isVisible: boolean }[] = [
    { id: 'description', label: 'Description', isVisible: !!product?.description },
    { id: 'highlights', label: 'Highlights', isVisible: !!product?.highlights && product.highlights.length > 0 },
    { id: 'specs', label: 'Specifications', isVisible: !!product?.specifications && Object.keys(product.specifications).length > 0 },
    { id: 'shipping', label: 'Shipping & Policy', isVisible: true },
  ];

  const visibleTabs = TABS.filter(t => t.isVisible);

  useEffect(() => {
    if (product && isAuthenticated) {
      addRecentlyViewed(product.id);
    }
     // Reset state on component mount/id change
    setCurrentImageIndex(0);
    // Set active tab to the first visible tab
    setActiveTab(visibleTabs[0]?.id || 'description');
  }, [productId, product, isAuthenticated, addRecentlyViewed]);

  if (!product) {
    return <div className="text-center p-8 text-text-main">Product not found</div>;
  }

  const isWishlisted = isInWishlist(product.id);
  const discount = product.originalPrice && product.originalPrice > product.price 
    ? Math.round(((product.originalPrice - product.price) / product.originalPrice) * 100) 
    : 0;

  const similarProducts = products.filter(p => p.category === product.category && p.id !== product.id).slice(0, 4);
  const recentlyViewedProducts = user?.recentlyViewed.map(id => getProduct(id)).filter(p => p && p.id !== product.id) || [];

  const handleToggleWishlist = () => {
    if (!isAuthenticated) navigate('/login'); else isWishlisted ? removeFromWishlist(product.id) : addToWishlist(product.id);
  };

  const handleShare = () => {
    if (navigator.share) {
      navigator.share({
        title: product.name,
        text: `Check out this product: ${product.name}`,
        url: window.location.href,
      }).catch(console.error);
    } else {
      navigator.clipboard.writeText(window.location.href);
      alert('Link copied to clipboard!');
    }
  };

  const handleAddToCart = () => { addToCart(product); };
  const handleBuyNow = () => { addToCart(product); navigate('/checkout'); };

  const getEmbedUrl = (url: string) => {
    if (!url) return '';
    if (url.includes('youtube.com') || url.includes('youtu.be')) {
        const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|\&v=)([^#\&\?]*).*/;
        const match = url.match(regExp);
        return (match && match[2].length === 11) ? `https://www.youtube.com/embed/${match[2]}?autoplay=1` : url;
    }
    return url;
  };

  const renderTabContent = () => {
    switch (activeTab) {
      case 'description': return <p className="text-text-secondary leading-relaxed text-sm">{product.description}</p>;
      case 'highlights': return <ul className="list-disc list-inside text-text-secondary space-y-2 text-sm">{product.highlights?.map((h, i) => <li key={i}>{h}</li>)}</ul>;
      case 'specs': return <div className="text-sm">{Object.entries(product.specifications || {}).map(([key, value]) => (<div key={key} className="flex border-b border-gray-700/50 py-2"><span className="w-1/3 text-text-muted">{key}</span><span className="w-2/3 text-text-main">{value}</span></div>))}</div>;
      case 'shipping': return <div className="text-sm text-text-secondary space-y-4">
          <div className="flex items-center gap-3">
            <img src={vendor?.storeLogo || 'https://picsum.photos/seed/storelogo/100'} alt={vendor?.storeName} className="w-12 h-12 rounded-full object-cover bg-surface" />
            <div>
              <p className="text-text-muted text-xs">Sold By</p>
              <p className="font-semibold text-text-main">{vendor?.storeName || product.sellerInfo || 'VexoKart'}</p>
            </div>
          </div>
          <p><strong className="text-text-secondary">Return Policy:</strong> {product.returnPolicy || 'N/A'}</p>
          <p><strong className="text-text-secondary">Warranty:</strong> {product.warranty || 'N/A'}</p>
        </div>;
      default: return null;
    }
  };

  return (
    <div className="min-h-screen bg-background pb-24">
      {/* Video Modal */}
      {showVideoModal && product.videoUrl && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-background/90 backdrop-blur-md" onClick={() => setShowVideoModal(false)}>
            <div className="relative w-full max-w-4xl aspect-video bg-black rounded-2xl overflow-hidden shadow-2xl border border-border" onClick={e => e.stopPropagation()}>
                <button 
                    onClick={() => setShowVideoModal(false)}
                    className="absolute top-4 right-4 z-10 p-2 bg-black/50 text-text-main rounded-full hover:bg-black/70 transition"
                >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                    </svg>
                </button>
                {product.videoUrl.includes('youtube') || product.videoUrl.includes('youtu.be') ? (
                    <iframe 
                        className="w-full h-full" 
                        src={getEmbedUrl(product.videoUrl)} 
                        title="Product Video" 
                        frameBorder="0" 
                        allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" 
                        allowFullScreen
                    ></iframe>
                ) : (
                    <video className="w-full h-full" controls autoPlay>
                        <source src={product.videoUrl} type="video/mp4" />
                        Your browser does not support the video tag.
                    </video>
                )}
            </div>
        </div>
      )}

      {/* Image Gallery */}
      <div className="relative">
        <img src={product.images[currentImageIndex]} alt={product.name} className="w-full h-80 object-cover" />
        <div className="absolute inset-0 bg-gradient-to-t from-background via-transparent to-transparent"></div>

        {/* Play Button Overlay */}
        {product.videoUrl && (
            <button 
                onClick={() => setShowVideoModal(true)}
                className="absolute inset-0 flex items-center justify-center group"
            >
                <div className="p-4 bg-accent/80 rounded-full shadow-lg transform group-hover:scale-110 transition-transform backdrop-blur-md">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-white fill-current" viewBox="0 0 24 24">
                        <path d="M8 5v14l11-7z" />
                    </svg>
                </div>
                <span className="absolute bottom-24 bg-surface/80 text-text-main text-xs font-bold px-3 py-1 rounded-full border border-border group-hover:bg-accent transition-colors">
                    Watch Product Video
                </span>
            </button>
        )}

        <button onClick={() => navigate(-1)} className="absolute top-4 left-4 p-2 bg-black/30 rounded-full text-text-main hover:bg-black/50 transition"><ChevronLeftIcon className="h-6 w-6" /></button>
        <div className="absolute top-4 right-4 flex gap-2">
            <button onClick={handleShare} className="p-2 bg-black/30 rounded-full text-text-main hover:bg-black/50 transition"><ShareIcon className="w-6 h-6" /></button>
            <button onClick={handleToggleWishlist} className={`p-2 bg-black/30 rounded-full transition-colors ${isWishlisted ? 'text-red-500' : 'text-text-main hover:text-red-400'}`}><HeartIcon className="w-6 h-6" fill={isWishlisted ? 'currentColor' : 'none'}/></button>
        </div>
      </div>
      <div className="flex justify-center gap-2 p-2 -mt-10 relative z-10">
        {product.images.map((img, index) => (
            <img key={index} src={img} onClick={() => setCurrentImageIndex(index)} className={`w-16 h-16 rounded-lg object-cover cursor-pointer border-2 transition-all ${currentImageIndex === index ? 'border-accent' : 'border-transparent opacity-60 hover:opacity-100'}`}/>
        ))}
      </div>

      {/* Product Info */}
      <div className="p-4 space-y-4">
        <h1 className="text-2xl font-bold text-text-main">{product.name}</h1>
        <div className="flex items-center"><StarRating rating={product.rating} /><span className="text-xs text-text-muted ml-2">{product.rating} ({product.reviewCount} reviews)</span></div>
        <div className="flex items-baseline gap-2">
          <p className="text-3xl font-bold text-accent">₹{product.price.toFixed(2)}</p>
          {product.originalPrice && product.originalPrice > product.price && <>
            <p className="text-lg text-text-muted line-through opacity-75">₹{product.originalPrice.toFixed(2)}</p>
            <span className="text-sm font-bold text-green-400 bg-green-900/50 px-2 py-0.5 rounded-md">{discount}% OFF</span>
          </>}
        </div>
        {product.stock !== undefined && product.stock > 0 && product.stock < 10 && <p className="text-sm font-semibold text-orange-400">Hurry, only {product.stock} left!</p>}

        {/* Info Tabs */}
        <div className="pt-2">
          <div className="flex border-b border-gray-700 mb-4 overflow-x-auto">
            {visibleTabs.map(tab => (
              <button key={tab.id} onClick={() => setActiveTab(tab.id)} className={`flex-shrink-0 px-4 py-2 text-sm font-semibold capitalize transition-colors ${activeTab === tab.id ? 'text-accent border-b-2 border-accent' : 'text-text-muted hover:text-text-secondary'}`}>{tab.label}</button>
            ))}
          </div>
          <div className="min-h-[100px]">{renderTabContent()}</div>
        </div>

        {/* Similar Products */}
        {similarProducts.length > 0 && <section>
          <h2 className="text-xl font-bold text-text-main mb-4">You Might Also Like</h2>
          <div className="grid grid-cols-2 gap-4">{similarProducts.map(p => <ProductCard key={p.id} product={p} />)}</div>
        </section>}

        {/* Recently Viewed */}
        {recentlyViewedProducts.length > 0 && <section>
          <h2 className="text-xl font-bold text-text-main mb-4">Recently Viewed</h2>
          <div className="grid grid-cols-2 gap-4">{recentlyViewedProducts.map(p => <ProductCard key={p.id} product={p} />)}</div>
        </section>}

      </div>

