import React from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { Product } from '../types';
import StarRating from './StarRating';
import GlassmorphicCard from './GlassmorphicCard';
import { useAuth } from '../context/AuthContext';
import { HeartIcon } from './icons/HeartIcon';

interface ProductCardProps {
  product: Product;
}

const ProductCard: React.FC<ProductCardProps> = ({ product }) => {
  const { isAuthenticated, addToWishlist, removeFromWishlist, isInWishlist } = useAuth();
  const navigate = useNavigate();

  const isWishlisted = isInWishlist(product.id);

  const handleToggleWishlist = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (!isAuthenticated) {
        navigate('/login');
        return;
    }
    if (isWishlisted) {
      removeFromWishlist(product.id);
    } else {
      addToWishlist(product.id);
    }
  };

  return (
    <GlassmorphicCard light className="transform hover:-translate-y-1 hover:shadow-xl hover:border-accent/20 relative group">
        <button 
            onClick={handleToggleWishlist}
            className={`absolute top-2 right-2 z-10 p-2 bg-white/90 backdrop-blur-md rounded-full border border-gray-100 shadow-sm transition-all duration-300 ${isWishlisted ? 'text-red-500' : 'text-gray-400 hover:text-red-400'}`}
        >
            <HeartIcon className="w-4 h-4" fill={isWishlisted ? 'currentColor' : 'none'}/>
        </button>

      <Link to={`/product/${product.id}`} className="block">
        <div className="w-full aspect-square bg-gray-50 flex items-center justify-center overflow-hidden">
            <img
              src={product.images[0]}
              alt={product.name}
              className="w-full h-full object-contain p-4 group-hover:scale-105 transition-transform duration-700"
            />
        </div>
        <div className="p-4">
          <p className="text-[10px] text-accent font-black uppercase tracking-widest mb-1">{product.category}</p>
          <h3 className="text-sm font-bold text-gray-900 truncate tracking-tight mb-2">{product.name}</h3>

          <div className="flex items-center justify-between mb-2">
            <div className="flex flex-col">
                <p className="text-lg font-black text-gray-900 leading-none tracking-tighter">₹{product.price.toLocaleString('en-IN')}</p>
                {product.originalPrice && product.originalPrice > product.price && (
                  <p className="text-[10px] text-gray-400 line-through mt-1">₹{product.originalPrice.toLocaleString('en-IN')}</p>
                )}
            </div>
            <div className="flex flex-col items-end">
                <StarRating rating={product.rating} />
                <span className="text-[10px] text-gray-400 font-bold mt-1">({product.reviewCount})</span>
            </div>
          </div>
        </div>
      </Link>
    </GlassmorphicCard>
  );
};

export default ProductCard;

import React, { useState, useEffect } from 'react';
import { useSearchParams } from 'react-router-dom';
import Header from '../components/Header';
import ProductCard from '../components/ProductCard';
import { useProducts } from '../hooks/useProducts';
import { useCategories } from '../hooks/useCategories';
import Skeleton, { ProductCardSkeleton } from '../components/Skeleton';

const ProductsPage: React.FC = () => {
  const { products } = useProducts();
  const { categories } = useCategories();
  const [searchParams, setSearchParams] = useSearchParams();
  const [isLoading, setIsLoading] = useState(true);

  const categoryFromUrl = searchParams.get('category');
  const [selectedCategory, setSelectedCategory] = useState<string>(categoryFromUrl || 'All');

  useEffect(() => {
    setSelectedCategory(categoryFromUrl || 'All');
    setIsLoading(true);
    const timer = setTimeout(() => setIsLoading(false), 500);
    return () => clearTimeout(timer);
  }, [categoryFromUrl]);

  const handleCategorySelect = (categoryName: string) => {
    setSelectedCategory(categoryName);
    if (categoryName === 'All') {
      setSearchParams({});
    } else {
      setSearchParams({ category: categoryName });
    }
  };

  const liveProducts = products.filter(p => p.status === 'approved' || p.status === 'live');

  const filteredProducts = selectedCategory === 'All'
    ? liveProducts
    : liveProducts.filter(p => p.category === selectedCategory);

  return (
    <div className="bg-[#F9FAFB] min-h-screen">
      <Header title="Shop All" />
      <div className="p-4 max-w-7xl mx-auto">
        <div className="flex space-x-2 overflow-x-auto pb-4 mb-6 no-scrollbar">
          <button
            onClick={() => handleCategorySelect('All')}
            className={`px-5 py-2.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all flex-shrink-0 ${selectedCategory === 'All' ? 'bg-accent text-white shadow-lg shadow-accent/30' : 'bg-white text-gray-500 border border-gray-100 hover:border-accent/30'}`}
          >
            All
          </button>
          {categories.map(category => (
            <button
              key={category.id}
              onClick={() => handleCategorySelect(category.name)}
              className={`px-5 py-2.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all flex-shrink-0 ${selectedCategory === category.name ? 'bg-accent text-white shadow-lg shadow-accent/30' : 'bg-white text-gray-500 border border-gray-100 hover:border-accent/30'}`}
            >
              {category.name}
            </button>
          ))}
        </div>

        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
          {isLoading ? (
              <>
                  {[...Array(6)].map((_, i) => <ProductCardSkeleton key={i} />)}
              </>
          ) : filteredProducts.length > 0 ? (
            filteredProducts.map(product => (
                <ProductCard key={product.id} product={product} />
            ))
          ) : (
            <div className="col-span-full text-center py-32 flex flex-col items-center">
                <svg className="w-20 h-20 text-gray-200 mb-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M9.172 16.172a4 4 0 015.656 0M9 10h.01M15 10h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                <h3 className="text-xl font-bold text-gray-900 italic">No products found</h3>
                <p className="text-gray-400 mt-2">Try adjusting your category filter.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default ProductsPage;

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useProducts } from '../hooks/useProducts';
import StarRating from '../components/StarRating';
import { ChevronLeftIcon } from '../components/icons/ChevronLeftIcon';
import { HeartIcon } from '../components/icons/HeartIcon';
import { ShareIcon } from '../components/icons/ShareIcon';
import { useCart } from '../hooks/useCart';
import { useAuth } from '../context/AuthContext';
import { useRecentlyViewed } from '../context/RecentlyViewedContext';
import ProductCard from '../components/ProductCard';
import { useVendors } from '../context/VendorContext';

type Tab = 'description' | 'highlights' | 'specs' | 'shipping';

const ProductDetailPage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { products, getProduct } = useProducts();
  const { addToCart } = useCart();
  const { user, isAuthenticated, addToWishlist, removeFromWishlist, isInWishlist } = useAuth();
  const { addRecentlyViewed } = useRecentlyViewed();
  const { getVendorById } = useVendors();
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const [activeTab, setActiveTab] = useState<Tab>('description');
  const [showVideoModal, setShowVideoModal] = useState(false);
  const [showImageLightbox, setShowImageLightbox] = useState(false);

  const productId = parseInt(id || '');
  const product = getProduct(productId);
  const vendor = product ? getVendorById(product.vendorId) : null;

  const TABS: { id: Tab; label: string; isVisible: boolean }[] = [
    { id: 'description', label: 'Description', isVisible: !!product?.description },
    { id: 'highlights', label: 'Highlights', isVisible: !!product?.highlights && product.highlights.length > 0 },
    { id: 'specs', label: 'Specifications', isVisible: !!product?.specifications && Object.keys(product.specifications).length > 0 },
    { id: 'shipping', label: 'Shipping & Policy', isVisible: true },
  ];

  const visibleTabs = TABS.filter(t => t.isVisible);

  useEffect(() => {
    if (product && isAuthenticated) {
      addRecentlyViewed(product.id);
    }
    setCurrentImageIndex(0);
    setActiveTab(visibleTabs[0]?.id || 'description');
  }, [productId, product, isAuthenticated, addRecentlyViewed]);

  if (!product) {
    return <div className="text-center p-8 text-gray-900 bg-white min-h-screen">Product not found</div>;
  }

  const isWishlisted = isInWishlist(product.id);
  const discount = product.originalPrice && product.originalPrice > product.price 
    ? Math.round(((product.originalPrice - product.price) / product.originalPrice) * 100) 
    : 0;

  const similarProducts = products.filter(p => p.category === product.category && p.id !== product.id && p.status === 'approved').slice(0, 4);
  const recentlyViewedProducts = user?.recentlyViewed.map(id => getProduct(id)).filter(p => p && p.id !== product.id && p.status === 'approved') || [];

  const handleToggleWishlist = () => {
    if (!isAuthenticated) navigate('/login'); else isWishlisted ? removeFromWishlist(product.id) : addToWishlist(product.id);
  };

  const handleShare = () => {
    if (navigator.share) {
      navigator.share({
        title: product.name,
        text: `Check out this product: ${product.name}`,
        url: window.location.href,
      }).catch(console.error);
    } else {
      navigator.clipboard.writeText(window.location.href);
      alert('Link copied to clipboard!');
    }
  };

  const handleAddToCart = () => { addToCart(product); };
  const handleBuyNow = () => { addToCart(product); navigate('/checkout'); };

  const nextImage = (e: React.MouseEvent) => {
      e.stopPropagation();
      setCurrentImageIndex((prev) => (prev + 1) % product.images.length);
  };

  const prevImage = (e: React.MouseEvent) => {
      e.stopPropagation();
      setCurrentImageIndex((prev) => (prev - 1 + product.images.length) % product.images.length);
  };

  const getEmbedUrl = (url: string) => {
    if (!url) return '';
    if (url.includes('youtube.com') || url.includes('youtu.be')) {
        const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|\&v=)([^#\&\?]*).*/;
        const match = url.match(regExp);
        return (match && match[2].length === 11) ? `https://www.youtube.com/embed/${match[2]}?autoplay=1` : url;
    }
    return url;
  };

  const renderTabContent = () => {
    switch (activeTab) {
      case 'description': return <p className="text-gray-600 leading-relaxed text-sm">{product.description}</p>;
      case 'highlights': return <ul className="list-disc list-inside text-gray-600 space-y-2 text-sm">{product.highlights?.map((h, i) => <li key={i}>{h}</li>)}</ul>;
      case 'specs': return <div className="text-sm">{Object.entries(product.specifications || {}).map(([key, value]) => (<div key={key} className="flex border-b border-gray-100 py-3"><span className="w-1/3 text-gray-400 font-medium">{key}</span><span className="w-2/3 text-gray-900 font-semibold">{value}</span></div>))}</div>;
      case 'shipping': return <div className="text-sm text-gray-600 space-y-5">
          <div className="flex items-center gap-4 p-4 bg-gray-50 rounded-2xl border border-gray-100">
            <img src={vendor?.storeLogo || `https://ui-avatars.com/api/?name=${vendor?.storeName || 'V'}`} alt={vendor?.storeName} className="w-12 h-12 rounded-full object-cover bg-white shadow-sm" />
            <div>
              <p className="text-gray-400 text-[10px] font-black uppercase tracking-widest">Official Merchant</p>
              <p className="font-bold text-gray-900">{vendor?.storeName || product.sellerInfo || 'VexoKart'}</p>
            </div>
          </div>
          <div className="space-y-3 px-1">
            <p><strong className="text-gray-900">Return Policy:</strong> {product.returnPolicy || '30-Day Returns'}</p>
            <p><strong className="text-gray-900">Warranty:</strong> {product.warranty || '1 Year Brand Warranty'}</p>
          </div>
        </div>;
      default: return null;
    }
  };

  return (
    <div className="min-h-screen bg-white pb-32">
      {/* Lightbox remains dark for focus */}
      {showImageLightbox && (
          <div className="fixed inset-0 z-[110] bg-black/95 flex items-center justify-center p-4 animate-in fade-in zoom-in duration-300" onClick={() => setShowImageLightbox(false)}>
              <button className="absolute top-6 right-6 text-white text-3xl font-light hover:scale-110 transition">&times;</button>
              <img src={product.images[currentImageIndex]} className="max-w-full max-h-[90vh] object-contain rounded-lg" onClick={e => e.stopPropagation()} alt="Product High Res" />
          </div>
      )}

      {/* Video Modal */}
      {showVideoModal && product.videoUrl && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm animate-in fade-in duration-300" onClick={() => setShowVideoModal(false)}>
            <div className="relative w-full max-w-4xl aspect-video bg-black rounded-2xl overflow-hidden shadow-2xl" onClick={e => e.stopPropagation()}>
                <button onClick={() => setShowVideoModal(false)} className="absolute top-4 right-4 z-10 p-2 bg-black/50 text-white rounded-full hover:bg-black/70 transition">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
                <iframe className="w-full h-full" src={getEmbedUrl(product.videoUrl)} title="Product Video" frameBorder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowFullScreen></iframe>
            </div>
        </div>
      )}

      {/* Image Gallery */}
      <div className="relative bg-gray-50 border-b border-gray-100">
        <div className="w-full h-[450px] flex items-center justify-center overflow-hidden cursor-zoom-in relative" onClick={() => setShowImageLightbox(true)}>
             <img src={product.images[currentImageIndex]} alt={product.name} className="max-w-full max-h-full object-contain p-8 drop-shadow-xl transition-all duration-700 hover:scale-110" />

            {product.images.length > 1 && (
                <div className="absolute inset-x-0 bottom-8 flex justify-center gap-2 px-4 z-10">
                    {product.images.map((_, i) => (
                        <div key={i} className={`h-1.5 transition-all duration-300 rounded-full ${i === currentImageIndex ? 'w-8 bg-accent' : 'w-2 bg-gray-300'}`}></div>
                    ))}
                </div>
            )}
        </div>

        <button onClick={() => navigate(-1)} className="absolute top-6 left-6 p-3 bg-white/90 rounded-full text-gray-900 hover:bg-white transition shadow-lg z-20"><ChevronLeftIcon className="h-6 w-6" /></button>
        <div className="absolute top-6 right-6 flex gap-3 z-20">
            <button onClick={handleShare} className="p-3 bg-white/90 rounded-full text-gray-900 hover:bg-white transition shadow-lg"><ShareIcon className="w-6 h-6" /></button>
            <button onClick={handleToggleWishlist} className={`p-3 bg-white/90 rounded-full transition-all shadow-lg ${isWishlisted ? 'text-red-500' : 'text-gray-400 hover:text-red-400'}`}><HeartIcon className="w-6 h-6" fill={isWishlisted ? 'currentColor' : 'none'}/></button>
        </div>

        {/* Video Play Button */}
        {product.videoUrl && (
            <button onClick={(e) => { e.stopPropagation(); setShowVideoModal(true); }} className="absolute bottom-8 right-8 p-5 bg-white text-accent rounded-full shadow-xl hover:scale-110 active:scale-95 transition-all z-20">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 fill-current" viewBox="0 0 24 24"><path d="M8 5v14l11-7z" /></svg>
            </button>
        )}
      </div>

      <div className="flex justify-center gap-3 p-4 bg-white overflow-x-auto no-scrollbar border-b border-gray-50">
        {product.images.map((img, index) => (
            <div key={index} className={`flex-shrink-0 w-20 h-20 rounded-2xl overflow-hidden cursor-pointer border-2 transition-all shadow-sm ${currentImageIndex === index ? 'border-accent' : 'border-transparent opacity-60 hover:opacity-100'}`} onClick={() => setCurrentImageIndex(index)}>
                <img src={img} className="w-full h-full object-contain bg-gray-50" />
            </div>
        ))}
      </div>

      {/* Product Info */}
      <div className="p-6 space-y-6 max-w-4xl mx-auto">
        <div className="space-y-3">
            <div className="flex justify-between items-start">
                <h1 className="text-3xl font-black text-gray-900 tracking-tight leading-tight italic uppercase">{product.name}</h1>
            </div>
            <div className="flex items-center gap-3">
                <div className="flex items-center bg-gray-50 px-3 py-1.5 rounded-full border border-gray-100">
                    <StarRating rating={product.rating} />
                    <span className="text-xs text-gray-900 font-black ml-2">{product.rating}</span>
                </div>
                <span className="text-xs text-gray-400 font-bold tracking-tight uppercase">{product.reviewCount} Verified Reviews</span>
            </div>
        </div>

        <div className="flex items-center gap-4 py-4 border-y border-gray-100">
          <p className="text-4xl font-black text-gray-900 tracking-tighter italic">₹{product.price.toLocaleString('en-IN', { minimumFractionDigits: 2 })}</p>
          {product.originalPrice && product.originalPrice > product.price && (
            <div className="flex flex-col">
                <p className="text-lg text-gray-400 line-through decoration-red-400">₹{product.originalPrice.toLocaleString('en-IN')}</p>
                <span className="text-[10px] font-black text-green-500 uppercase tracking-widest">{discount}% OFF EXCLUSIVE</span>
            </div>
          )}
        </div>

        {product.stock !== undefined && product.stock > 0 && product.stock < 10 && (
            <div className="bg-orange-50 border border-orange-100 rounded-2xl p-4 flex items-center gap-3 animate-pulse">
                <div className="w-2.5 h-2.5 rounded-full bg-orange-500"></div>
                <p className="text-[11px] font-black text-orange-600 uppercase tracking-widest leading-none">Limited Inventory: Only {product.stock} pieces remaining</p>
            </div>
        )}

        {/* Tabs */}
        <div className="pt-2">
          <div className="flex space-x-8 border-b border-gray-100 mb-6 overflow-x-auto no-scrollbar">
            {visibleTabs.map(tab => (
              <button key={tab.id} onClick={() => setActiveTab(tab.id)} className={`flex-shrink-0 pb-4 text-[10px] font-black uppercase tracking-widest transition-all relative ${activeTab === tab.id ? 'text-gray-900' : 'text-gray-400 hover:text-gray-600'}`}>
                {tab.label}
                {activeTab === tab.id && <div className="absolute bottom-0 left-0 right-0 h-1 bg-gray-900 rounded-full"></div>}
              </button>
            ))}
          </div>
          <div className="min-h-[150px] animate-in fade-in duration-500">
            {renderTabContent()}
          </div>
        </div>

        {/* Recommended Grid */}
        {similarProducts.length > 0 && (
            <section className="pt-12">
                <h2 className="text-sm font-black text-gray-900 italic tracking-widest uppercase mb-8">Related Masterpieces</h2>
                <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
                    {similarProducts.map(p => <ProductCard key={p.id} product={p} />)}
                </div>
            </section>
        )}

      </div>

      {/* Sticky Bottom Nav - Premium Light Glass */}
      <div className="fixed bottom-0 left-0 right-0 p-5 bg-white/80 backdrop-blur-2xl border-t border-gray-100 flex items-center gap-4 z-50">
         <button onClick={handleAddToCart} className="flex-1 bg-white border-2 border-accent text-accent font-black uppercase tracking-widest text-[11px] py-4 rounded-2xl shadow-sm hover:bg-accent/5 transition-all active:scale-95">
            Add to Bag
         </button>
         <button onClick={handleBuyNow} className="flex-[1.5] bg-gradient-to-r from-accent to-accent-secondary text-white font-black uppercase tracking-widest text-[11px] py-4 rounded-2xl shadow-xl shadow-accent/20 hover:brightness-110 transition-all active:scale-95">
            Buy Now
         </button>
      </div>
    </div>
  );
};

export default ProductDetailPage;

