  const handleAddToCart = () => { addToCart(product); };
  const handleBuyNow = () => { addToCart(product); navigate('/checkout'); };

  const nextImage = (e: React.MouseEvent) => {
      e.stopPropagation();
      setCurrentImageIndex((prev) => (prev + 1) % product.images.length);
  };

  const prevImage = (e: React.MouseEvent) => {
      e.stopPropagation();
      setCurrentImageIndex((prev) => (prev - 1 + product.images.length) % product.images.length);
  };

  const getEmbedUrl = (url: string) => {
    if (!url) return '';
    if (url.includes('youtube.com') || url.includes('youtu.be')) {
        const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|\&v=)([^#\&\?]*).*/;
        const match = url.match(regExp);
        return (match && match[2].length === 11) ? `https://www.youtube.com/embed/${match[2]}?autoplay=1` : url;
    }
    return url;
  };

  const renderTabContent = () => {
    switch (activeTab) {
      case 'description': return <p className="text-text-secondary leading-relaxed text-sm font-medium">{product.description}</p>;
      case 'highlights': return <ul className="list-disc list-inside text-text-secondary space-y-3 text-sm font-medium">{product.highlights?.map((h, i) => <li key={i}>{h}</li>)}</ul>;
      case 'specs': return <div className="text-sm font-medium">{Object.entries(product.specifications || {}).map(([key, value]) => (<div key={key} className="flex border-b border-gray-700/30 py-3"><span className="w-1/3 text-text-muted uppercase text-[10px] font-black tracking-widest">{key}</span><span className="w-2/3 text-text-main">{value}</span></div>))}</div>;
      case 'reviews': return (
        <div className="space-y-8">
          {/* Summary */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8 items-center bg-surface/30 p-6 rounded-2xl border border-white/5">
            <div className="text-center md:text-left">
              <p className="text-5xl font-black text-text-main italic tracking-tighter mb-2">{product.rating || '0.0'}</p>
              <div className="flex justify-center md:justify-start mb-2"><StarRating rating={product.rating} /></div>
              <p className="text-[10px] font-black uppercase tracking-widest text-text-muted">Based on {product.reviewCount} Reviews</p>
            </div>
            <div className="space-y-2">
              {[5, 4, 3, 2, 1].map(num => {
                const count = product.reviews.filter(r => r.rating === num).length;
                const pct = product.reviewCount > 0 ? (count / product.reviewCount) * 100 : 0;
                return (
                  <div key={num} className="flex items-center gap-3">
                    <span className="text-[10px] font-bold text-text-muted w-3">{num}</span>
                    <div className="flex-grow h-1.5 bg-white/5 rounded-full overflow-hidden">
                      <div className="h-full bg-accent transition-all duration-500" style={{ width: `${pct}%` }}></div>
                    </div>
                    <span className="text-[10px] font-bold text-text-muted w-8">{count}</span>
                  </div>
                )
              })}
            </div>
          </div>

          {/* Review List */}
          <div className="space-y-6">
            {product.reviews.length > 0 ? product.reviews.map((review) => (
              <GlassmorphicCard key={review.id} className="p-4 border-white/5">
                <div className="flex justify-between items-start mb-3">
                  <div>
                    <div className="flex items-center gap-2 mb-1">
                      <span className="text-sm font-bold text-text-main">{review.author}</span>
                      <span className="text-[8px] font-black uppercase text-green-400 bg-green-400/10 px-2 py-0.5 rounded border border-green-400/20">Verified Buyer</span>
                    </div>
                    <StarRating rating={review.rating} />
                  </div>
                  <span className="text-[9px] text-text-muted font-bold">{new Date(review.date).toLocaleDateString([], { day: 'numeric', month: 'short', year: 'numeric' })}</span>
                </div>
                <p className="text-sm text-text-secondary leading-relaxed italic">"{review.comment}"</p>
                {review.vendorReply && (
                  <div className="mt-4 p-3 bg-accent/5 border-l-2 border-accent rounded-r-lg">
                    <p className="text-[9px] font-black uppercase text-accent mb-1">Response from Vendor</p>
                    <p className="text-xs text-text-secondary italic">"{review.vendorReply}"</p>
                  </div>
                )}
              </GlassmorphicCard>
            )) : (
              <div className="text-center py-10 opacity-50">
                <p className="text-sm font-bold uppercase tracking-widest text-text-muted italic">No verified reviews yet.</p>
              </div>
            )}
          </div>
        </div>
      );
      case 'shipping': return <div className="text-sm text-text-secondary space-y-4 font-medium">
          <div className="flex items-center gap-4 p-3 bg-surface rounded-xl border border-white/5">
            <img src={vendor?.storeLogo || `https://ui-avatars.com/api/?name=${vendor?.storeName || 'V'}`} alt={vendor?.storeName} className="w-12 h-12 rounded-full object-cover border border-border" />
            <div>
              <p className="text-text-muted text-[10px] font-black uppercase tracking-widest">Authorized Seller</p>
              <p className="font-bold text-text-main text-base tracking-tight">{vendor?.storeName || product.sellerInfo || 'VexoKart'}</p>
            </div>
          </div>
          <div className="space-y-2">
            <p><strong className="text-text-muted uppercase text-[10px] font-black tracking-widest mr-2">Return Policy:</strong> {product.returnPolicy || '30-Day Returns'}</p>
            <p><strong className="text-text-muted uppercase text-[10px] font-black tracking-widest mr-2">Warranty:</strong> {product.warranty || '1 Year Brand Warranty'}</p>
          </div>
        </div>;
      default: return null;
    }
  };

  return (
    <div className="min-h-screen bg-background pb-24 text-text-secondary">
      {/* Image Lightbox Modal */}
      {showImageLightbox && (
          <div className="fixed inset-0 z-[110] bg-black/95 flex items-center justify-center p-4 animate-in fade-in zoom-in duration-300" onClick={() => setShowImageLightbox(false)}>
              <button className="absolute top-6 right-6 text-white text-3xl font-light hover:scale-110 transition">&times;</button>
              <img src={product.images[currentImageIndex]} className="max-w-full max-h-[90vh] object-contain rounded-lg shadow-2xl" onClick={e => e.stopPropagation()} alt="Product High Res" />
          </div>
      )}

      {/* Video Modal */}
      {showVideoModal && product.videoUrl && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-background/90 backdrop-blur-md animate-in fade-in duration-300" onClick={() => setShowVideoModal(false)}>
            <div className="relative w-full max-w-4xl aspect-video bg-black rounded-2xl overflow-hidden shadow-2xl border border-border" onClick={e => e.stopPropagation()}>
                <button onClick={() => setShowVideoModal(false)} className="absolute top-4 right-4 z-10 p-2 bg-black/50 text-text-main rounded-full hover:bg-black/70 transition">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
                <iframe className="w-full h-full" src={getEmbedUrl(product.videoUrl)} title="Product Video" frameBorder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowFullScreen></iframe>
            </div>
        </div>
      )}

      {/* Image Gallery */}
      <div className="relative group/gallery">
        <div className="w-full h-96 bg-surface flex items-center justify-center overflow-hidden cursor-zoom-in relative" onClick={() => setShowImageLightbox(true)}>
             <img src={product.images[currentImageIndex]} alt={product.name} className="max-w-full max-h-full object-contain p-4 drop-shadow-2xl transition-transform duration-500 hover:scale-105" />

            {product.images.length > 1 && (
                <div className="absolute inset-0 flex items-center justify-between px-4 opacity-0 group-hover/gallery:opacity-100 transition-opacity">
                    <button onClick={prevImage} className="p-2 bg-black/20 hover:bg-black/40 text-white rounded-full backdrop-blur-sm transition-all"><ChevronLeftIcon className="w-6 h-6" /></button>
                    <button onClick={nextImage} className="p-2 bg-black/20 hover:bg-black/40 text-white rounded-full backdrop-blur-sm transition-all rotate-180"><ChevronLeftIcon className="w-6 h-6" /></button>
                </div>
            )}
        </div>

        <div className="absolute inset-x-0 bottom-0 h-24 bg-gradient-to-t from-background to-transparent pointer-events-none"></div>

        <button onClick={() => navigate(-1)} className="absolute top-4 left-4 p-2 bg-black/30 rounded-full text-text-main hover:bg-black/50 transition backdrop-blur-md border border-white/5 shadow-lg"><ChevronLeftIcon className="h-6 w-6" /></button>
        <div className="absolute top-4 right-4 flex gap-2">
            <button onClick={handleShare} className="p-2 bg-black/30 rounded-full text-text-main hover:bg-black/50 transition backdrop-blur-md border border-white/5 shadow-lg"><ShareIcon className="w-6 h-6" /></button>
            <button onClick={handleToggleWishlist} className={`p-2 bg-black/30 rounded-full transition-colors backdrop-blur-md border border-white/5 shadow-lg ${isWishlisted ? 'text-red-500' : 'text-text-main hover:text-red-400'}`}><HeartIcon className="w-6 h-6" fill={isWishlisted ? 'currentColor' : 'none'}/></button>
        </div>

        {/* Video Play Button */}
        {product.videoUrl && (
            <button onClick={(e) => { e.stopPropagation(); setShowVideoModal(true); }} className="absolute bottom-6 right-6 p-4 bg-accent/90 rounded-full shadow-2xl transform hover:scale-110 active:scale-95 transition-all backdrop-blur-md z-10">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-white fill-current" viewBox="0 0 24 24"><path d="M8 5v14l11-7z" /></svg>
            </button>
        )}
      </div>

      <div className="flex justify-center gap-2 p-2 -mt-4 relative z-10 overflow-x-auto no-scrollbar max-w-full px-4">
        {product.images.map((img, index) => (
            <div key={index} className="flex-shrink-0 relative group">
                <img src={img} onClick={() => setCurrentImageIndex(index)} className={`w-16 h-16 rounded-xl object-cover cursor-pointer border-2 transition-all shadow-md ${currentImageIndex === index ? 'border-accent ring-2 ring-accent/20' : 'border-border opacity-70 hover:opacity-100 hover:border-text-muted'}`} />
            </div>
        ))}
      </div>

      {/* Product Info */}
      <div className="p-4 space-y-6 max-w-4xl mx-auto">
        <div className="space-y-2 text-center md:text-left">
            <h1 className="text-3xl md:text-5xl font-black text-text-main tracking-tighter leading-none uppercase italic">{product.name}</h1>
            <div className="flex items-center justify-center md:justify-start gap-3">
                <StarRating rating={product.rating} />
                <span className="text-[11px] text-text-muted font-black uppercase tracking-[0.2em]">{product.rating} • {product.reviewCount} GLOBAL REVIEWS</span>
            </div>
        </div>

        <div className="flex flex-wrap items-center justify-center md:justify-start gap-4">
          <p className="text-4xl md:text-5xl font-black text-accent tracking-tighter italic">₹{product.price.toLocaleString('en-IN', { minimumFractionDigits: 2 })}</p>
          {product.originalPrice && product.originalPrice > product.price && (
            <div className="flex items-center gap-3">
                <p className="text-xl text-text-muted line-through opacity-40 decoration-red-500/50">₹{product.originalPrice.toLocaleString('en-IN')}</p>
                <span className="text-[10px] font-black text-green-400 bg-green-900/40 px-3 py-1.5 rounded-full border border-green-500/20 uppercase tracking-widest">{discount}% OFF</span>
            </div>
          )}
        </div>

        {product.stock !== undefined && product.stock > 0 && product.stock < 10 && (
            <div className="bg-orange-500/5 border border-orange-500/10 rounded-2xl p-4 flex items-center justify-center md:justify-start gap-3">
                <div className="w-2.5 h-2.5 rounded-full bg-orange-500 animate-ping"></div>
                <p className="text-[10px] font-black text-orange-400 uppercase tracking-[0.2em]">Priority Stock Alert: {product.stock} Units Remaining</p>
            </div>
        )}

        {/* Info Tabs */}
        <div className="pt-4">
          <div className="flex border-b border-border/30 mb-6 overflow-x-auto no-scrollbar scroll-smooth">
            {visibleTabs.map(tab => (
              <button key={tab.id} onClick={() => setActiveTab(tab.id)} className={`flex-shrink-0 px-8 py-4 text-[10px] font-black uppercase tracking-[0.25em] transition-all relative ${activeTab === tab.id ? 'text-accent' : 'text-text-muted hover:text-text-secondary'}`}>
                {tab.label}
                {activeTab === tab.id && <div className="absolute bottom-0 left-0 right-0 h-[2px] bg-accent"></div>}
              </button>
            ))}
          </div>
          <div className="min-h-[120px] animate-in fade-in slide-in-from-bottom-4 duration-500">
            {renderTabContent()}
          </div>
        </div>

        {/* Similar Products */}
        {similarProducts.length > 0 && (
            <section className="pt-12 border-t border-white/5">
                <div className="flex justify-between items-center mb-8">
                    <h2 className="text-xl font-black text-text-main italic tracking-tighter uppercase">Marketplace Discovery</h2>
                </div>
                <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
                    {similarProducts.map(p => <ProductCard key={p.id} product={p} />)}
                </div>
            </section>
        )}
      </div>

      {/* Sticky Footer */}
      <div className="fixed bottom-0 left-0 right-0 p-4 bg-background/80 backdrop-blur-2xl border-t border-white/5 flex items-center gap-4 z-50">
         <button onClick={handleAddToCart} className="w-1/2 bg-surface/50 border border-white/10 text-text-main font-black uppercase tracking-[0.2em] text-[10px] py-4 rounded-2xl shadow-lg hover:bg-white/5 transition-all active:scale-95">
            Add to Cart
         </button>
         <button onClick={handleBuyNow} className="w-1/2 bg-gradient-to-r from-orange-500 to-orange-600 text-white font-black uppercase tracking-[0.2em] text-[10px] py-4 rounded-2xl shadow-2xl shadow-orange-500/30 hover:brightness-110 transition-all active:scale-95">
            Buy Now
         </button>
      </div>
    </div>
  );
};

