import React, { useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useOrders } from '../context/OrderContext';
import { useProducts } from '../hooks/useProducts';
import { useAuth } from '../context/AuthContext';
import GlassmorphicCard from '../components/GlassmorphicCard';
import { ChevronLeftIcon } from '../components/icons/ChevronLeftIcon';
import OrderTracker from '../components/OrderTracker';
import InvoiceModal from '../components/InvoiceModal';
import RateProductModal from '../components/RateProductModal';
import { OrderItem } from '../types';

const OrderDetailPage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { getOrderById, updateOrderStatus } = useOrders();
  const { getProduct, addReview } = useProducts();
  const { user } = useAuth();

  const [showInvoice, setShowInvoice] = useState(false);
  const [isCancelling, setIsCancelling] = useState(false);
  const [ratingItem, setRatingItem] = useState<OrderItem | null>(null);

  if (!id) {
    navigate('/orders');
    return null;
  }

  const order = getOrderById(id);

  if (!order) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen text-center p-4">
        <h1 className="text-2xl font-bold text-text-main">Order Not Found</h1>
        <button onClick={() => navigate('/orders')} className="mt-4 bg-accent text-white font-bold py-2 px-6 rounded-lg">
          Back to My Orders
        </button>
      </div>
    );
  }

  const handleCancelOrder = () => {
    if (window.confirm("Are you sure you want to cancel this order? This action cannot be undone.")) {
      setIsCancelling(true);
      setTimeout(() => {
        updateOrderStatus(order.id, 'Cancelled');
        setIsCancelling(false);
      }, 500);
    }
  };

  const handleReviewSubmit = (rating: number, comment: string) => {
    if (ratingItem && user) {
      // FIX: Removed 'productId' from the review object as it's not part of the Review type.
      // The productId is already passed as the first argument to addReview.
      addReview(ratingItem.id, {
        userId: user.email,
        orderId: order.id,
        author: user.name,
        rating,
        comment
      });
      setRatingItem(null);
      alert("Thank you for your review!");
    }
  };

  const isReviewed = (productId: number) => {
    const product = getProduct(productId);
    return product?.reviews.some(r => r.orderId === order.id && r.userId === user?.email);
  };

  const canCancel = ['Placed', 'Confirmed'].includes(order.status);
  const isDelivered = order.status === 'Delivered';
  const { shippingAddress: address } = order;

  return (
    <div className="min-h-screen bg-background pb-12">
      {showInvoice && order && <InvoiceModal order={order} onClose={() => setShowInvoice(false)} />}

      {ratingItem && (
        <RateProductModal 
          item={ratingItem} 
          orderId={order.id} 
          onClose={() => setRatingItem(null)} 
          onSubmit={handleReviewSubmit} 
        />
      )}

      <div className="sticky top-0 z-10 p-4 bg-background/80 backdrop-blur-xl flex items-center justify-between border-b border-white/5">
        <div className="flex items-center">
          <button onClick={() => navigate('/orders')} className="p-2 -ml-2 mr-2">
              <ChevronLeftIcon className="h-6 w-6 text-text-main" />
          </button>
          <h1 className="text-xl font-black text-text-main italic tracking-tight uppercase">Order Details</h1>
        </div>
        {canCancel && (
          <button 
            onClick={handleCancelOrder}
            disabled={isCancelling}
            className="text-[10px] font-black uppercase tracking-widest text-red-400 hover:text-red-300 transition-colors disabled:opacity-50"
          >
            {isCancelling ? 'Processing...' : 'Cancel Order'}
          </button>
        )}
      </div>

      <div className="p-4 space-y-4 max-w-2xl mx-auto">
        <GlassmorphicCard className="p-4 border-accent/20">
          <div className="flex justify-between items-center text-sm">
            <div>
              <p className="text-[10px] font-black uppercase tracking-widest text-text-muted mb-1">Receipt ID</p>
              <p className="font-bold text-text-main font-mono">#{order.id}</p>
            </div>
             <div>
              <p className="text-[10px] font-black uppercase tracking-widest text-text-muted text-right mb-1">Placed On</p>
              <p className="font-bold text-text-main">{new Date(order.date).toLocaleDateString([], { day: 'numeric', month: 'short', year: 'numeric' })}</p>
            </div>
          </div>
        </GlassmorphicCard>

        <section>
          <h2 className="text-[10px] font-black uppercase tracking-widest text-text-muted mb-3 ml-1">Live Tracking</h2>
          <OrderTracker status={order.status} history={order.statusHistory} />
        </section>

        {order.status !== 'Cancelled' && order.courierName && order.trackingId && (
            <GlassmorphicCard className="p-4 border-blue-500/20 bg-blue-500/5">
                <div className="flex items-center gap-3 mb-3">
                  <div className="p-2 bg-blue-500/20 rounded-lg">
                    <svg className="w-5 h-5 text-blue-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                  </div>
                  <h2 className="font-bold text-text-main tracking-tight italic">Shipment Dispatched</h2>
                </div>
                <div className="text-sm space-y-2 mb-4">
                    <div className="flex justify-between">
                      <span className="text-text-muted">Courier Partner</span>
                      <span className="font-bold text-text-main uppercase tracking-tight">{order.courierName}</span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-text-muted">Tracking Reference</span>
                      <span className="font-bold text-accent font-mono">{order.trackingId}</span>
                    </div>
                </div>
                <a 
                    href={`https://www.google.com/search?q=${encodeURIComponent(order.courierName + ' ' + order.trackingId + ' tracking')}`}
                    target="_blank" 
                    rel="noopener noreferrer"
                    className="block w-full text-center bg-accent text-white font-black uppercase tracking-widest text-[10px] py-3 rounded-xl shadow-lg shadow-accent/20 hover:-translate-y-0.5 transition-all"
                >
                    Track Package
                </a>
            </GlassmorphicCard>
        )}

        <GlassmorphicCard className="p-4">
            <h2 className="text-[10px] font-black uppercase tracking-widest text-text-muted mb-4 border-b border-white/5 pb-2">Order Items</h2>
            <div className="space-y-6">
                {order.items.map(item => (
                    <div key={item.id} className="flex flex-col gap-4">
                      <div className="flex items-center space-x-4">
                          <img src={item.image} alt={item.name} className="w-16 h-16 rounded-xl object-cover bg-surface border border-white/5 shadow-inner" />
                          <div className="flex-grow min-w-0">
                              <p className="text-text-main font-bold truncate tracking-tight">{item.name}</p>
                              <p className="text-xs text-text-muted">Quantity: {item.quantity}</p>
                          </div>
                          <p className="text-text-main font-black italic">₹{(item.price * item.quantity).toFixed(2)}</p>
                      </div>
                      {isDelivered && (
                        <div className="flex justify-end">
                          {isReviewed(item.id) ? (
                            <span className="text-[9px] font-black uppercase text-green-400 bg-green-400/10 px-3 py-1.5 rounded-lg border border-green-400/20 flex items-center gap-2">
                              <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" /></svg>
                              Feedback Received
                            </span>
                          ) : (
                            <button 
                              onClick={() => setRatingItem(item)}
                              className="text-[9px] font-black uppercase tracking-widest text-accent border border-accent/30 px-4 py-2 rounded-xl hover:bg-accent hover:text-white transition-all active:scale-95"
                            >
                              Rate Experience
                            </button>
                          )}
                        </div>
                      )}
                    </div>
                ))}
            </div>

            <div className="mt-8 pt-4 border-t border-white/5 space-y-2 text-sm">
                <div className="flex justify-between"><span className="text-text-muted">Payment Type</span><span className="text-text-main font-bold">{order.paymentMethod}</span></div>
                <div className="flex justify-between"><span className="text-text-muted">Address Detail</span><span className="text-text-main text-right font-medium max-w-[200px] truncate">{address.fullName}, {address.city}</span></div>
                <div className="flex justify-between pt-2"><span className="text-text-main font-black uppercase tracking-widest text-[11px]">Final Total</span><span className="text-accent font-black text-lg italic">₹{order.total.toFixed(2)}</span></div>
            </div>

            {order.paymentId && order.status !== 'Cancelled' && (
                <div className="mt-4 pt-4 border-t border-white/5">
                    <button onClick={() => setShowInvoice(true)} className="w-full bg-surface border border-white/10 text-text-main font-black uppercase tracking-widest text-[10px] py-3 rounded-xl hover:bg-white/5 transition">
                        View Digital Invoice
                    </button>
                </div>
            )}
        </GlassmorphicCard>

      </div>
    </div>
  );
};

export default OrderDetailPage;

import React, { useEffect } from 'react';

interface ToastProps {
  message: string;
  isVisible: boolean;
  onClose: () => void;
  type?: 'success' | 'info';
}

const Toast: React.FC<ToastProps> = ({ message, isVisible, onClose, type = 'success' }) => {
  useEffect(() => {
    if (isVisible) {
      const timer = setTimeout(onClose, 3000);
      return () => clearTimeout(timer);
    }
  }, [isVisible, onClose]);

  if (!isVisible) return null;

  return (
    <div className="fixed bottom-24 left-1/2 -translate-x-1/2 z-[100] animate-in slide-in-from-bottom-4 fade-in duration-300">
      <div className={`px-6 py-3 rounded-2xl shadow-2xl backdrop-blur-xl border border-white/10 flex items-center gap-3 ${
        type === 'success' ? 'bg-accent text-white' : 'bg-surface text-text-main'
      }`}>
        {type === 'success' && (
          <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" />
          </svg>
        )}
        <span className="text-xs font-black uppercase tracking-widest">{message}</span>
      </div>
    </div>
  );
};

export default Toast;

import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useProducts } from '../../hooks/useProducts';
import { useCategories } from '../../hooks/useCategories';
import GlassmorphicCard from '../../components/GlassmorphicCard';
import { Product } from '../../types';

const AdminProductFormPage: React.FC = () => {
  const { id } = useParams<{ id?: string }>();
  const navigate = useNavigate();
  const { getProduct, addProduct, updateProduct } = useProducts();
  const { categories } = useCategories();

  const isEditing = id !== undefined;

  const [formData, setFormData] = useState<Omit<Product, 'id' | 'reviews' | 'rating' | 'reviewCount'>>({
    name: '',
    category: categories[0]?.name || '',
    price: 0,
    originalPrice: 0,
    images: [],
    description: '',
    vendorId: 'vexokart_internal',
    status: 'approved',
    highlights: [],
    stock: 10,
    specifications: {},
    sellerInfo: 'VexoKart Direct',
    returnPolicy: '30-Day Money Back Guarantee',
    warranty: '1 Year Standard Warranty',
    videoUrl: ''
  });

  // Local states for textareas to allow seamless typing
  const [highlightsText, setHighlightsText] = useState('');
  const [specsText, setSpecsText] = useState('');

  const inputClasses = "w-full mt-1 bg-surface text-text-main border border-gray-600 rounded-lg p-3 transition focus:outline-none focus:border-accent focus:ring-2 focus:ring-accent/50";

  useEffect(() => {
    if (isEditing) {
      const productToEdit = getProduct(parseInt(id));
      if (productToEdit) {
        setFormData({
            name: productToEdit.name,
            category: productToEdit.category,
            price: productToEdit.price,
            originalPrice: productToEdit.originalPrice,
            images: productToEdit.images,
            description: productToEdit.description,
            vendorId: productToEdit.vendorId,
            status: productToEdit.status,
            highlights: productToEdit.highlights || [],
            stock: productToEdit.stock || 0,
            specifications: productToEdit.specifications || {},
            sellerInfo: productToEdit.sellerInfo || 'VexoKart Direct',
            returnPolicy: productToEdit.returnPolicy || '30-Day Money Back Guarantee',
            warranty: productToEdit.warranty || '1 Year Standard Warranty',
            videoUrl: productToEdit.videoUrl || ''
        });
        setHighlightsText((productToEdit.highlights || []).join('\n'));
        setSpecsText(Object.entries(productToEdit.specifications || {}).map(([k, v]) => `${k}: ${v}`).join('\n'));
      }
    } else {
        if (categories.length > 0) {
            setFormData(prev => ({...prev, category: categories[0].name}));
        }
    }
  }, [id, isEditing, getProduct, categories]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: ['price', 'originalPrice', 'stock'].includes(name) ? parseFloat(value) || 0 : value }));
  };

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      for (const file of e.target.files) {
        const reader = new FileReader();
        reader.onloadend = () => {
          setFormData(prev => ({
            ...prev,
            images: [...prev.images, reader.result as string]
          }));
        };
        reader.readAsDataURL(file);
      }
    }
  };

  const removeImage = (index: number) => {
    setFormData(prev => ({ ...prev, images: prev.images.filter((_, i) => i !== index) }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if(formData.images.length === 0) {
        alert("Please upload at least one image for the product.");
        return;
    }

    // Parse highlights and specs from local text states before saving
    const finalHighlights = highlightsText.split('\n').map(s => s.trim()).filter(Boolean);
    const finalSpecs: { [key: string]: string } = {};
    specsText.split('\n').forEach(line => {
      const parts = line.split(':');
      if (parts.length === 2) {
        finalSpecs[parts[0].trim()] = parts[1].trim();
      }
    });

    const finalData = { 
        ...formData, 
        highlights: finalHighlights, 
        specifications: finalSpecs 
    };

    if (isEditing) {
      const existingProduct = getProduct(parseInt(id));
      const updatedData = { ...existingProduct, ...finalData, id: parseInt(id) } as Product;
      updateProduct(updatedData);
    } else {
      const { status, ...productData } = finalData;
      addProduct(productData as any);
      alert("Product published successfully!");
    }
    navigate('/admin/products');
  };

  return (
    <div>
      <h1 className="text-3xl font-bold text-text-main mb-6">{isEditing ? 'Edit Product' : 'Create New Product'}</h1>
      <GlassmorphicCard className="p-6">
        <form onSubmit={handleSubmit} className="space-y-4">
            <div><label className="block text-sm font-medium text-text-secondary">Name</label><input type="text" name="name" value={formData.name} onChange={handleChange} required className={inputClasses} /></div>
            <div><label className="block text-sm font-medium text-text-secondary">Category</label><select name="category" value={formData.category} onChange={handleChange} className={inputClasses}>{categories.map(c => <option key={c.id} value={c.name}>{c.name}</option>)}</select></div>
            <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                <div><label className="block text-sm font-medium text-text-secondary">Price (₹)</label><input type="number" name="price" value={formData.price} onChange={handleChange} required className={inputClasses} /></div>
                <div><label className="block text-sm font-medium text-text-secondary">Original Price (₹)</label><input type="number" name="originalPrice" value={formData.originalPrice} onChange={handleChange} className={inputClasses} /></div>
                 <div><label className="block text-sm font-medium text-text-secondary">Stock</label><input type="number" name="stock" value={formData.stock} onChange={handleChange} required className={inputClasses} /></div>
            </div>
            <div><label className="block text-sm font-medium text-text-secondary">Description</label><textarea name="description" value={formData.description} onChange={handleChange} required rows={4} className={inputClasses}></textarea></div>

            <div>
                <label className="block text-sm font-medium text-text-secondary">Images</label>
                <div className="mt-2"><input type="file" id="imageUpload" multiple accept="image/*" onChange={handleImageChange} className="hidden" /><label htmlFor="imageUpload" className="cursor-pointer bg-surface text-text-main font-semibold py-2 px-4 rounded-lg border border-gray-600 hover:bg-gray-700">Choose Files</label></div>
                <div className="mt-4 grid grid-cols-3 sm:grid-cols-4 md:grid-cols-5 gap-4">
                    {formData.images.map((image, index) => (
                        <div key={index} className="relative"><img src={image} alt={`preview ${index}`} className="w-full h-24 object-cover rounded-lg"/><button type="button" onClick={() => removeImage(index)} className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full w-6 h-6 flex items-center justify-center text-xs font-bold">&times;</button></div>
                    ))}
                </div>
            </div>

            <div><label className="block text-sm font-medium text-text-secondary">Highlights (one per line)</label><textarea value={highlightsText} onChange={(e) => setHighlightsText(e.target.value)} rows={4} className={inputClasses} placeholder="e.g.&#10;Premium Design&#10;Long Battery Life"></textarea></div>
            <div><label className="block text-sm font-medium text-text-secondary">Specifications (format: Key: Value)</label><textarea value={specsText} onChange={(e) => setSpecsText(e.target.value)} rows={5} className={inputClasses} placeholder="e.g.&#10;Color: Black&#10;Material: Aluminum"></textarea></div>
            <div><label className="block text-sm font-medium text-text-secondary">Video URL (optional)</label><input type="url" name="videoUrl" value={formData.videoUrl} onChange={handleChange} className={inputClasses} /></div>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <div><label className="block text-sm font-medium text-text-secondary">Seller Info</label><input type="text" name="sellerInfo" value={formData.sellerInfo} onChange={handleChange} className={inputClasses} /></div>
              <div><label className="block text-sm font-medium text-text-secondary">Return Policy</label><input type="text" name="returnPolicy" value={formData.returnPolicy} onChange={handleChange} className={inputClasses} /></div>
              <div><label className="block text-sm font-medium text-text-secondary">Warranty</label><input type="text" name="warranty" value={formData.warranty} onChange={handleChange} className={inputClasses} /></div>
            </div>
            <div className="flex justify-end gap-4 pt-4">
                <button type="button" onClick={() => navigate('/admin/products')} className="bg-gray-600/50 text-white font-bold py-2 px-4 rounded-lg hover:bg-gray-500/50">Cancel</button>
                <button type="submit" className="bg-accent text-white font-bold py-2 px-4 rounded-lg hover:brightness-110">{isEditing ? 'Update Product' : 'Create Product'}</button>
            </div>
        </form>
      </GlassmorphicCard>
    </div>
  );
};

export default AdminProductFormPage;

import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useProducts } from '../../hooks/useProducts';
import { useCategories } from '../../hooks/useCategories';
import GlassmorphicCard from '../../components/GlassmorphicCard';
import { Product } from '../../types';
import { useAuth } from '../../context/AuthContext';
import { useVendors } from '../../context/VendorContext';

const VendorProductFormPage: React.FC = () => {
  const { id } = useParams<{ id?: string }>();
  const navigate = useNavigate();
  const { getProduct, addProduct, updateProduct } = useProducts();
  const { categories } = useCategories();
  const { user } = useAuth();
  const { getVendorByUserId } = useVendors();

  const vendor = user ? getVendorByUserId(user.email) : null;
  const isEditing = id !== undefined;

  const [formData, setFormData] = useState<Omit<Product, 'id' | 'reviews' | 'rating' | 'reviewCount' | 'status' | 'vendorId'>>({
    name: '',
    category: categories[0]?.name || '',
    price: 0,
    originalPrice: 0,
    images: [],
    description: '',
    highlights: [],
    stock: 10,
    specifications: {},
    sellerInfo: vendor?.storeName || '',
    returnPolicy: '30-Day Money Back Guarantee',
    warranty: '1 Year Standard Warranty',
    videoUrl: ''
  });

  const [highlightsText, setHighlightsText] = useState('');
  const [specsText, setSpecsText] = useState('');

  const inputClasses = "w-full mt-1 bg-surface text-text-main border border-gray-600 rounded-lg p-3 transition focus:outline-none focus:border-accent focus:ring-2 focus:ring-accent/50";

  useEffect(() => {
    if (isEditing) {
      const productToEdit = getProduct(parseInt(id));
      if (productToEdit && vendor && productToEdit.vendorId === vendor.id) {
        setFormData({ ...productToEdit });
        setHighlightsText((productToEdit.highlights || []).join('\n'));
        setSpecsText(Object.entries(productToEdit.specifications || {}).map(([k, v]) => `${k}: ${v}`).join('\n'));
      } else {
        navigate('/vendor/products');
      }
    } else {
        if (categories.length > 0) {
            setFormData(prev => ({...prev, category: categories[0].name, sellerInfo: vendor?.storeName || ''}));
        }
    }
  }, [id, isEditing, getProduct, categories, vendor, navigate]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: ['price', 'originalPrice', 'stock'].includes(name) ? parseFloat(value) || 0 : value }));
  };

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      for (const file of e.target.files) {
        const reader = new FileReader();
        reader.onloadend = () => {
            setFormData(prev => ({
                ...prev,
                images: [...prev.images, reader.result as string]
            }));
        };
        reader.readAsDataURL(file);
      }
    }
  };

  const removeImage = (index: number) => {
    setFormData(prev => ({ ...prev, images: prev.images.filter((_, i) => i !== index) }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!vendor) {
        alert("Vendor information not found. Cannot save product.");
        return;
    }
    if(formData.images.length === 0) {
        alert("Please upload at least one image for the product.");
        return;
    }

    const finalHighlights = highlightsText.split('\n').map(s => s.trim()).filter(Boolean);
    const finalSpecs: { [key: string]: string } = {};
    specsText.split('\n').forEach(line => {
      const parts = line.split(':');
      if (parts.length === 2) {
        finalSpecs[parts[0].trim()] = parts[1].trim();
      }
    });

    const finalData = { 
        ...formData, 
        highlights: finalHighlights, 
        specifications: finalSpecs 
    };

    if (isEditing) {
      const existingProduct = getProduct(parseInt(id));
      const updatedData: Product = { ...existingProduct!, ...finalData, id: parseInt(id) };
      updateProduct(updatedData);
      alert("Product updated successfully!");
    } else {
      addProduct({ ...finalData, vendorId: vendor.id });
      alert("Product published successfully! It is now live for customers.");
    }
    navigate('/vendor/products');
  };

  return (
    <div>
      <h1 className="text-3xl font-bold text-text-main mb-6">{isEditing ? 'Edit Product' : 'Publish New Product'}</h1>
      <GlassmorphicCard className="p-6">
        <form onSubmit={handleSubmit} className="space-y-4">
            <div><label className="block text-sm font-medium text-text-secondary">Name</label><input type="text" name="name" value={formData.name} onChange={handleChange} required className={inputClasses} /></div>
            <div><label className="block text-sm font-medium text-text-secondary">Category</label><select name="category" value={formData.category} onChange={handleChange} className={inputClasses}>{categories.map(c => <option key={c.id} value={c.name}>{c.name}</option>)}</select></div>
            <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                <div><label className="block text-sm font-medium text-text-secondary">Price (₹)</label><input type="number" name="price" value={formData.price} onChange={handleChange} required className={inputClasses} /></div>
                <div><label className="block text-sm font-medium text-text-secondary">Original Price (₹)</label><input type="number" name="originalPrice" value={formData.originalPrice} onChange={handleChange} className={inputClasses} /></div>
                 <div><label className="block text-sm font-medium text-text-secondary">Stock</label><input type="number" name="stock" value={formData.stock} onChange={handleChange} required className={inputClasses} /></div>
            </div>
            <div><label className="block text-sm font-medium text-text-secondary">Description</label><textarea name="description" value={formData.description} onChange={handleChange} required rows={4} className={inputClasses}></textarea></div>
            <div>
                <label className="block text-sm font-medium text-text-secondary">Images</label>
                <div className="mt-2"><input type="file" id="imageUpload" multiple accept="image/*" onChange={handleImageChange} className="hidden" /><label htmlFor="imageUpload" className="cursor-pointer bg-surface text-text-main font-semibold py-2 px-4 rounded-lg border border-gray-600 hover:bg-gray-700">Choose Files</label></div>
                <div className="mt-4 grid grid-cols-3 sm:grid-cols-4 md:grid-cols-5 gap-4">
                    {formData.images.map((image, index) => (
                        <div key={index} className="relative"><img src={image} alt={`preview ${index}`} className="w-full h-24 object-cover rounded-lg"/><button type="button" onClick={() => removeImage(index)} className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full w-6 h-6 flex items-center justify-center text-xs font-bold">&times;</button></div>
                    ))}
                </div>
            </div>
            <div><label className="block text-sm font-medium text-text-secondary">Highlights (one per line)</label><textarea value={highlightsText} onChange={(e) => setHighlightsText(e.target.value)} rows={4} className={inputClasses} placeholder="e.g.&#10;High Quality&#10;Durable"></textarea></div>
            <div><label className="block text-sm font-medium text-text-secondary">Specifications (format: Key: Value)</label><textarea value={specsText} onChange={(e) => setSpecsText(e.target.value)} rows={5} className={inputClasses} placeholder="e.g.&#10;Color: Black&#10;Material: Aluminum"></textarea></div>
            <div className="flex justify-end gap-4 pt-4">
                <button type="button" onClick={() => navigate('/vendor/products')} className="bg-gray-600/50 text-white font-bold py-2 px-4 rounded-lg hover:bg-gray-500/50">Cancel</button>
                <button type="submit" className="bg-accent text-white font-bold py-2 px-4 rounded-lg hover:brightness-110">{isEditing ? 'Save Changes' : 'Publish Product'}</button>
            </div>
        </form>
      </GlassmorphicCard>
    </div>
  );
};

export default VendorProductFormPage;

import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { Product } from '../types';
import StarRating from './StarRating';
import GlassmorphicCard from './GlassmorphicCard';
import { useAuth } from '../context/AuthContext';
import { HeartIcon } from './icons/HeartIcon';
import { useCart } from '../hooks/useCart';
import Toast from './Toast';

interface ProductCardProps {
  product: Product;
}

const ProductCard: React.FC<ProductCardProps> = ({ product }) => {
  const { isAuthenticated, addToWishlist, removeFromWishlist, isInWishlist } = useAuth();
  const { addToCart } = useCart();
  const navigate = useNavigate();
  const [showAddedToast, setShowAddedToast] = useState(false);

  const isWishlisted = isInWishlist(product.id);

  const handleToggleWishlist = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (!isAuthenticated) {
        navigate('/login');
        return;
    }
    if (isWishlisted) {
      removeFromWishlist(product.id);
    } else {
      addToWishlist(product.id);
    }
  };

  const handleAddToCart = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    addToCart(product);
    setShowAddedToast(true);
  };

  const discount = product.originalPrice && product.originalPrice > product.price 
    ? Math.round(((product.originalPrice - product.price) / product.originalPrice) * 100) 
    : 0;

  return (
    <>
      <Toast message="Added to bag" isVisible={showAddedToast} onClose={() => setShowAddedToast(false)} />
      <GlassmorphicCard className="hover:shadow-premium-hover relative group border-none">
          <button 
              onClick={handleToggleWishlist}
              className={`absolute top-2 right-2 z-10 p-2 bg-white/80 backdrop-blur-md rounded-full border border-border transition-all duration-300 ${isWishlisted ? 'text-accent shadow-sm' : 'text-text-muted hover:text-accent shadow-sm'}`}
          >
              <HeartIcon className="w-4 h-4" fill={isWishlisted ? 'currentColor' : 'none'}/>
          </button>

        <Link to={`/product/${product.id}`} className="block">
          <div className="w-full aspect-square bg-surface flex items-center justify-center overflow-hidden">
              <img
                src={product.images[0]}
                alt={product.name}
                className="w-full h-full object-contain p-4 group-hover:scale-105 transition-transform duration-500"
              />
              {discount > 0 && (
                <div className="absolute top-2 left-2 bg-accent text-white text-[9px] font-bold px-2 py-1 rounded-md shadow-sm">
                  -{discount}%
                </div>
              )}
          </div>
          <div className="p-3">
            <h3 className="text-xs font-bold text-text-main truncate uppercase tracking-tight leading-tight">{product.name}</h3>
            <p className="text-[10px] text-text-secondary font-medium mt-1">{product.category}</p>

            <div className="flex items-center justify-between mt-2">
              <div className="flex flex-col">
                <p className="text-sm font-bold text-text-main">₹{product.price.toLocaleString('en-IN')}</p>
                {product.originalPrice && product.originalPrice > product.price && (
                  <p className="text-[10px] text-text-muted line-through opacity-70">₹{product.originalPrice.toLocaleString('en-IN')}</p>
                )}
              </div>
              <button 
                className="w-8 h-8 bg-accent text-white rounded-full flex items-center justify-center shadow-lg shadow-accent/20 active:scale-90 transition-transform"
                onClick={handleAddToCart}
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4v16m8-8H4" />
                </svg>
              </button>
            </div>

            <div className="flex items-center mt-2 pt-2 border-t border-border">
              <StarRating rating={product.rating} />
              <span className="text-[10px] text-text-muted font-bold ml-auto">{product.rating}</span>
            </div>
          </div>
        </Link>
      </GlassmorphicCard>
    </>
  );
};

export default ProductCard;

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useProducts } from '../hooks/useProducts';
import StarRating from '../components/StarRating';
import { ChevronLeftIcon } from '../components/icons/ChevronLeftIcon';
import { HeartIcon } from '../components/icons/HeartIcon';
import { ShareIcon } from '../components/icons/ShareIcon';
import { useCart } from '../hooks/useCart';
import { useAuth } from '../context/AuthContext';
import { useRecentlyViewed } from '../context/RecentlyViewedContext';
import ProductCard from '../components/ProductCard';
import { useVendors } from '../context/VendorContext';
import GlassmorphicCard from '../components/GlassmorphicCard';
import Toast from '../components/Toast';

type Tab = 'description' | 'highlights' | 'specs' | 'reviews' | 'shipping';

const ProductDetailPage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { products, getProduct } = useProducts();
  const { addToCart } = useCart();
  const { user, isAuthenticated, addToWishlist, removeFromWishlist, isInWishlist } = useAuth();
  const { addRecentlyViewed } = useRecentlyViewed();
  const { getVendorById } = useVendors();
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const [activeTab, setActiveTab] = useState<Tab>('description');
  const [showVideoModal, setShowVideoModal] = useState(false);
  const [showImageLightbox, setShowImageLightbox] = useState(false);
  const [showAddedToast, setShowAddedToast] = useState(false);

  const productId = parseInt(id || '');
  const product = getProduct(productId);
  const vendor = product ? getVendorById(product.vendorId) : null;

  const TABS: { id: Tab; label: string; isVisible: boolean }[] = [
    { id: 'description', label: 'Info', isVisible: !!product?.description },
    { id: 'highlights', label: 'Highlights', isVisible: !!product?.highlights && product.highlights.length > 0 },
    { id: 'specs', label: 'Specs', isVisible: !!product?.specifications && Object.keys(product.specifications).length > 0 },
    { id: 'reviews', label: 'Reviews', isVisible: true },
    { id: 'shipping', label: 'Delivery', isVisible: true },
  ];

  const visibleTabs = TABS.filter(t => t.isVisible);

  useEffect(() => {
    if (product && isAuthenticated) {
      addRecentlyViewed(product.id);
    }
    setCurrentImageIndex(0);
    setActiveTab(visibleTabs[0]?.id || 'description');
    window.scrollTo(0, 0);
  }, [productId, product, isAuthenticated]);

  if (!product) {
    return <div className="text-center p-8 text-text-main">Product not found</div>;
  }

  const isWishlisted = isInWishlist(product.id);
  const discount = product.originalPrice && product.originalPrice > product.price 
    ? Math.round(((product.originalPrice - product.price) / product.originalPrice) * 100) 
    : 0;

  const similarProducts = products.filter(p => p.category === product.category && p.id !== product.id && p.status === 'approved').slice(0, 4);

  const handleToggleWishlist = () => {
    if (!isAuthenticated) navigate('/login'); else isWishlisted ? removeFromWishlist(product.id) : addToWishlist(product.id);
  };

  const handleShare = () => {
    if (navigator.share) {
      navigator.share({
        title: product.name,
        text: `Check out this product: ${product.name}`,
        url: window.location.href,
      }).catch(console.error);
    } else {
      navigator.clipboard.writeText(window.location.href);
      alert('Link copied to clipboard!');
    }
  };

  const handleAddToCart = () => { 
    addToCart(product); 
    setShowAddedToast(true);
  };

  const handleBuyNow = () => { addToCart(product); navigate('/checkout'); };

  const renderTabContent = () => {
    switch (activeTab) {
      case 'description': return <p className="text-text-secondary leading-relaxed text-sm font-medium">{product.description}</p>;
      case 'highlights': return (
        <ul className="space-y-4">
          {product.highlights?.map((h, i) => (
            <li key={i} className="flex items-start gap-3 text-sm font-medium text-text-secondary">
              <div className="w-5 h-5 rounded-full bg-accent/10 flex items-center justify-center shrink-0 mt-0.5">
                <svg className="w-3 h-3 text-accent" fill="currentColor" viewBox="0 0 20 20">
                  <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
                </svg>
              </div>
              <span>{h}</span>
            </li>
          ))}
        </ul>
      );
      case 'specs': return (
        <div className="space-y-1">
          {Object.entries(product.specifications || {}).map(([key, value]) => (
            <div key={key} className="flex border-b border-border py-4 last:border-0 group">
              <span className="w-1/3 text-text-muted uppercase text-[9px] font-black tracking-widest group-hover:text-accent transition-colors">{key}</span>
              <span className="w-2/3 text-text-main font-bold tracking-tight">{value}</span>
            </div>
          ))}
        </div>
      );
      case 'reviews': return (
        <div className="space-y-6">
          <div className="flex items-center gap-4 bg-surface p-6 rounded-2xl">
            <div className="text-center">
              <p className="text-4xl font-black text-text-main tracking-tighter">{product.rating || '0.0'}</p>
              <div className="mt-1"><StarRating rating={product.rating} /></div>
              <p className="text-[10px] font-bold text-text-muted mt-1 uppercase">{product.reviewCount} Ratings</p>
            </div>
            <div className="flex-grow space-y-1">
              {[5, 4, 3, 2, 1].map(num => (
                <div key={num} className="flex items-center gap-2">
                  <span className="text-[9px] font-bold text-text-muted w-2">{num}</span>
                  <div className="flex-grow h-1.5 bg-border rounded-full overflow-hidden">
                    <div className="h-full bg-accent" style={{ width: `${(product.reviews.filter(r => r.rating === num).length / (product.reviewCount || 1)) * 100}%` }}></div>
                  </div>
                </div>
              ))}
            </div>
          </div>
          <div className="space-y-4">
            {product.reviews.length > 0 ? product.reviews.map((review) => (
              <div key={review.id} className="p-4 border border-border rounded-xl">
                <div className="flex justify-between items-start mb-2">
                  <div>
                    <div className="flex items-center gap-2">
                      <span className="text-xs font-bold text-text-main">{review.author}</span>
                      <span className="bg-green-100 text-green-600 text-[8px] font-black px-1.5 py-0.5 rounded-sm uppercase tracking-tighter">Verified</span>
                    </div>
                    <StarRating rating={review.rating} />
                  </div>
                  <span className="text-[9px] text-text-muted font-bold">{new Date(review.date).toLocaleDateString([], { day: 'numeric', month: 'short' })}</span>
                </div>
                <p className="text-sm text-text-secondary italic">"{review.comment}"</p>
              </div>
            )) : (
              <p className="text-center py-8 text-text-muted italic text-sm">No verified reviews yet.</p>
            )}
          </div>
        </div>
      );
      case 'shipping': return <div className="space-y-6">
          <div className="flex items-center gap-4 p-4 border border-border rounded-2xl">
            <img src={vendor?.storeLogo} className="w-12 h-12 rounded-full border border-border" />
            <div>
              <p className="text-[9px] font-bold text-text-muted uppercase">Seller</p>
              <p className="font-bold text-text-main">{vendor?.storeName || 'VexoKart Direct'}</p>
            </div>
          </div>
          <div className="grid grid-cols-2 gap-4">
             <div className="p-4 bg-surface rounded-xl">
               <p className="text-[9px] font-bold text-text-muted uppercase mb-1">Return Policy</p>
               <p className="text-xs font-semibold text-text-secondary">{product.returnPolicy || '30-Day Returns'}</p>
             </div>
             <div className="p-4 bg-surface rounded-xl">
               <p className="text-[9px] font-bold text-text-muted uppercase mb-1">Warranty</p>
               <p className="text-xs font-semibold text-text-secondary">{product.warranty || '1 Year Brand'}</p>
             </div>
          </div>
        </div>;
      default: return null;
    }
  };

  return (
    <div className="min-h-screen bg-background pb-32">
      <Toast message="Added to bag" isVisible={showAddedToast} onClose={() => setShowAddedToast(false)} />
      {/* Navigation & Actions */}
      <div className="sticky top-0 z-30 flex items-center justify-between p-4 bg-white/80 backdrop-blur-md">
        <button onClick={() => navigate(-1)} className="p-2 bg-surface rounded-full text-text-main shadow-sm"><ChevronLeftIcon className="h-5 w-5" /></button>
        <div className="flex gap-2">
            <button onClick={handleShare} className="p-2 bg-surface rounded-full text-text-main shadow-sm"><ShareIcon className="w-5 h-5" /></button>
            <button onClick={handleToggleWishlist} className={`p-2 bg-surface rounded-full shadow-sm ${isWishlisted ? 'text-accent' : 'text-text-main'}`}><HeartIcon className="w-5 h-5" fill={isWishlisted ? 'currentColor' : 'none'}/></button>
        </div>
      </div>

      {/* Media Content */}
      <div className="relative w-full aspect-square bg-white flex items-center justify-center overflow-hidden mb-4">
          <img src={product.images[currentImageIndex]} className="max-w-full max-h-full object-contain p-8 animate-in fade-in zoom-in duration-500" />
          {product.images.length > 1 && (
            <div className="absolute bottom-6 flex gap-2">
              {product.images.map((_, i) => (
                <div key={i} className={`h-1.5 transition-all duration-300 rounded-full ${currentImageIndex === i ? 'w-6 bg-accent' : 'w-1.5 bg-border'}`}></div>
              ))}
            </div>
          )}
      </div>

      {/* Info Section */}
      <div className="px-6 space-y-4">
        <div className="space-y-1">
          <div className="flex items-center gap-2">
            <span className="text-[10px] font-extrabold text-accent bg-accent/10 px-2 py-0.5 rounded-full uppercase tracking-widest">{product.category}</span>
            <div className="flex items-center gap-1"><StarRating rating={product.rating} /><span className="text-[10px] font-bold text-text-muted">({product.reviewCount})</span></div>
          </div>
          <h1 className="text-2xl font-black text-text-main tracking-tight leading-tight uppercase italic">{product.name}</h1>
        </div>

        <div className="flex items-baseline gap-4">
          <p className="text-3xl font-black text-text-main tracking-tight">₹{product.price.toLocaleString('en-IN')}</p>
          {product.originalPrice && (
            <div className="flex items-center gap-2">
              <p className="text-base text-text-muted line-through opacity-60 italic">₹{product.originalPrice.toLocaleString('en-IN')}</p>
              <span className="text-xs font-black text-accent">{discount}% OFF</span>
            </div>
          )}
        </div>

        {/* Tab System */}
        <div className="pt-6">
          <div className="flex border-b border-border overflow-x-auto no-scrollbar scroll-smooth mb-6">
            {visibleTabs.map(tab => (
              <button key={tab.id} onClick={() => setActiveTab(tab.id)} className={`flex-shrink-0 px-5 py-3 text-[10px] font-black uppercase tracking-widest transition-all relative ${activeTab === tab.id ? 'text-accent' : 'text-text-muted'}`}>
                {tab.label}
                {activeTab === tab.id && <div className="absolute bottom-0 left-0 right-0 h-1 bg-accent rounded-t-full"></div>}
              </button>
            ))}
          </div>
          <div className="min-h-[100px]">{renderTabContent()}</div>
        </div>

        {/* Recommendations */}
        {similarProducts.length > 0 && (
          <div className="pt-10 border-t border-border">
             <h2 className="text-lg font-black text-text-main italic tracking-tighter uppercase mb-6">You might also like</h2>
             <div className="grid grid-cols-2 gap-4">
               {similarProducts.slice(0, 2).map(p => <ProductCard key={p.id} product={p} />)}
             </div>
          </div>
        )}
      </div>

      {/* Dynamic CTA Footer */}
      <div className="fixed bottom-0 left-0 right-0 p-4 bg-white border-t border-border flex items-center gap-3 z-50 shadow-[0_-4px_10px_rgba(0,0,0,0.02)]">
         <button onClick={handleAddToCart} className="flex-1 border-2 border-accent text-accent font-black uppercase tracking-widest text-xs py-4 rounded-2xl hover:bg-accent/5 transition-all active:scale-95">
            Add to Cart
         </button>
         <button onClick={handleBuyNow} className="flex-[1.5] bg-accent text-white font-black uppercase tracking-widest text-xs py-4 rounded-2xl shadow-xl shadow-accent/20 active:scale-95 transition-all">
            Buy Experience
         </button>
      </div>
    </div>
  );
};

export default ProductDetailPage;

import React, { useState } from 'react';
import { SearchIcon } from './icons/SearchIcon';
