import React, { createContext, useState, useContext, ReactNode, useEffect } from 'react';
import { GoogleGenAI } from '@google/genai';
import { NotificationLog, NotificationSettings, Order, User } from '../types';

interface NotificationContextType {
  settings: NotificationSettings;
  logs: NotificationLog[];
  updateSettings: (settings: Partial<NotificationSettings>) => void;
  notifyOrderUpdate: (order: Order, user: User) => Promise<void>;
  clearLogs: () => void;
}

const NotificationContext = createContext<NotificationContextType | undefined>(undefined);

const DEFAULT_SETTINGS: NotificationSettings = {
  emailEnabled: true,
  smsEnabled: true,
  smtpHost: 'smtp.gmail.com',
  smtpUser: '',
  smtpPass: '',
  smsApiKey: '',
  testMode: true,
};

export const NotificationProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [settings, setSettings] = useState<NotificationSettings>(() => {
    const local = localStorage.getItem('vexokart-notification-settings');
    return local ? JSON.parse(local) : DEFAULT_SETTINGS;
  });

  const [logs, setLogs] = useState<NotificationLog[]>(() => {
    const local = localStorage.getItem('vexokart-notification-logs');
    return local ? JSON.parse(local) : [];
  });

  useEffect(() => {
    localStorage.setItem('vexokart-notification-settings', JSON.stringify(settings));
  }, [settings]);

  useEffect(() => {
    localStorage.setItem('vexokart-notification-logs', JSON.stringify(logs));
  }, [logs]);

  const updateSettings = (newSettings: Partial<NotificationSettings>) => {
    setSettings(prev => ({ ...prev, ...newSettings }));
  };

  const addLog = (log: Omit<NotificationLog, 'id' | 'createdAt'>) => {
    const newLog: NotificationLog = {
      ...log,
      id: Math.random().toString(36).substr(2, 9),
      createdAt: new Date().toISOString(),
    };
    setLogs(prev => [newLog, ...prev].slice(0, 100)); // Keep last 100 logs
  };

  const clearLogs = () => setLogs([]);

  const notifyOrderUpdate = async (order: Order, user: User) => {
    if (!settings.testMode && !settings.emailEnabled && !settings.smsEnabled) return;

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

    // Generate professional message content using Gemini
    let aiContent = { email: '', sms: '' };
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Create a professional e-commerce notification for VexoKart.
        User: ${user.name}
        Order ID: #${order.id}
        Status: ${order.status}
        Total: ₹${order.total}

        Provide the response in JSON format with two fields: "emailBody" (markdown supported, friendly, professional) and "smsBody" (concise, max 160 chars).`,
        config: {
          responseMimeType: 'application/json'
        }
      });

      const parsed = JSON.parse(response.text || '{}');
      aiContent.email = parsed.emailBody || `Hi ${user.name}, your order #${order.id} is now ${order.status}.`;
      aiContent.sms = parsed.smsBody || `VexoKart: Order #${order.id} is ${order.status}. Thanks!`;
    } catch (err) {
      console.error("Gemini failed to generate content", err);
      aiContent.email = `Your order #${order.id} is ${order.status}.`;
      aiContent.sms = `VexoKart: Order #${order.id} is ${order.status}.`;
    }

    // Simulate Email Sending
    if (settings.emailEnabled || settings.testMode) {
      setTimeout(() => {
        console.log(`[TEST EMAIL] To: ${user.email} | Subject: Order ${order.status} | Content: ${aiContent.email}`);
        addLog({
          userId: user.email,
          orderId: order.id,
          channel: 'email',
          status: 'sent',
          response: settings.testMode ? 'Simulated Success (Test Mode)' : 'API Success',
          type: order.status
        });
      }, 1000);
    }

    // Simulate SMS Sending
    if ((settings.smsEnabled || settings.testMode) && order.shippingAddress.phone) {
      setTimeout(() => {
        console.log(`[TEST SMS] To: ${order.shippingAddress.phone} | Content: ${aiContent.sms}`);
        addLog({
          userId: user.email,
          orderId: order.id,
          channel: 'sms',
          status: 'sent',
          response: settings.testMode ? 'Simulated Success (Test Mode)' : 'API Success',
          type: order.status
        });
      }, 1500);
    }
  };

  return (
    <NotificationContext.Provider value={{ settings, logs, updateSettings, notifyOrderUpdate, clearLogs }}>
      {children}
    </NotificationContext.Provider>
  );
};

export const useNotifications = () => {
  const context = useContext(NotificationContext);
  if (!context) throw new Error('useNotifications must be used within NotificationProvider');
  return context;
};

import React, { createContext, useState, useEffect, ReactNode, useContext } from 'react';
import { Order, OrderStatus } from '../types';
import { useNotifications } from './NotificationContext';
import { useAuth } from './AuthContext';

interface OrderContextType {
  orders: Order[];
  addOrder: (order: Omit<Order, 'id' | 'date' | 'status' | 'statusHistory'>) => string;
  updateOrderStatus: (orderId: string, status: OrderStatus, details?: { courierName?: string; trackingId?: string }) => void;
  updateOrderPaymentDetails: (orderId: string, paymentId: string) => void;
  getOrderById: (orderId: string) => Order | undefined;
}

const OrderContext = createContext<OrderContextType | undefined>(undefined);

export const OrderProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const { notifyOrderUpdate } = useNotifications();
  const { user } = useAuth();
  const [orders, setOrders] = useState<Order[]>(() => {
    try {
      const localData = localStorage.getItem('vexokart-orders');
      return localData ? JSON.parse(localData) : [];
    } catch (error) {
      return [];
    }
  });

  const saveOrders = (updatedOrders: Order[]) => {
    localStorage.setItem('vexokart-orders', JSON.stringify(updatedOrders));
    setOrders(updatedOrders);
  };

  const addOrder = (orderData: Omit<Order, 'id' | 'date' | 'status' | 'statusHistory'>): string => {
    const timestamp = new Date().toISOString();
    const newOrder: Order = {
        ...orderData,
        id: new Date().getTime().toString().slice(-6),
        date: timestamp,
        status: 'Placed',
        statusHistory: [{ status: 'Placed', timestamp }]
    };
    saveOrders([newOrder, ...orders]);

    // Trigger notification
    if (user) {
      notifyOrderUpdate(newOrder, user);
    }

    return newOrder.id;
  };

  const updateOrderStatus = (orderId: string, status: OrderStatus, details: { courierName?: string; trackingId?: string } = {}) => {
    const orderToUpdate = orders.find(o => o.id === orderId);
    if (!orderToUpdate) return;

    const updated = orders.map(o => {
      if (o.id === orderId) {
        if (o.status === status) return o;
        return { 
          ...o, 
          status, 
          statusHistory: [...o.statusHistory, { status, timestamp: new Date().toISOString() }],
          courierName: details.courierName || o.courierName,
          trackingId: details.trackingId || o.trackingId,
        };
      }
      return o;
    });
    saveOrders(updated);

    // Trigger notification on status change
    const updatedOrder = updated.find(o => o.id === orderId);
    if (updatedOrder && user) {
        notifyOrderUpdate(updatedOrder, user);
    }
  };

  const updateOrderPaymentDetails = (orderId: string, paymentId: string) => {
    const updated = orders.map(o => {
      if (o.id === orderId) {
        const newStatus: OrderStatus = 'Confirmed';
        const newStatusHistory = o.status === 'Placed' 
            ? [...o.statusHistory, { status: newStatus, timestamp: new Date().toISOString() }] 
            : o.statusHistory;
        const updatedOrder = { ...o, paymentId, status: newStatus, statusHistory: newStatusHistory };

        // Notify Confirmed
        if (user) {
          notifyOrderUpdate(updatedOrder, user);
        }

        return updatedOrder;
      }
      return o;
    });
    saveOrders(updated);
  };

  const getOrderById = (orderId: string) => orders.find(o => o.id === orderId);

  return (
    <OrderContext.Provider value={{ orders, addOrder, updateOrderStatus, getOrderById, updateOrderPaymentDetails }}>
      {children}
    </OrderContext.Provider>
  );
};

export const useOrders = () => {
  const context = useContext(OrderContext);
  if (context === undefined) {
    throw new Error('useOrders must be used within a OrderProvider');
  }
  return context;
};

