import React, { createContext, useState, useEffect, ReactNode, useContext } from 'react';
import { Vendor } from '../types';

interface VendorContextType {
  vendors: Vendor[];
  addVendor: (vendorData: { userId: string; storeName: string }) => void;
  updateVendorStatus: (vendorId: string, status: 'approved' | 'rejected' | 'suspended', reason?: string) => void;
  updateVendorProfile: (vendorId: string, profileData: Partial<Vendor>) => void;
  getVendorByUserId: (userId: string) => Vendor | undefined;
  getVendorById: (vendorId: string) => Vendor | undefined;
}

export const VendorContext = createContext<VendorContextType | undefined>(undefined);

export const VendorProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [vendors, setVendors] = useState<Vendor[]>(() => {
    try {
      const localData = localStorage.getItem('vexokart-vendors');
      return localData ? JSON.parse(localData) : [];
    } catch (error) {
      return [];
    }
  });

  const saveVendors = (updatedVendors: Vendor[]) => {
    localStorage.setItem('vexokart-vendors', JSON.stringify(updatedVendors));
    setVendors(updatedVendors);
  };

  const addVendor = (vendorData: { userId: string; storeName: string }) => {
    const newVendor: Vendor = {
      id: new Date().getTime().toString(),
      userId: vendorData.userId,
      storeName: vendorData.storeName,
      storeLogo: `https://picsum.photos/seed/${vendorData.storeName}/200`,
      status: 'pending',
      kycDetails: {
        pan: '',
        gst: '',
        addressProofUrl: '',
        status: 'pending'
      },
      createdAt: new Date().toISOString()
    };
    saveVendors([...vendors, newVendor]);
  };

  const updateVendorStatus = (vendorId: string, status: 'approved' | 'rejected' | 'suspended', reason?: string) => {
    const updated = vendors.map(v => {
      if (v.id !== vendorId) return v;
      if (status === 'rejected' && reason) {
        return { ...v, status: 'rejected' as const, rejectionReason: reason };
      } else {
        const { rejectionReason, ...vendorWithoutReason } = v;
        return { ...vendorWithoutReason, status };
      }
    });
    saveVendors(updated);
  };

  const updateVendorProfile = (vendorId: string, profileData: Partial<Vendor>) => {
    const updated = vendors.map(v => v.id === vendorId ? { ...v, ...profileData } : v);
    saveVendors(updated);
  };

  const getVendorByUserId = (userId: string) => vendors.find(v => v.userId === userId);
  const getVendorById = (vendorId: string) => vendors.find(v => v.id === vendorId);

  return (
    <VendorContext.Provider value={{ vendors, addVendor, updateVendorStatus, getVendorByUserId, getVendorById, updateVendorProfile }}>
      {children}
    </VendorContext.Provider>
  );
};

export const useVendors = () => {
  const context = useContext(VendorContext);
  if (context === undefined) {
    throw new Error('useVendors must be used within a VendorProvider');
  }
  return context;
};

import React, { createContext, useState, useContext, ReactNode, useEffect } from 'react';
import { GoogleGenAI } from '@google/genai';
import { NotificationLog, NotificationSettings, Order, User } from '../types';

interface NotificationContextType {
  settings: NotificationSettings;
  logs: NotificationLog[];
  updateSettings: (settings: Partial<NotificationSettings>) => void;
  notifyOrderUpdate: (order: Order, user: User) => Promise<void>;
  clearLogs: () => void;
}

const NotificationContext = createContext<NotificationContextType | undefined>(undefined);

const DEFAULT_SETTINGS: NotificationSettings = {
  emailEnabled: true,
  smsEnabled: true,
  smtpHost: 'api.sendgrid.com',
  smtpUser: '',
  smtpPass: '',
  emailFrom: 'VexoKart Support <support@vexokart.com>',
  smsApiKey: '',
  smsSenderId: 'VXKART',
  smsTemplateId: '',
  testMode: true, // Switched to true by default for safe browser previewing
};

export const NotificationProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [settings, setSettings] = useState<NotificationSettings>(() => {
    const local = localStorage.getItem('vexokart-notification-settings');
    return local ? JSON.parse(local) : DEFAULT_SETTINGS;
  });

  const [logs, setLogs] = useState<NotificationLog[]>(() => {
    const local = localStorage.getItem('vexokart-notification-logs');
    return local ? JSON.parse(local) : [];
  });

  useEffect(() => {
    localStorage.setItem('vexokart-notification-settings', JSON.stringify(settings));
  }, [settings]);

  useEffect(() => {
    localStorage.setItem('vexokart-notification-logs', JSON.stringify(logs));
  }, [logs]);

  const updateSettings = (newSettings: Partial<NotificationSettings>) => {
    setSettings(prev => ({ ...prev, ...newSettings }));
  };

  const addLog = (log: Omit<NotificationLog, 'id' | 'createdAt'>) => {
    const newLog: NotificationLog = {
      ...log,
      id: Math.random().toString(36).substr(2, 9),
      createdAt: new Date().toISOString(),
    };
    setLogs(prev => [newLog, ...prev].slice(0, 100));
  };

  const notifyOrderUpdate = async (order: Order, user: User) => {
    if (!settings.emailEnabled && !settings.smsEnabled && !settings.testMode) return;

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

    let aiContent = { email: '', sms: '' };
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Generate a production-ready transactional notification for VexoKart.
        User Name: ${user.name}
        Order ID: #${order.id}
        Status: ${order.status}
        Total Amount: ₹${order.total}

        Output JSON with:
        "emailBody": (Professional HTML/Markdown)
        "smsBody": (Strictly max 150 chars, start with "VexoKart: ")`,
        config: { responseMimeType: 'application/json' }
      });

      const parsed = JSON.parse(response.text || '{}');
      aiContent.email = parsed.emailBody;
      aiContent.sms = parsed.smsBody;
    } catch (err) {
      aiContent.email = `Order #${order.id} is ${order.status}. Thank you!`;
      aiContent.sms = `VexoKart: Order #${order.id} is ${order.status}.`;
    }

    const sendWithRetry = async (
        channel: 'email' | 'sms', 
        sendFn: () => Promise<any>, 
        maxRetries = 2
    ) => {
      let attempts = 0;
      while (attempts <= maxRetries) {
        try {
          if (settings.testMode) {
            await new Promise(r => setTimeout(r, 600));
            addLog({ userId: user.email, orderId: order.id, channel, status: 'sent', response: 'Sandbox Simulation Success', type: order.status, retryCount: attempts });
            return;
          }

          const result = await sendFn();
          addLog({ userId: user.email, orderId: order.id, channel, status: 'sent', response: 'Live Provider Accepted', type: order.status, retryCount: attempts });
          return result;
        } catch (error: any) {
          attempts++;

          // Handle common browser restriction errors (CORS/Network)
          let errorMsg = error.message || 'Unknown Error';
          if (errorMsg === 'Failed to fetch') {
            errorMsg = 'CORS Restriction: Production APIs (SendGrid/SMS) must be called from a server-side proxy, not directly from a browser.';
          }

          if (attempts > maxRetries) {
            addLog({ userId: user.email, orderId: order.id, channel, status: 'failed', response: errorMsg, type: order.status, retryCount: attempts - 1 });
            console.error(`[Production] ${channel} failed: ${errorMsg}`);
          } else {
            await new Promise(r => setTimeout(r, 1000));
          }
        }
      }
    };

    if (settings.emailEnabled) {
      await sendWithRetry('email', async () => {
        // NOTE: Standard browser 'fetch' to SendGrid will fail due to CORS.
        // In real production, this call must be made via a backend API endpoint (Node/Express/Next.js).
        const response = await fetch('https://api.sendgrid.com/v3/mail/send', {
          mode: 'cors',
          method: 'POST',
          headers: {
            'Authorization': `Bearer ${settings.smtpPass}`,
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({
            personalizations: [{ to: [{ email: user.email }] }],
            from: { email: 'support@vexokart.com', name: 'VexoKart' },
            subject: `Order Update: #${order.id}`,
            content: [{ type: 'text/html', value: aiContent.email }]
          })
        });
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
      });
    }

    if (settings.smsEnabled && order.shippingAddress.phone) {
      await sendWithRetry('sms', async () => {
        const response = await fetch('https://www.fast2sms.com/dev/bulkV2', {
          method: 'POST',
          headers: {
            'authorization': settings.smsApiKey,
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({
            route: 'transactional',
            sender_id: settings.smsSenderId,
            message: aiContent.sms,
            numbers: order.shippingAddress.phone,
          })
        });
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
      });
    }
  };

  const clearLogs = () => setLogs([]);

  return (
    <NotificationContext.Provider value={{ settings, logs, updateSettings, notifyOrderUpdate, clearLogs }}>
      {children}
    </NotificationContext.Provider>
  );
};

export const useNotifications = () => {
  const context = useContext(NotificationContext);
  if (!context) throw new Error('useNotifications must be used within NotificationProvider');
  return context;
};

