import React, { createContext, useState, useEffect, ReactNode, useContext } from 'react';
import { User, Address } from '../types';
import { VendorContext } from './VendorContext';
import { AdminCodeContext } from './AdminCodeContext';
import { BASE_API_URL, API_HEADERS } from '../constants';

interface AuthContextType {
  user: User | null;
  users: User[];
  isLoading: boolean;
  isAuthenticated: boolean;
  login: (email: string, pass: string) => Promise<void>;
  signup: (name: string, email: string, pass: string) => Promise<void>;
  signupAsVendor: (name: string, email: string, pass: string, storeName: string, adminCode: string) => Promise<void>;
  logout: () => void;
  addUser: (userData: { name: string; email: string; pass: string; role: 'USER' | 'VENDOR' | 'SUPER_ADMIN' }) => Promise<void>;
  addAddress: (address: Omit<Address, 'id'>) => Promise<void>;
  updateAddress: (address: Address) => Promise<void>;
  deleteAddress: (addressId: string) => Promise<void>;
  deleteUser: (email: string) => Promise<void>;
  addToWishlist: (productId: number) => Promise<void>;
  removeFromWishlist: (productId: number) => Promise<void>;
  isInWishlist: (productId: number) => boolean;
  updateUserSession: (userData: User) => void;
  fetchUsers: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const vendorContext = useContext(VendorContext);
  const adminCodeContext = useContext(AdminCodeContext);

  const fetchUsers = async () => {
    try {
      const response = await fetch(`${BASE_API_URL}/users?select=*`, { headers: API_HEADERS });
      const data = await response.json();
      setAllUsers(data);
    } catch (error) {
      console.error("Error fetching users:", error);
    }
  };

  useEffect(() => {
    const init = async () => {
      setIsLoading(true);
      await fetchUsers();
      const session = localStorage.getItem('vexokart-session-email');
      if (session) {
        try {
          const res = await fetch(`${BASE_API_URL}/users?email=eq.${session}&select=*`, { headers: API_HEADERS });
          const userData = await res.json();
          if (userData && userData.length > 0) {
            setUser(userData[0]);
          }
        } catch (e) {
          console.error("Session restore failed", e);
        }
      }
      setIsLoading(false);
    };
    init();
  }, []);

  const updateUserSession = (userData: User) => {
    setUser(userData);
    localStorage.setItem('vexokart-session-email', userData.email);
  };

  const login = async (email: string, pass: string) => {
    const res = await fetch(`${BASE_API_URL}/users?email=eq.${email}&password=eq.${pass}&select=*`, { headers: API_HEADERS });
    const data = await res.json();
    if (data && data.length > 0) {
      updateUserSession(data[0]);
      return;
    }
    throw new Error('Invalid email or password');
  };

  const signup = async (name: string, email: string, pass: string) => {
    const check = await fetch(`${BASE_API_URL}/users?email=eq.${email}`, { headers: API_HEADERS });
    const existing = await check.json();
    if (existing.length > 0) throw new Error('Account already exists');

    const newUser = {
      name,
      email,
      password: pass,
      role: 'USER',
      addresses: [],
      wishlist: [],
      recentlyViewed: []
    };

    const res = await fetch(`${BASE_API_URL}/users`, {
      method: 'POST',
      headers: API_HEADERS,
      body: JSON.stringify(newUser)
    });

    if (!res.ok) throw new Error('Failed to create account');
    updateUserSession(newUser as any);
    await fetchUsers();
  };

  const signupAsVendor = async (name: string, email: string, pass: string, storeName: string, adminCode: string) => {
    const validation = adminCodeContext?.validateAndUseCode(adminCode, email);
    if (!validation || !validation.isValid) throw new Error(validation?.message || 'Invalid code');

    const newUser = {
      name,
      email,
      password: pass,
      role: 'VENDOR',
      addresses: [],
      wishlist: [],
      recentlyViewed: []
    };

    const res = await fetch(`${BASE_API_URL}/users`, {
      method: 'POST',
      headers: API_HEADERS,
      body: JSON.stringify(newUser)
    });

    if (!res.ok) throw new Error('Failed to create vendor account');

    await vendorContext?.addVendor({ userId: email, storeName });
    updateUserSession(newUser as any);
    await fetchUsers();
  };

  const logout = () => {
    localStorage.removeItem('vexokart-session-email');
    setUser(null);
  };

  const addUser = async (userData: any) => {
    await fetch(`${BASE_API_URL}/users`, {
      method: 'POST',
      headers: API_HEADERS,
      body: JSON.stringify({ ...userData, addresses: [], wishlist: [], recentlyViewed: [] })
    });
    if (userData.role === 'VENDOR') {
      await vendorContext?.addVendor({ userId: userData.email, storeName: `${userData.name}'s Store` });
    }
    await fetchUsers();
  };

  const addAddress = async (address: Omit<Address, 'id'>) => {
    if (!user) return;
    const newAddress = { ...address, id: Date.now().toString() };
    const updatedAddresses = [...user.addresses, newAddress];
    await fetch(`${BASE_API_URL}/users?email=eq.${user.email}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify({ addresses: updatedAddresses })
    });
    setUser({ ...user, addresses: updatedAddresses });
  };

  const updateAddress = async (address: Address) => {
    if (!user) return;
    const updatedAddresses = user.addresses.map(a => a.id === address.id ? address : a);
    await fetch(`${BASE_API_URL}/users?email=eq.${user.email}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify({ addresses: updatedAddresses })
    });
    setUser({ ...user, addresses: updatedAddresses });
  };

  const deleteAddress = async (addressId: string) => {
    if (!user) return;
    const updatedAddresses = user.addresses.filter(a => a.id !== addressId);
    await fetch(`${BASE_API_URL}/users?email=eq.${user.email}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify({ addresses: updatedAddresses })
    });
    setUser({ ...user, addresses: updatedAddresses });
  };

  const deleteUser = async (email: string) => {
    if (email === 'admin@vexokart.com') return;
    await fetch(`${BASE_API_URL}/users?email=eq.${email}`, { method: 'DELETE', headers: API_HEADERS });
    await fetchUsers();
  };

  const addToWishlist = async (productId: number) => {
    if (!user || user.wishlist.includes(productId)) return;
    const updated = [...user.wishlist, productId];
    await fetch(`${BASE_API_URL}/users?email=eq.${user.email}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify({ wishlist: updated })
    });
    setUser({ ...user, wishlist: updated });
  };

  const removeFromWishlist = async (productId: number) => {
    if (!user) return;
    const updated = user.wishlist.filter(id => id !== productId);
    await fetch(`${BASE_API_URL}/users?email=eq.${user.email}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify({ wishlist: updated })
    });
    setUser({ ...user, wishlist: updated });
  };

  const isInWishlist = (productId: number) => user?.wishlist.includes(productId) || false;

  return (
    <AuthContext.Provider value={{ 
      user, users: allUsers, isLoading, isAuthenticated: !!user, 
      login, signup, logout, addUser, addAddress, updateAddress, 
      deleteAddress, deleteUser, addToWishlist, removeFromWishlist, 
      isInWishlist, updateUserSession, signupAsVendor, fetchUsers 
    }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) throw new Error('useAuth must be used within an AuthProvider');
  return context;
};

import React, { createContext, useState, useEffect, ReactNode, useContext } from 'react';
import { Product, Review } from '../types';
import { BASE_API_URL, API_HEADERS } from '../constants';

interface ProductContextType {
  products: Product[];
  isLoading: boolean;
  getProduct: (id: number) => Product | undefined;
  addProduct: (product: Omit<Product, 'id' | 'rating' | 'reviewCount' | 'reviews' | 'status'>) => Promise<void>;
  updateProduct: (product: Product) => Promise<void>;
  deleteProduct: (productId: number) => Promise<void>;
  toggleProductStatus: (productId: number) => Promise<void>;
  approveProduct: (productId: number, approvedBy?: string) => Promise<void>;
  rejectProduct: (productId: number, reason: string) => Promise<void>;
  disableProduct: (productId: number) => Promise<void>;
  addReview: (productId: number, reviewData: Omit<Review, 'id' | 'date'>) => Promise<void>;
  refreshProducts: () => Promise<void>;
}

export const ProductContext = createContext<ProductContextType | undefined>(undefined);

export const ProductProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [products, setProducts] = useState<Product[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const refreshProducts = async () => {
    try {
      const response = await fetch(`${BASE_API_URL}/products?select=*`, { headers: API_HEADERS });
      const data = await response.json();
      setProducts(data);
    } catch (error) {
      console.error("Error fetching products:", error);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    refreshProducts();
  }, []);

  const getProduct = (id: number) => products.find(p => p.id === id);

  const addProduct = async (productData: any) => {
    const newProduct = {
      ...productData,
      rating: 0,
      reviewCount: 0,
      reviews: [],
      status: 'pending',
      highlights: productData.highlights || [],
      specifications: productData.specifications || {}
    };
    await fetch(`${BASE_API_URL}/products`, {
      method: 'POST',
      headers: API_HEADERS,
      body: JSON.stringify(newProduct)
    });
    await refreshProducts();
  };

  const updateProduct = async (product: Product) => {
    await fetch(`${BASE_API_URL}/products?id=eq.${product.id}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify(product)
    });
    await refreshProducts();
  };

  const deleteProduct = async (productId: number) => {
    await fetch(`${BASE_API_URL}/products?id=eq.${productId}`, {
      method: 'DELETE',
      headers: API_HEADERS
    });
    await refreshProducts();
  };

  const toggleProductStatus = async (productId: number) => {
    const p = getProduct(productId);
    if (!p) return;
    const newStatus = p.status === 'approved' ? 'disabled' : 'approved';
    await fetch(`${BASE_API_URL}/products?id=eq.${productId}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify({ status: newStatus })
    });
    await refreshProducts();
  };

  const approveProduct = async (productId: number, approvedBy?: string) => {
    await fetch(`${BASE_API_URL}/products?id=eq.${productId}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify({ 
        status: 'approved', 
        approved_by: approvedBy, 
        approved_at: new Date().toISOString() 
      })
    });
    await refreshProducts();
  };

  const rejectProduct = async (productId: number, reason: string) => {
    await fetch(`${BASE_API_URL}/products?id=eq.${productId}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify({ status: 'rejected', rejectionReason: reason })
    });
    await refreshProducts();
  };

  const disableProduct = async (productId: number) => {
    await fetch(`${BASE_API_URL}/products?id=eq.${productId}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify({ status: 'disabled' })
    });
    await refreshProducts();
  };

  const addReview = async (productId: number, reviewData: any) => {
    const p = getProduct(productId);
    if (!p) return;
    const newReview = { ...reviewData, id: Math.random().toString(36).substr(2, 9), date: new Date().toISOString() };
    const updatedReviews = [newReview, ...p.reviews];
    const newCount = updatedReviews.length;
    const newRating = Number(((p.rating * p.reviewCount + reviewData.rating) / newCount).toFixed(1));

    await fetch(`${BASE_API_URL}/products?id=eq.${productId}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify({ reviews: updatedReviews, reviewCount: newCount, rating: newRating })
    });
    await refreshProducts();
  };

  return (
    <ProductContext.Provider value={{ 
      products, isLoading, getProduct, addProduct, updateProduct, 
      deleteProduct, toggleProductStatus, approveProduct, rejectProduct, 
      disableProduct, addReview, refreshProducts 
    }}>
      {children}
    </ProductContext.Provider>
  );
};

import React, { createContext, useState, useEffect, ReactNode, useContext } from 'react';
import { Order, OrderStatus } from '../types';
import { useNotifications } from './NotificationContext';
import { useAuth } from './AuthContext';
import { BASE_API_URL, API_HEADERS } from '../constants';

interface OrderContextType {
  orders: Order[];
  isLoading: boolean;
  addOrder: (order: Omit<Order, 'id' | 'date' | 'status' | 'statusHistory'>) => Promise<string>;
  updateOrderStatus: (orderId: string, status: OrderStatus, details?: { courierName?: string; trackingId?: string }) => Promise<void>;
  updateOrderPaymentDetails: (orderId: string, paymentId: string) => Promise<void>;
  updateOrderLabelInfo: (orderId: string, labelUrl: string) => Promise<string>;
  updateOrderByToken: (token: string, status: OrderStatus, note?: string) => Promise<{ success: boolean; message: string }>;
  getOrderById: (orderId: string) => Order | undefined;
  getOrderByToken: (token: string) => Order | undefined;
  refreshOrders: () => Promise<void>;
}

const OrderContext = createContext<OrderContextType | undefined>(undefined);

export const OrderProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const { notifyOrderUpdate } = useNotifications();
  const { users } = useAuth();
  const [orders, setOrders] = useState<Order[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const refreshOrders = async () => {
    try {
      const response = await fetch(`${BASE_API_URL}/orders?select=*&order=date.desc`, { headers: API_HEADERS });
      const data = await response.json();
      setOrders(data);
    } catch (e) {
      console.error("Orders sync failed", e);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    refreshOrders();
  }, []);

  const addOrder = async (orderData: any): Promise<string> => {
    const orderId = Math.random().toString(36).substr(2, 9).toUpperCase();
    const timestamp = new Date().toISOString();
    const newOrder = {
      ...orderData,
      id: orderId,
      date: timestamp,
      status: 'Placed',
      statusHistory: [{ status: 'Placed', timestamp }]
    };

    await fetch(`${BASE_API_URL}/orders`, {
      method: 'POST',
      headers: API_HEADERS,
      body: JSON.stringify(newOrder)
    });

    await refreshOrders();
    const orderUser = users.find(u => u.email === orderData.userEmail);
    if (orderUser) notifyOrderUpdate(newOrder as any, orderUser);

    return orderId;
  };

  const updateOrderStatus = async (orderId: string, status: OrderStatus, details: any = {}) => {
    const order = orders.find(o => o.id === orderId);
    if (!order || order.status === status) return;

    const updatedHistory = [...order.statusHistory, { status, timestamp: new Date().toISOString() }];
    const updateBody = { 
      status, 
      statusHistory: updatedHistory,
      courierName: details.courierName || order.courierName,
      trackingId: details.trackingId || order.trackingId
    };

    await fetch(`${BASE_API_URL}/orders?id=eq.${orderId}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify(updateBody)
    });

    await refreshOrders();
    const updatedOrder = { ...order, ...updateBody };
    const orderUser = users.find(u => u.email === order.userEmail);
    if (orderUser) notifyOrderUpdate(updatedOrder as any, orderUser);
  };

  const updateOrderPaymentDetails = async (orderId: string, paymentId: string) => {
    await fetch(`${BASE_API_URL}/orders?id=eq.${orderId}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify({ paymentId, status: 'Confirmed' })
    });
    await refreshOrders();
  };

  const updateOrderLabelInfo = async (orderId: string, labelUrl: string) => {
    const token = Math.random().toString(36).substring(2, 15);
    const expiry = new Date();
    expiry.setDate(expiry.getDate() + 7);

    await fetch(`${BASE_API_URL}/orders?id=eq.${orderId}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify({ 
        shippingLabelUrl: labelUrl, 
        labelGeneratedAt: new Date().toISOString(),
        qrToken: token,
        qrExpiresAt: expiry.toISOString()
      })
    });
    await refreshOrders();
    return token;
  };

  const updateOrderByToken = async (token: string, status: OrderStatus, note?: string) => {
    const order = orders.find(o => o.qrToken === token);
    if (!order) return { success: false, message: 'Invalid token' };

    const newLog = { id: Date.now().toString(), orderId: order.id, statusSet: status, note, scannedAt: new Date().toISOString() };
    const updatedHistory = [...order.statusHistory, { status, timestamp: new Date().toISOString() }];

    await fetch(`${BASE_API_URL}/orders?id=eq.${order.id}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify({ 
        status, 
        statusHistory: updatedHistory,
        qrUsedAt: new Date().toISOString(),
        scanLogs: [...(order.scanLogs || []), newLog]
      })
    });

    await refreshOrders();
    return { success: true, message: 'Status updated' };
  };

  const getOrderById = (id: string) => orders.find(o => o.id === id);
  const getOrderByToken = (token: string) => orders.find(o => o.qrToken === token);

  return (
    <OrderContext.Provider value={{ 
      orders, isLoading, addOrder, updateOrderStatus, updateOrderPaymentDetails, 
      updateOrderLabelInfo, updateOrderByToken, getOrderById, getOrderByToken, refreshOrders 
    }}>
      {children}
    </OrderContext.Provider>
  );
};

