          <NotificationProvider>
            <ProductProvider>
              <CategoryProvider>
                <BannerProvider>
                  <CartProvider>
                    <OrderProvider>
                      <RecentlyViewedProvider>
                        <HashRouter>
                          <AppContent />
                        </HashRouter>
                      </RecentlyViewedProvider>
                    </OrderProvider>
                  </CartProvider>
                </BannerProvider>
              </CategoryProvider>
            </ProductProvider>
          </NotificationProvider>
        </AuthProvider>
      </VendorProvider>
    </AdminCodeProvider>
  );
};

export default App;

