                </div>
              ))}
            </div>
          ) : (
             <p className="text-text-muted text-sm">No addresses found.</p>
          )}
          <button onClick={() => navigate('/addresses/new')} className="text-accent text-sm mt-3 font-semibold">Add New Address</button>
        </GlassmorphicCard>
        <GlassmorphicCard className="p-4">
