import React, { createContext, useState, useEffect, ReactNode, useContext } from 'react';
import { AdminCode } from '../types';
import { BASE_API_URL, API_HEADERS } from '../constants';

interface AdminCodeContextType {
  adminCodes: AdminCode[];
  generateCode: (note: string, expiresAt: string | null) => Promise<void>;
  revokeCode: (codeId: string) => Promise<void>;
  validateAndUseCode: (code: string, userId: string) => { isValid: boolean; message: string };
}

export const AdminCodeContext = createContext<AdminCodeContextType | undefined>(undefined);

export const AdminCodeProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [adminCodes, setAdminCodes] = useState<AdminCode[]>([]);

  const fetchCodes = async () => {
    try {
      const res = await fetch(`${BASE_API_URL}/admin_codes?select=*`, { headers: API_HEADERS });
      const data = await res.json();
      if (Array.isArray(data)) {
        setAdminCodes(data);
      } else {
        console.error("Admin codes fetch failed: API response is not an array", data);
        setAdminCodes([]);
      }
    } catch (error) {
      console.error("Error fetching admin codes:", error);
      setAdminCodes([]);
    }
  };

  useEffect(() => {
    fetchCodes();
  }, []);

  const generateCode = async (note: string, expiresAt: string | null) => {
    const code = 'ADMIN-' + Math.random().toString(36).substr(2, 6).toUpperCase();
    const newCode = {
      code,
      status: 'unused',
      createdAt: new Date().toISOString(),
      expiresAt,
      note,
      maxUsage: 1,
      usageCount: 0
    };
    await fetch(`${BASE_API_URL}/admin_codes`, {
      method: 'POST',
      headers: API_HEADERS,
      body: JSON.stringify(newCode)
    });
    await fetchCodes();
  };

  const revokeCode = async (id: string) => {
    await fetch(`${BASE_API_URL}/admin_codes?id=eq.${id}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify({ status: 'revoked' })
    });
    await fetchCodes();
  };

  const validateAndUseCode = (code: string, userId: string) => {
    const target = adminCodes.find(c => c.code === code);
    if (!target || target.status !== 'unused') return { isValid: false, message: 'Invalid code' };

    // In a real app, we would use an RPC or transaction. 
    // Here we just update via PATCH.
    fetch(`${BASE_API_URL}/admin_codes?id=eq.${target.id}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify({ status: 'used', usedBy: userId, usageCount: target.usageCount + 1 })
    }).then(fetchCodes);

    return { isValid: true, message: 'Code accepted' };
  };

  return (
    <AdminCodeContext.Provider value={{ adminCodes, generateCode, revokeCode, validateAndUseCode }}>
      {children}
    </AdminCodeContext.Provider>
  );
};

// Export useAdminCodes hook for accessing admin code context
export const useAdminCodes = () => {
  const context = useContext(AdminCodeContext);
  if (context === undefined) {
    throw new Error('useAdminCodes must be used within an AdminCodeProvider');
  }
  return context;
};

import React, { createContext, useState, useEffect, ReactNode, useContext } from 'react';
import { Banner } from '../types';
import { BASE_API_URL, API_HEADERS } from '../constants';

interface BannerContextType {
  banners: Banner[];
  addBanner: (imageUrl: string) => Promise<void>;
  deleteBanner: (id: string) => Promise<void>;
  toggleBannerStatus: (id: string) => Promise<void>;
  updateBannerOrder: (id: string, newOrder: number) => Promise<void>;
}

const BannerContext = createContext<BannerContextType | undefined>(undefined);

export const BannerProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [banners, setBanners] = useState<Banner[]>([]);

  const fetchBanners = async () => {
    try {
      const res = await fetch(`${BASE_API_URL}/banners?select=*`, { headers: API_HEADERS });
      const data = await res.json();
      if (Array.isArray(data)) {
        setBanners(data);
      } else {
        console.error("Banners fetch failed: API response is not an array", data);
        setBanners([]);
      }
    } catch (error) {
      console.error("Error fetching banners:", error);
      setBanners([]);
    }
  };

  useEffect(() => {
    fetchBanners();
  }, []);

  const addBanner = async (url: string) => {
    await fetch(`${BASE_API_URL}/banners`, {
      method: 'POST',
      headers: API_HEADERS,
      body: JSON.stringify({ imageUrl: url, status: 'active', displayOrder: banners.length, createdAt: new Date().toISOString() })
    });
    await fetchBanners();
  };

  const deleteBanner = async (id: string) => {
    await fetch(`${BASE_API_URL}/banners?id=eq.${id}`, { method: 'DELETE', headers: API_HEADERS });
    await fetchBanners();
  };

  const toggleBannerStatus = async (id: string) => {
    const b = banners.find(x => x.id === id);
    if (!b) return;
    await fetch(`${BASE_API_URL}/banners?id=eq.${id}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify({ status: b.status === 'active' ? 'inactive' : 'active' })
    });
    await fetchBanners();
  };

  const updateBannerOrder = async (id: string, order: number) => {
    await fetch(`${BASE_API_URL}/banners?id=eq.${id}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify({ displayOrder: order })
    });
    await fetchBanners();
  };

  return (
    <BannerContext.Provider value={{ banners, addBanner, deleteBanner, toggleBannerStatus, updateBannerOrder }}>
      {children}
    </BannerContext.Provider>
  );
};

