                  </td>
                  <td className="p-6 text-right space-x-2 whitespace-nowrap">
                    <button onClick={() => navigate(`/vendor/products/edit/${product.id}`)} className="text-accent text-[10px] font-black uppercase hover:underline">Edit</button>
