import React, { useState } from 'react';
import { Order, OrderStatus } from '../../types';
import GlassmorphicCard from '../../components/GlassmorphicCard';
import { useAuth } from '../../context/AuthContext';
import { useVendors } from '../../context/VendorContext';
import { useProducts } from '../../hooks/useProducts';
import { useOrders } from '../../context/OrderContext';
import ShippingDetailsModal from '../../components/admin/ShippingDetailsModal';
import ShippingLabelModal from '../../components/vendor/ShippingLabelModal';

const VENDOR_UPDATABLE_STATUSES: OrderStatus[] = ['Packed', 'Shipped', 'Out for Delivery'];

const VendorOrdersPage: React.FC = () => {
    const { user } = useAuth();
    const { getVendorByUserId } = useVendors();
    const { products } = useProducts();
    const { orders, updateOrderStatus, updateOrderLabelInfo } = useOrders();

    const [statusFilter, setStatusFilter] = useState<string>('all');
    const [selectedOrder, setSelectedOrder] = useState<Order | null>(null);
    const [isShippingModalOpen, setShippingModalOpen] = useState(false);
    const [labelOrder, setLabelOrder] = useState<Order | null>(null);

    const vendor = user ? getVendorByUserId(user.email) : null;
    const vendorProducts = vendor ? products.filter(p => p.vendorId === vendor.id.toString()) : [];

    const vendorOrders = orders.map(order => {
        const vendorItems = order.items.filter(item => 
            vendorProducts.some(p => p.id === item.id)
        );
        if (vendorItems.length === 0) return null;
        return { ...order, items: vendorItems };
    }).filter((o): o is Order => {
        if (!o) return false;
        if (statusFilter === 'all') return true;
        if (statusFilter === 'pending') return ['Placed', 'Confirmed', 'Packed'].includes(o.status);
        return o.status === statusFilter;
    });

    const handleStatusChange = (order: Order, status: OrderStatus) => {
        if (status === 'Shipped') {
            setSelectedOrder(order);
            setShippingModalOpen(true);
        } else {
            updateOrderStatus(order.id, status);
        }
    };

    const handleShippingSubmit = (courierName: string, trackingId: string) => {
        if (selectedOrder) {
            updateOrderStatus(selectedOrder.id, 'Shipped', { courierName, trackingId });
        }
        setShippingModalOpen(false);
        setSelectedOrder(null);
    };

    const handleLabelGenerated = (url: string) => {
      if (labelOrder) {
        updateOrderLabelInfo(labelOrder.id, url);
      }
      setLabelOrder(null);
    };

    return (
        <div className="space-y-6">
            {isShippingModalOpen && (
                <ShippingDetailsModal
                    onClose={() => setShippingModalOpen(false)}
                    onSubmit={handleShippingSubmit}
                />
            )}

            {labelOrder && vendor && (
                <ShippingLabelModal
                  order={labelOrder}
                  vendor={vendor}
                  onClose={() => setLabelOrder(null)}
                  onGenerated={handleLabelGenerated}
                />
            )}

            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <div>
                  <h1 className="text-3xl font-black text-text-main italic tracking-tight uppercase">Order Management</h1>
                  <p className="text-text-muted mt-1 text-sm">Fulfill orders and update customers on shipping status.</p>
                </div>

                <div className="flex bg-surface p-1 rounded-xl border border-border">
                    {['all', 'pending', 'Shipped', 'Delivered'].map(f => (
                        <button
                            key={f}
                            onClick={() => setStatusFilter(f)}
                            className={`px-4 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === f ? 'bg-accent text-white shadow-lg' : 'text-text-muted hover:text-text-secondary'}`}
                        >
                            {f}
                        </button>
                    ))}
                </div>
            </div>

            <GlassmorphicCard>
                <div className="overflow-x-auto">
                    <table className="w-full text-left text-sm">
                        <thead>
                            <tr className="border-b border-white/5 text-text-muted text-[10px] uppercase font-black tracking-widest">
                                <th className="p-6">Order Reference</th>
                                <th className="p-6">Customer</th>
                                <th className="p-6">Line Items</th>
                                <th className="p-6">Current Status</th>
                                <th className="p-6 text-right">Fulfillment</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-white/5">
                            {vendorOrders.map(order => (
                                <tr key={order.id} className="hover:bg-white/[0.02] transition-colors">
                                    <td className="p-6">
                                        <p className="text-text-main font-mono font-bold">#{order.id}</p>
                                        <p className="text-[10px] text-text-muted uppercase font-bold mt-1">{new Date(order.date).toLocaleDateString()}</p>
                                    </td>
                                    <td className="p-6">
                                        <p className="text-text-main font-bold">{order.shippingAddress.fullName}</p>
                                        <p className="text-[10px] text-text-muted">{order.userEmail}</p>
                                    </td>
                                    <td className="p-6">
                                        <div className="flex -space-x-2">
                                          {order.items.slice(0, 3).map((item, idx) => (
                                            <img key={idx} src={item.image} className="w-8 h-8 rounded-full border border-background object-cover bg-surface" />
                                          ))}
                                          {order.items.length > 3 && (
                                            <div className="w-8 h-8 rounded-full border border-background bg-surface flex items-center justify-center text-[8px] font-bold text-text-muted">+{order.items.length - 3}</div>
                                          )}
                                        </div>
                                    </td>
                                    <td className="p-6">
                                        <span className={`px-2 py-1 rounded-md text-[9px] font-black uppercase tracking-widest border ${
                                          order.status === 'Cancelled' ? 'bg-red-500/10 text-red-500 border-red-500/20' :
                                          order.status === 'Delivered' ? 'bg-green-500/10 text-green-500 border-green-500/20' :
                                          'bg-accent/10 text-accent border-accent/20'
                                        }`}>
                                          {order.status}
                                        </span>
                                    </td>
                                    <td className="p-6 text-right">
                                        <div className="flex items-center justify-end gap-4">
                                            {['Confirmed', 'Packed'].includes(order.status) && (
                                                <button 
                                                  onClick={() => setLabelOrder(order)}
                                                  className={`flex items-center gap-2 px-3 py-1.5 rounded-lg border text-[10px] font-black uppercase transition-all ${order.shippingLabelUrl ? 'bg-green-500/10 text-green-500 border-green-500/20' : 'bg-surface text-text-main border-border hover:border-accent'}`}
                                                >
                                                   <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z" /></svg>
                                                   {order.shippingLabelUrl ? 'Label Ready' : 'Get Label'}
                                                </button>
                                            )}

                                            {['Cancelled', 'Delivered'].includes(order.status) ? (
                                                <span className="text-[10px] text-text-muted italic uppercase font-bold tracking-tight">Locked</span>
                                            ) : (
                                                <select
                                                    value=""
                                                    onChange={(e) => handleStatusChange(order, e.target.value as OrderStatus)}
                                                    className="bg-surface border border-white/10 rounded-lg py-1.5 px-3 text-[10px] font-black uppercase tracking-widest text-text-main focus:ring-accent focus:border-accent"
                                                >
                                                    <option value="" disabled>Set Status</option>
                                                    {VENDOR_UPDATABLE_STATUSES.map(s => <option key={s} value={s}>{s}</option>)}
                                                    <option value="Delivered">Mark Delivered</option>
                                                </select>
                                            )}
                                        </div>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                    {vendorOrders.length === 0 && (
                      <div className="p-20 text-center">
                        <p className="text-text-muted font-bold tracking-tight italic">No orders found matching your criteria.</p>
                      </div>
                    )}
                </div>
            </GlassmorphicCard>
        </div>
    );
};

export default VendorOrdersPage;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import { useVendors } from '../../context/VendorContext';
import GlassmorphicCard from '../../components/GlassmorphicCard';

const VendorProfilePage: React.FC = () => {
    const { user } = useAuth();
    const { getVendorByUserId, updateVendorProfile } = useVendors();
    const navigate = useNavigate();

    const vendor = user ? getVendorByUserId(user.email) : null;

    const [storeName, setStoreName] = useState('');
    const [storeLogo, setStoreLogo] = useState('');
    const [logoPreview, setLogoPreview] = useState('');
    const [storeAddress, setStoreAddress] = useState('');
    const [storePhone, setStorePhone] = useState('');

    const inputClasses = "w-full mt-1 bg-surface text-text-main border border-gray-600 rounded-lg p-3 transition focus:outline-none focus:border-accent focus:ring-2 focus:ring-accent/50";

    useEffect(() => {
        if (vendor) {
            setStoreName(vendor.store_name);
            setStoreLogo(vendor.profile_image);
            setLogoPreview(vendor.profile_image);
            setStoreAddress(vendor.store_address || '');
            setStorePhone(vendor.phone || '');
        }
    }, [vendor]);

    const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const reader = new FileReader();
            reader.onloadend = () => {
                const result = reader.result as string;
                setStoreLogo(result);
                setLogoPreview(result);
            };
            reader.readAsDataURL(e.target.files[0]);
        }
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (vendor) {
            updateVendorProfile(vendor.id, { 
                store_name: storeName, 
                profile_image: storeLogo,
                store_address: storeAddress,
                phone: storePhone
            });
            alert('Store profile updated successfully! Your details will now appear on shipping labels.');
            navigate('/vendor');
        }
    };

    if (!vendor) {
        return <div className="text-center p-8">Loading vendor profile...</div>;
    }

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center">
                <div>
                    <h1 className="text-3xl font-black text-text-main italic tracking-tight uppercase">Store Profile</h1>
                    <p className="text-text-muted mt-1">Configure your public storefront and dispatch settings.</p>
                </div>
            </div>

            <GlassmorphicCard className="p-8 max-w-3xl mx-auto">
                 <form onSubmit={handleSubmit} className="space-y-8">
                    <div className="flex flex-col items-center gap-6 pb-8 border-b border-border">
                        <div className="relative group">
                            <img src={logoPreview} alt="Logo Preview" className="w-32 h-32 rounded-3xl object-cover bg-background border-4 border-white shadow-2xl transition-transform group-hover:scale-105" />
                            <input type="file" id="logoUpload" accept="image/*" onChange={handleImageChange} className="hidden" />
                            <label htmlFor="logoUpload" className="absolute -bottom-2 -right-2 p-3 bg-accent text-white rounded-2xl shadow-xl cursor-pointer hover:bg-orange-600 transition-colors">
                                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
                            </label>
                        </div>
                        <div className="text-center">
                            <p className="text-lg font-black text-text-main tracking-tight italic uppercase">{storeName}</p>
                            <p className="text-xs text-text-muted font-bold uppercase tracking-widest mt-1">Vendor ID: {vendor.id}</p>
                        </div>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                         <div className="col-span-full">
                            <label className="text-[10px] font-black uppercase text-text-muted mb-1 block">Display Store Name</label>
                            <input 
                                type="text" 
                                value={storeName} 
                                onChange={(e) => setStoreName(e.target.value)} 
                                required 
                                className={inputClasses} 
                            />
                        </div>

                        <div>
                            <label className="text-[10px] font-black uppercase text-text-muted mb-1 block">Dispatch Phone Contact</label>
                            <input 
                                type="tel" 
                                value={storePhone} 
                                onChange={(e) => setStorePhone(e.target.value)} 
                                required 
                                placeholder="+91 XXXX XXX XXX"
                                className={inputClasses} 
                            />
                        </div>

                        <div className="col-span-full">
                            <label className="text-[10px] font-black uppercase text-text-muted mb-1 block">Warehouse / Pickup Address (Printed on Labels)</label>
                            <textarea 
                                value={storeAddress} 
                                onChange={(e) => setStoreAddress(e.target.value)} 
                                required 
                                rows={3}
                                placeholder="Full pickup address for couriers..."
                                className={`${inputClasses} resize-none`} 
                            />
                        </div>
                    </div>

                    <div className="flex justify-end gap-4 pt-6 border-t border-border">
                        <button type="button" onClick={() => navigate('/vendor')} className="px-8 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest text-text-secondary hover:bg-surface transition-all">Cancel</button>
                        <button type="submit" className="bg-accent text-white px-10 py-3 rounded-2xl font-black uppercase tracking-widest text-xs shadow-2xl shadow-accent/30 hover:-translate-y-1 active:translate-y-0 transition-all">Save Profile Settings</button>
                    </div>
                 </form>
            </GlassmorphicCard>
        </div>
    );
};

export default VendorProfilePage;

import React from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import { Vendor } from '../../types';
import GlassmorphicCard from '../../components/GlassmorphicCard';

interface VendorStatusPageProps {
  vendor: Vendor;
}

const StatusTimeline: React.FC<{ currentStatus: Vendor['status'] }> = ({ currentStatus }) => {
    const steps = ['Submitted', 'Under Review', 'Approved'];
    let activeIndex = 1; // "Under Review" is the default for pending
    if(currentStatus === 'approved') activeIndex = 2;

    return (
        <div className="flex items-center justify-center w-full max-w-sm mx-auto mt-8">
            {steps.map((step, index) => (
                <React.Fragment key={step}>
                    <div className="flex flex-col items-center text-center">
                        <div className={`w-8 h-8 rounded-full flex items-center justify-center border-2 transition-all duration-500 ${index <= activeIndex ? 'bg-accent border-accent' : 'bg-surface border-gray-600'}`}>
                           {index < activeIndex ? (
                             <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" /></svg>
                           ) : (
                             <span className={`w-3 h-3 rounded-full ${index === activeIndex ? 'bg-white animate-pulse' : 'bg-gray-500'}`}></span>
                           )}
                        </div>
                        <p className={`mt-2 text-xs font-semibold ${index <= activeIndex ? 'text-text-main' : 'text-text-muted'}`}>{step}</p>
                    </div>
                    {index < steps.length - 1 && (
                        <div className={`flex-1 h-1 transition-all duration-500 mx-2 ${index < activeIndex ? 'bg-accent' : 'bg-gray-600'}`}></div>
                    )}
                </React.Fragment>
            ))}
        </div>
    );
}

const VendorStatusPage: React.FC<VendorStatusPageProps> = ({ vendor }) => {
