export const CategoryProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [categories, setCategories] = useState<Category[]>([]);

  const fetchCategories = async () => {
    try {
      const res = await fetch(`${BASE_API_URL}/categories?select=*`, { 
        headers: { ...API_HEADERS, 'Cache-Control': 'no-cache' } 
      });
      const data = await res.json();

      if (Array.isArray(data)) {
        /**
         * SCHEMA ALIGNMENT:
         * Since 'image' and 'image_url' columns are missing in the Supabase table,
         * we generate a premium branded placeholder using the category name.
         */
        const mappedData = data.map((item: any) => ({
          id: item.id,
          name: item.name || 'Category',
          image: `https://ui-avatars.com/api/?name=${encodeURIComponent(item.name || 'C')}&background=FF8A00&color=fff&size=128&bold=true`
        }));
        setCategories(mappedData);
      } else {
        console.error("Categories fetch failed: API response is not an array", data);
        setCategories([]);
      }
    } catch (error) {
      console.error("Error fetching categories:", error);
      setCategories([]);
    }
  };

  useEffect(() => {
    fetchCategories();
  }, []);

  const addCategory = async (cat: any) => {
    /**
     * CORE FIX FOR PGRST204:
     * We only send 'name' and 'created_at'.
     * We EXCLUDE 'image' or 'image_url' because the database schema cache
     * explicitly states these columns do not exist.
     */
    const payload = {
      name: cat.name,
      created_at: new Date().toISOString()
    };

    const response = await fetch(`${BASE_API_URL}/categories`, {
      method: 'POST',
      headers: API_HEADERS,
      body: JSON.stringify(payload)
    });

    if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.message || `Failed to create category (${response.status})`);
    }

    await fetchCategories();
  };

  const updateCategory = async (cat: Category) => {
    /**
     * SAFE PATCH:
     * Only updating the 'name' field to avoid column-not-found errors.
     */
    const payload = {
      name: cat.name
    };

    const response = await fetch(`${BASE_API_URL}/categories?id=eq.${cat.id}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify(payload)
    });

    if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.message || `Failed to update category (${response.status})`);
    }

    await fetchCategories();
  };

  const deleteCategory = async (id: number) => {
    const response = await fetch(`${BASE_API_URL}/categories?id=eq.${id}`, {
      method: 'DELETE',
      headers: API_HEADERS
    });

    if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.message || `Failed to delete category (${response.status})`);
    }

    await fetchCategories();
  };

  const getCategory = (id: number) => categories.find(c => c.id === id);

  return (
    <CategoryContext.Provider value={{ categories, addCategory, updateCategory, deleteCategory, getCategory }}>
      {children}
    </CategoryContext.Provider>
  );
};

import React, { createContext, useState, useEffect, ReactNode, useContext } from 'react';
import { User, Address } from '../types';
import { VendorContext } from './VendorContext';
import { BASE_API_URL, API_HEADERS } from '../constants';

interface AuthContextType {
  user: User | null;
  users: User[];
  isLoading: boolean;
  isAuthenticated: boolean;
  login: (email: string, pass: string) => Promise<void>;
  signup: (name: string, email: string, phone: string, pass: string) => Promise<void>;
  signupAsVendor: (name: string, email: string, pass: string, storeName: string, code: string) => Promise<void>;
  logout: () => void;
  addUser: (userData: { name: string; email: string; phone: string; pass: string; role: User['role']; storeName?: string }) => Promise<void>;
  addAddress: (address: Omit<Address, 'id'>) => Promise<void>;
  updateAddress: (address: Address) => Promise<void>;
  deleteAddress: (addressId: string) => Promise<void>;
  deleteUser: (email: string) => Promise<void>;
  addToWishlist: (productId: number) => Promise<void>;
  removeFromWishlist: (productId: number) => Promise<void>;
  isInWishlist: (productId: number) => boolean;
  updateUserSession: (userData: User) => void;
  fetchUsers: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

/**
 * Helper to ensure a user object has all required array properties
 * to prevent 'not iterable' errors.
 */
const sanitizeUser = (u: any): User => ({
  ...u,
  addresses: Array.isArray(u.addresses) ? u.addresses : [],
  wishlist: Array.isArray(u.wishlist) ? u.wishlist : [],
  recentlyViewed: Array.isArray(u.recentlyViewed) ? u.recentlyViewed : []
});

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const vendorContext = useContext(VendorContext);

  const fetchUsers = async () => {
    try {
      const response = await fetch(`${BASE_API_URL}/users?select=*`, { 
        headers: { ...API_HEADERS, 'Cache-Control': 'no-cache' } 
      });
      const data = await response.json();
      if (Array.isArray(data)) {
        setAllUsers(data.map(sanitizeUser));
      } else {
        setAllUsers([]);
      }
    } catch (error) {
      console.error("Error fetching users:", error);
      setAllUsers([]);
    }
  };

  useEffect(() => {
    const init = async () => {
      setIsLoading(true);
      await fetchUsers();

      const sessionUser = localStorage.getItem('vexokart-user');
      if (sessionUser) {
        try {
          const parsed = JSON.parse(sessionUser);
          const res = await fetch(`${BASE_API_URL}/users?email=eq.${encodeURIComponent(parsed.email)}&select=*`, { headers: API_HEADERS });
          const userData = await res.json();
          if (Array.isArray(userData) && userData.length > 0) {
            setUser(sanitizeUser(userData[0]));
          }
        } catch (e) {
          console.error("Session restoration failed:", e);
        }
      }
      setIsLoading(false);
    };
    init();
  }, []);

  const updateUserSession = (userData: User) => {
    const safeUser = sanitizeUser(userData);
    setUser(safeUser);
    localStorage.setItem('vexokart-user', JSON.stringify(safeUser));
  };

  const login = async (email: string, pass: string) => {
    try {
      const query = `email=eq.${encodeURIComponent(email)}&password=eq.${encodeURIComponent(pass)}&select=*`;
      const res = await fetch(`${BASE_API_URL}/users?${query}`, { headers: API_HEADERS });
      const data = await res.json();

      if (Array.isArray(data) && data.length > 0) {
        const loggedUser = sanitizeUser(data[0]);
        setUser(loggedUser);
        localStorage.setItem('vexokart-user', JSON.stringify(loggedUser));
        return;
      }

      const checkRes = await fetch(`${BASE_API_URL}/users?email=eq.${encodeURIComponent(email)}&select=email`, { headers: API_HEADERS });
      const checkData = await checkRes.json();

      if (Array.isArray(checkData) && checkData.length === 0) {
          throw new Error('User not found. Please register first.');
      }

      throw new Error('Invalid email or password');
    } catch (err: any) {
      console.error("Login attempt failed:", err);
      throw new Error(err.message || 'Authentication error');
    }
  };

  const signup = async (name: string, email: string, phone: string, pass: string) => {
    const checkRes = await fetch(`${BASE_API_URL}/users?email=eq.${encodeURIComponent(email)}&select=email`, { headers: API_HEADERS });
    const existing = await checkRes.json();
    if (Array.isArray(existing) && existing.length > 0) throw new Error('Email already registered');

    const newUser = {
      name, email, phone, password: pass, role: 'user',
      addresses: [], wishlist: [], recentlyViewed: [], created_at: new Date().toISOString()
    };

    const res = await fetch(`${BASE_API_URL}/users`, {
      method: 'POST',
      headers: API_HEADERS,
      body: JSON.stringify(newUser)
    });

    if (!res.ok) {
        const err = await res.json();
        throw new Error(err.message || 'Signup failed. Please try again.');
    }
    await fetchUsers();
  };

  const signupAsVendor = async (name: string, email: string, pass: string, storeName: string, code: string) => {
     throw new Error("Direct vendor signup is managed via admin panel.");
  };

  const logout = () => {
    localStorage.removeItem('vexokart-user');
    setUser(null);
  };

  const addUser = async (userData: { name: string; email: string; phone: string; pass: string; role: User['role']; storeName?: string }) => {
    const newUser = {
      name: userData.name,
      email: userData.email,
      phone: userData.phone,
      password: userData.pass,
      role: userData.role,
      addresses: [],
      wishlist: [],
      recentlyViewed: [],
      created_at: new Date().toISOString()
    };

    const res = await fetch(`${BASE_API_URL}/users`, {
      method: 'POST',
      headers: { ...API_HEADERS, 'Prefer': 'return=representation' },
      body: JSON.stringify(newUser)
    });

    const createdUsers = await res.json();
    if (!res.ok) throw new Error(createdUsers.message || 'Failed to create user record');

    const createdUser = sanitizeUser(createdUsers[0]);

    if (userData.role === 'vendor' && vendorContext) {
        try {
            await vendorContext.addVendorRecord({
                user_id: createdUser.id.toString(),
                store_name: userData.storeName || `${userData.name}'s Store`,
                owner_name: userData.name,
                email: userData.email,
                phone: userData.phone,
                profile_image: `https://ui-avatars.com/api/?name=${encodeURIComponent(userData.storeName || userData.name)}&background=FF8A00&color=fff`,
                status: 'pending'
            });
            await vendorContext.refreshVendors();
        } catch (vErr) {
            console.error("Vendor profile link failed:", vErr);
        }
    }

    await fetchUsers();
  };

  const addAddress = async (address: Omit<Address, 'id'>) => {
    if (!user) return;
    const newAddress = { ...address, id: Date.now().toString() };
    const currentAddresses = Array.isArray(user.addresses) ? user.addresses : [];
    const updatedAddresses = [...currentAddresses, newAddress];

    await fetch(`${BASE_API_URL}/users?email=eq.${encodeURIComponent(user.email)}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify({ addresses: updatedAddresses })
    });
    setUser({ ...user, addresses: updatedAddresses });
  };

  const updateAddress = async (address: Address) => {
    if (!user) return;
    const currentAddresses = Array.isArray(user.addresses) ? user.addresses : [];
    const updatedAddresses = currentAddresses.map(a => a.id === address.id ? address : a);

    await fetch(`${BASE_API_URL}/users?email=eq.${encodeURIComponent(user.email)}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify({ addresses: updatedAddresses })
    });
    setUser({ ...user, addresses: updatedAddresses });
  };

  const deleteAddress = async (addressId: string) => {
    if (!user) return;
    const currentAddresses = Array.isArray(user.addresses) ? user.addresses : [];
    const updatedAddresses = currentAddresses.filter(a => a.id !== addressId);

    await fetch(`${BASE_API_URL}/users?email=eq.${encodeURIComponent(user.email)}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify({ addresses: updatedAddresses })
    });
    setUser({ ...user, addresses: updatedAddresses });
  };

  const deleteUser = async (email: string) => {
    if (email === 'admin@vexokart.com') return;
    await fetch(`${BASE_API_URL}/users?email=eq.${encodeURIComponent(email)}`, { method: 'DELETE', headers: API_HEADERS });
    await fetchUsers();
  };

  const addToWishlist = async (productId: number) => {
    if (!user) return;
    const currentWishlist = Array.isArray(user.wishlist) ? user.wishlist : [];
    if (currentWishlist.includes(productId)) return;

    const updated = [...currentWishlist, productId];
    await fetch(`${BASE_API_URL}/users?email=eq.${encodeURIComponent(user.email)}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify({ wishlist: updated })
    });
    setUser({ ...user, wishlist: updated });
  };

  const removeFromWishlist = async (productId: number) => {
    if (!user) return;
    const currentWishlist = Array.isArray(user.wishlist) ? user.wishlist : [];
    const updated = currentWishlist.filter(id => id !== productId);

    await fetch(`${BASE_API_URL}/users?email=eq.${encodeURIComponent(user.email)}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify({ wishlist: updated })
    });
    setUser({ ...user, wishlist: updated });
  };

  const isInWishlist = (productId: number) => {
    if (!user) return false;
    const currentWishlist = Array.isArray(user.wishlist) ? user.wishlist : [];
    return currentWishlist.includes(productId);
  };

  return (
    <AuthContext.Provider value={{ 
      user, users: allUsers, isLoading, isAuthenticated: !!user, 
      login, signup, signupAsVendor, logout, addUser, addAddress, updateAddress, 
      deleteAddress, deleteUser, addToWishlist, removeFromWishlist, 
      isInWishlist, updateUserSession, fetchUsers 
    }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) throw new Error('useAuth must be used within an AuthProvider');
  return context;
};

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useCart } from '../hooks/useCart';
import { useAuth } from '../context/AuthContext';
import { useOrders } from '../context/OrderContext';
import GlassmorphicCard from '../components/GlassmorphicCard';
import { ChevronLeftIcon } from '../components/icons/ChevronLeftIcon';
import { Address } from '../types';

const CheckoutPage: React.FC = () => {
  const { cartItems, cartTotal, clearCart } = useCart();
  const { user } = useAuth();
  const { addOrder, updateOrderPaymentDetails, updateOrderStatus } = useOrders();
  const navigate = useNavigate();
  const [paymentMethod, setPaymentMethod] = useState('card');
  const [orderPlaced, setOrderPlaced] = useState(false);
  const [selectedAddress, setSelectedAddress] = useState<Address | null>(null);

  useEffect(() => {
    if (user?.addresses && Array.isArray(user.addresses) && user.addresses.length > 0) {
      setSelectedAddress(user.addresses[0]);
    }
  }, [user]);

  const showSuccessAndNavigate = () => {
    setOrderPlaced(true);
    setTimeout(() => {
        clearCart();
        navigate('/');
    }, 3000);
  }

  const handlePlaceOrder = async () => {
    if (!selectedAddress || !user) {
      alert("Please select a shipping address.");
      return;
    }

    const orderPayload = {
        userEmail: user.email,
        items: cartItems.map(item => ({
            id: item.id,
            name: item.name,
            price: item.price,
            quantity: item.quantity,
            image: item.images[0]
        })),
        total: cartTotal,
        shippingAddress: selectedAddress,
        paymentMethod: paymentMethod === 'cod' ? 'Cash on Delivery' : 'Online Payment'
    };

    const newOrderId = await addOrder(orderPayload);

    if (paymentMethod === 'cod') {
      await updateOrderStatus(newOrderId, 'Confirmed');
      showSuccessAndNavigate();
      return;
    }

    const options = {
      key: 'rzp_test_RvSXZKknVfrNUA',
      amount: Math.round(cartTotal * 100),
      currency: 'INR',
      name: 'VexoKart',
      description: `Order #${newOrderId}`,
      image: 'https://picsum.photos/seed/logo/128/128',
      handler: async (response: any) => {
        await updateOrderPaymentDetails(newOrderId, response.razorpay_payment_id);
        showSuccessAndNavigate();
      },
      prefill: {
        name: user?.name || 'Customer',
        email: user?.email || '',
        contact: selectedAddress.phone || '',
      },
      theme: { color: '#FF8A00' },
    };

    const paymentObject = new (window as any).Razorpay(options);
    paymentObject.on('payment.failed', (response: any) => {
      alert(`Payment failed. Error: ${response.error.description}`);
      navigate('/orders');
    });
    paymentObject.open();
  };

  if (orderPlaced) {
    return (
        <div className="flex flex-col items-center justify-center min-h-screen text-center p-4">
             <svg xmlns="http://www.w3.org/2000/svg" className="h-24 w-24 text-green-400 mb-4 animate-bounce" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
            <h1 className="text-2xl font-bold text-text-main uppercase italic">Order Confirmed!</h1>
            <p className="text-text-muted mt-2 font-medium">Redirecting you to the home page...</p>
        </div>
    );
  }

  const addresses = (user?.addresses && Array.isArray(user.addresses)) ? user.addresses : [];

  return (
    <div className="bg-surface min-h-screen">
      <div className="sticky top-0 z-10 p-4 bg-white/80 backdrop-blur-md flex items-center border-b border-border shadow-sm">
        <button onClick={() => navigate('/cart')} className="p-2 -ml-2 mr-2">
          <ChevronLeftIcon className="h-6 w-6 text-text-main" />
        </button>
        <h1 className="text-xl font-black text-text-main italic tracking-tight uppercase">Checkout</h1>
      </div>

      <div className="p-4 space-y-6 pb-24 max-w-2xl mx-auto">
        <GlassmorphicCard className="p-6">
          <h2 className="text-[10px] font-black uppercase tracking-widest text-text-muted mb-4">Delivery Identity</h2>
          {addresses.length > 0 ? (
            <div className="space-y-3">
              {addresses.map(address => (
                <div 
