              <span className={`px-2 py-0.5 rounded text-[10px] font-black uppercase border ${getPaymentStatusColor(order.payment_status)}`}>
                {order.payment_status === 'cod_pending' ? 'COD Pending' : order.payment_status.toUpperCase()}
              </span>
            </div>
          </div>
        </GlassmorphicCard>

        <section>
