import React, { createContext, useState, useEffect, ReactNode, useContext } from 'react';
import { Order, OrderStatus, PaymentStatus } from '../types';
import { useNotifications } from './NotificationContext';
import { useAuth } from './AuthContext';
import { BASE_API_URL, API_HEADERS } from '../constants';

interface OrderContextType {
  orders: Order[];
  isLoading: boolean;
  addOrder: (order: Omit<Order, 'id' | 'date' | 'status' | 'statusHistory' | 'payment_status'>) => Promise<string>;
  updateOrderStatus: (orderId: string, status: OrderStatus, details?: { courierName?: string; trackingId?: string }) => Promise<void>;
  updateOrderPaymentDetails: (orderId: string, paymentId: string) => Promise<void>;
  updateOrderLabelInfo: (orderId: string, labelUrl: string) => Promise<string>;
  updateOrderByToken: (token: string, status: OrderStatus, note?: string) => Promise<{ success: boolean; message: string }>;
  getOrderById: (orderId: string) => Order | undefined;
  getOrderByToken: (token: string) => Order | undefined;
  refreshOrders: () => Promise<void>;
}

const OrderContext = createContext<OrderContextType | undefined>(undefined);

export const OrderProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const { notifyOrderUpdate } = useNotifications();
  const { users } = useAuth();
  const [orders, setOrders] = useState<Order[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const refreshOrders = async () => {
    try {
      // Use created_at for ordering to align with Supabase default schema
      const response = await fetch(`${BASE_API_URL}/orders?select=*&order=created_at.desc`, { headers: API_HEADERS });
      const data = await response.json();

      if (!response.ok) {
        console.error(`Supabase API Error (Orders): ${response.status}`, data?.message);
        setOrders([]);
        return;
      }

      if (Array.isArray(data)) {
        // Map created_at to date for frontend compatibility
        const mappedData = data.map((o: any) => ({
            ...o,
            date: o.created_at || o.date || new Date().toISOString()
        }));
        setOrders(mappedData);
      } else {
        setOrders([]);
      }
    } catch (e) {
      console.error("Network error during orders sync:", e);
      setOrders([]);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    refreshOrders();
  }, []);

  const addOrder = async (orderData: any): Promise<string> => {
    const orderId = Math.random().toString(36).substr(2, 9).toUpperCase();
    const timestamp = new Date().toISOString();

    // Logic for initial payment status
    const paymentStatus: PaymentStatus = orderData.payment_method === 'Cash on Delivery' ? 'cod_pending' : 'paid';

    // Align with Supabase column naming convention (created_at instead of date)
    const newOrder = {
      ...orderData,
      id: orderId,
      created_at: timestamp, 
      status: 'Placed',
      payment_status: paymentStatus,
      statusHistory: [{ status: 'Placed', timestamp }]
    };

    const response = await fetch(`${BASE_API_URL}/orders`, {
      method: 'POST',
      headers: API_HEADERS,
      body: JSON.stringify(newOrder)
    });

    if (!response.ok) {
      const errData = await response.json();
      throw new Error(errData.message || 'Fulfillment service unavailable');
    }

    await refreshOrders();
    const orderUser = users.find(u => u.email === orderData.userEmail);
    if (orderUser) notifyOrderUpdate({ ...newOrder, date: timestamp } as any, orderUser);

    return orderId;
  };

  const updateOrderStatus = async (orderId: string, status: OrderStatus, details: any = {}) => {
    const order = orders.find(o => o.id === orderId);
    if (!order || order.status === status) return;

    const updatedHistory = [...order.statusHistory, { status, timestamp: new Date().toISOString() }];

    const updateBody: any = { 
      status, 
      statusHistory: updatedHistory,
      courierName: details.courierName || order.courierName,
      trackingId: details.trackingId || order.trackingId,
      updated_at: new Date().toISOString()
    };

    // If marked delivered, payment is definitely received
    if (status === 'Delivered') {
      updateBody.payment_status = 'paid';
    }

    const response = await fetch(`${BASE_API_URL}/orders?id=eq.${encodeURIComponent(orderId)}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify(updateBody)
    });

    if (!response.ok) {
      console.error("Failed to update order status:", await response.json());
      return;
    }

    await refreshOrders();
    const updatedOrder = { ...order, ...updateBody };
    const orderUser = users.find(u => u.email === order.userEmail);
    if (orderUser) notifyOrderUpdate(updatedOrder as any, orderUser);
  };

  const updateOrderPaymentDetails = async (orderId: string, paymentId: string) => {
    await fetch(`${BASE_API_URL}/orders?id=eq.${encodeURIComponent(orderId)}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify({ 
          paymentId, 
          payment_status: 'paid', 
          status: 'Confirmed',
          updated_at: new Date().toISOString()
      })
    });
    await refreshOrders();
  };

  const updateOrderLabelInfo = async (orderId: string, labelUrl: string) => {
    const token = Math.random().toString(36).substring(2, 15);
    const expiry = new Date();
    expiry.setDate(expiry.getDate() + 7);

    await fetch(`${BASE_API_URL}/orders?id=eq.${encodeURIComponent(orderId)}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify({ 
        shippingLabelUrl: labelUrl, 
        labelGeneratedAt: new Date().toISOString(),
        qrToken: token,
        qrExpiresAt: expiry.toISOString(),
        updated_at: new Date().toISOString()
      })
    });
    await refreshOrders();
    return token;
  };

  const updateOrderByToken = async (token: string, status: OrderStatus, note?: string) => {
    const order = orders.find(o => o.qrToken === token);
    if (!order) return { success: false, message: 'Invalid token' };

    const newLog = { id: Date.now().toString(), orderId: order.id, statusSet: status, note, scannedAt: new Date().toISOString() };
    const updatedHistory = [...order.statusHistory, { status, timestamp: new Date().toISOString() }];

    const patchBody: any = { 
        status, 
        statusHistory: updatedHistory,
        qrUsedAt: new Date().toISOString(),
        scanLogs: [...(order.scanLogs || []), newLog],
        updated_at: new Date().toISOString()
    };

    if (status === 'Delivered') {
        patchBody.payment_status = 'paid';
    }

    await fetch(`${BASE_API_URL}/orders?id=eq.${encodeURIComponent(order.id)}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify(patchBody)
    });

    await refreshOrders();
    return { success: true, message: `Order marked as ${status} and payment status updated.` };
  };

  const getOrderById = (id: string) => orders.find(o => o.id === id);
  const getOrderByToken = (token: string) => orders.find(o => o.qrToken === token);

  return (
    <OrderContext.Provider value={{ 
      orders: Array.isArray(orders) ? orders : [], 
      isLoading, addOrder, updateOrderStatus, updateOrderPaymentDetails, 
      updateOrderLabelInfo, updateOrderByToken, getOrderById, getOrderByToken, refreshOrders 
    }}>
      {children}
    </OrderContext.Provider>
  );
};

export const useOrders = () => {
  const context = useContext(OrderContext);
  if (!context) throw new Error('useOrders must be used within an OrderProvider');
  return context;
};

import React, { createContext, useState, useEffect, ReactNode, useContext } from 'react';
import { Product, Review, Category } from '../types';
import { BASE_API_URL, API_HEADERS } from '../constants';

interface ProductContextType {
  products: Product[];
  isLoading: boolean;
  getProduct: (id: number) => Product | undefined;
  addProduct: (product: any) => Promise<void>;
  updateProduct: (product: Product) => Promise<void>;
  deleteProduct: (productId: number) => Promise<void>;
  toggleProductStatus: (productId: number) => Promise<void>;
  approveProduct: (productId: number, approvedBy?: string) => Promise<void>;
  rejectProduct: (productId: number, reason: string) => Promise<void>;
  disableProduct: (productId: number) => Promise<void>;
  addReview: (productId: number, reviewData: Omit<Review, 'id' | 'date'>) => Promise<void>;
  refreshProducts: () => Promise<void>;
}

export const ProductContext = createContext<ProductContextType | undefined>(undefined);

export const ProductProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [products, setProducts] = useState<Product[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [categories, setCategories] = useState<Category[]>([]);

  const fetchCategories = async () => {
    try {
      const res = await fetch(`${BASE_API_URL}/categories?select=*`, { headers: API_HEADERS });
      const data = await res.json();
      if (Array.isArray(data)) setCategories(data);
    } catch (e) {
      console.error("Failed to fetch categories:", e);
    }
  };

  const refreshProducts = async () => {
    try {
      const response = await fetch(`${BASE_API_URL}/products?select=*`, { 
        headers: { ...API_HEADERS, 'Cache-Control': 'no-cache' } 
      });
      const data = await response.json();

      if (Array.isArray(data)) {
        const mappedProducts: Product[] = data.map((item: any) => {
          const cat = categories.find(c => c.id === item.category_id);
          // Standardizing Database response to Frontend Product model
          return {
            id: item.id,
            name: item.name || 'Untitled Product',
            description: item.description || '',
            price: Number(item.price) || 0,
            originalPrice: Number(item.original_price || item.price || 0),
            stock: Number(item.stock) || 0,
            images: Array.isArray(item.images) ? item.images : (item.image ? [item.image] : []),
            category: cat ? cat.name : (item.category || 'General'),
            // Ensure vendorId is a string for consistent filtering
            vendorId: item.vendor_id ? item.vendor_id.toString() : 'internal',
            status: item.status || 'approved',
            rating: Number(item.rating) || 0,
            reviewCount: Number(item.review_count) || 0,
            reviews: item.reviews || [],
            highlights: item.highlights || [],
            specifications: item.specifications || {},
            sellerInfo: item.seller_info || 'VexoKart Partner',
            returnPolicy: item.return_policy || 'Standard Returns',
            warranty: item.warranty || 'No Warranty',
            videoUrl: item.video_url || '',
            approved_at: item.approved_at,
            approved_by: item.approved_by,
            rejectionReason: item.rejection_reason
          };
        });
        setProducts(mappedProducts);
      }
    } catch (error) {
      console.error("Error refreshing products:", error);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    const init = async () => {
        await fetchCategories();
        await refreshProducts();
    };
    init();
  }, []);

  const getProduct = (id: number) => products.find(p => p.id === id);

  const addProduct = async (productData: any) => {
    const matchedCategory = categories.find(c => c.name === productData.category);
    const categoryId = matchedCategory ? matchedCategory.id : null;

    /**
     * FIXED PAYLOAD:
     * Explicitly including vendor_id to associate product with its owner.
     */
    const supabasePayload: any = {
      name: productData.name,
      description: productData.description,
      price: productData.price,
      stock: productData.stock || 0,
      image: productData.images?.[0] || '',
      status: 'pending', // Vendor products always start as pending
      vendor_id: productData.vendor_id, // CRITICAL FIX: Include the vendor reference
      created_at: new Date().toISOString()
    };

    if (categoryId) supabasePayload.category_id = categoryId;

    const response = await fetch(`${BASE_API_URL}/products`, {
      method: 'POST',
      headers: API_HEADERS,
      body: JSON.stringify(supabasePayload)
    });

    if (!response.ok) {
        const err = await response.json();
        throw new Error(`Database Error: ${JSON.stringify(err)}`);
    }

    await refreshProducts();
  };

  const updateProduct = async (product: Product) => {
    const matchedCategory = categories.find(c => c.name === product.category);
    const categoryId = matchedCategory ? matchedCategory.id : null;

    const supabaseUpdate: any = {
      name: product.name,
      description: product.description,
      price: product.price,
      stock: product.stock,
      status: product.status,
      image: product.images?.[0] || ''
    };

    if (categoryId) supabaseUpdate.category_id = categoryId;

    const response = await fetch(`${BASE_API_URL}/products?id=eq.${product.id}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify(supabaseUpdate)
    });

    if (!response.ok) {
        const err = await response.json();
        throw new Error(`Update Failed: ${JSON.stringify(err)}`);
    }

    await refreshProducts();
  };

  const deleteProduct = async (productId: number) => {
    await fetch(`${BASE_API_URL}/products?id=eq.${productId}`, {
      method: 'DELETE',
      headers: API_HEADERS
    });
    await refreshProducts();
  };

  const toggleProductStatus = async (productId: number) => {
    const p = getProduct(productId);
    if (!p) return;
    const newStatus = p.status === 'approved' ? 'disabled' : 'approved';
    await fetch(`${BASE_API_URL}/products?id=eq.${productId}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify({ status: newStatus })
    });
    await refreshProducts();
  };

  const approveProduct = async (productId: number, approvedBy?: string) => {
    await fetch(`${BASE_API_URL}/products?id=eq.${productId}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify({ 
        status: 'approved', 
        approved_by: approvedBy, 
        approved_at: new Date().toISOString() 
      })
    });
    await refreshProducts();
  };

  const rejectProduct = async (productId: number, reason: string) => {
    await fetch(`${BASE_API_URL}/products?id=eq.${productId}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify({ status: 'rejected', rejection_reason: reason })
    });
    await refreshProducts();
  };

  const disableProduct = async (productId: number) => {
    await fetch(`${BASE_API_URL}/products?id=eq.${productId}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify({ status: 'disabled' })
    });
    await refreshProducts();
  };

  const addReview = async (productId: number, reviewData: any) => {
    const p = getProduct(productId);
    if (!p) return;
    const newReview = { ...reviewData, id: Math.random().toString(36).substr(2, 9), date: new Date().toISOString() };
    const updatedReviews = [newReview, ...(p.reviews || [])];
    const newCount = updatedReviews.length;
    const newRating = Number(((p.rating * (p.reviewCount || 0) + reviewData.rating) / newCount).toFixed(1));

    try {
        await fetch(`${BASE_API_URL}/products?id=eq.${productId}`, {
          method: 'PATCH',
          headers: API_HEADERS,
          body: JSON.stringify({ 
              reviews: updatedReviews, 
              review_count: newCount, 
              rating: newRating 
          })
        });
        await refreshProducts();
    } catch (e) {
        console.warn("Product schema does not support remote reviews storage.");
    }
  };

  return (
    <ProductContext.Provider value={{ 
      products, isLoading, getProduct, addProduct, updateProduct, 
      deleteProduct, toggleProductStatus, approveProduct, rejectProduct, 
      disableProduct, addReview, refreshProducts 
    }}>
      {children}
    </ProductContext.Provider>
  );
};

