  getOrderByToken: (token: string) => Order | undefined;
  refreshOrders: () => Promise<void>;
}

const OrderContext = createContext<OrderContextType | undefined>(undefined);

// Explicitly defining fields to avoid PostgREST trying to fetch stale/missing columns like 'email' or 'history'
const ORDER_FIELDS = 'id,created_at,status,total_amount,address,user_id,items,payment_method,payment_status,courier_name,tracking_id,shipping_label_url,label_generated_at,qr_token,qr_expires_at,qr_used_at,scan_logs';

