    try {
      const response = await fetch(`${BASE_API_URL}/orders?select=${ORDER_FIELDS}&order=created_at.desc`, { headers: API_HEADERS });
      const data = await response.json();

      if (!response.ok) {
        console.error(`Supabase API Error (Orders): ${response.status}`, data?.message);
        // If the explicit select fails, fallback to basic fields to maintain app stability
        if (response.status === 400) {
            console.warn("Retrying with minimal column set due to field mismatch...");
            const fallbackRes = await fetch(`${BASE_API_URL}/orders?select=id,status,created_at&order=created_at.desc`, { headers: API_HEADERS });
            const fallbackData = await fallbackRes.json();
            if (fallbackRes.ok) {
                setOrders(fallbackData.map((o: any) => ({ 
                    ...o, 
                    date: o.created_at, 
                    items: [], 
                    total: 0, 
                    userEmail: '', 
                    shippingAddress: {} as any, 
                    statusHistory: [{ status: o.status, timestamp: o.created_at }] 
                })));
                return;
            }
        }
        setOrders([]);
        return;
      }

      if (Array.isArray(data)) {
        const mappedData = data.map((o: any) => ({
            ...o,
            date: o.created_at || o.date || new Date().toISOString(),
            total: Number(o.total_amount || o.amount || o.total || 0),
            userEmail: o.user_id || o.email || o.user_email || o.userEmail,
            shippingAddress: o.address || o.shipping_address || o.delivery_address || o.shippingAddress,
            // Synthesize history since dedicated history column is failing in schema cache
            statusHistory: o.history || o.status_history || [{ status: o.status || 'Placed', timestamp: o.created_at || new Date().toISOString() }],
            courierName: o.courier_name || o.courierName,
            trackingId: o.tracking_id || o.trackingId,
