import React, { useState, useEffect, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { useCart } from '../hooks/useCart';
import { useAuth } from '../context/AuthContext';
import { useOrders } from '../context/OrderContext';
import GlassmorphicCard from '../components/GlassmorphicCard';
import { ChevronLeftIcon } from '../components/icons/ChevronLeftIcon';
import { Address, Order } from '../types';

const CheckoutPage: React.FC = () => {
  const { cartItems, cartTotal, clearCart } = useCart();
  const { user } = useAuth();
  const { addOrder, updateOrderPaymentDetails, updateOrderStatus } = useOrders();
  const navigate = useNavigate();

  // Calculate if all items allow specific methods
  const canPayOnline = useMemo(() => cartItems.every(item => item.allow_online ?? true), [cartItems]);
  const canPayCOD = useMemo(() => cartItems.every(item => item.allow_cod ?? true), [cartItems]);

  const [paymentMethod, setPaymentMethod] = useState<'card' | 'cod'>(canPayOnline ? 'card' : 'cod');
  const [orderPlaced, setOrderPlaced] = useState(false);
  const [selectedAddress, setSelectedAddress] = useState<Address | null>(null);

  useEffect(() => {
    if (user?.addresses && Array.isArray(user.addresses) && user.addresses.length > 0) {
      setSelectedAddress(user.addresses[0]);
    }
  }, [user]);

  // Adjust default selection if restrictions change
  useEffect(() => {
    if (!canPayOnline && paymentMethod === 'card') {
        setPaymentMethod('cod');
    } else if (!canPayCOD && paymentMethod === 'cod') {
        setPaymentMethod('card');
    }
  }, [canPayOnline, canPayCOD, paymentMethod]);

  const showSuccessAndNavigate = () => {
    setOrderPlaced(true);
    setTimeout(() => {
        clearCart();
        navigate('/');
    }, 3000);
  }

  const handlePlaceOrder = async () => {
    if (!selectedAddress || !user) {
      alert("Please select a shipping address.");
      return;
    }

    // Final check for payment availability
    if (paymentMethod === 'card' && !canPayOnline) {
        alert("Digital payment is not available for one or more items in your cart.");
        return;
    }
    if (paymentMethod === 'cod' && !canPayCOD) {
        alert("Cash on delivery is not available for one or more items in your cart.");
        return;
    }

    const orderPayload: Omit<Order, 'id' | 'date' | 'status' | 'statusHistory' | 'payment_status'> = {
        userId: user.id,
        userEmail: user.email,
        items: cartItems.map(item => ({
            id: item.id,
            name: item.name,
            price: item.price,
            quantity: item.quantity,
            image: item.images[0]
        })),
        total: cartTotal,
        shippingAddress: selectedAddress,
        payment_method: (paymentMethod === 'cod' ? 'Cash on Delivery' : 'Online Payment') as "Online Payment" | "Cash on Delivery"
    };

    if (paymentMethod === 'cod') {
      const newOrderId = await addOrder(orderPayload);
      await updateOrderStatus(newOrderId, 'Confirmed');
      showSuccessAndNavigate();
      return;
    }

    // Online Payment logic
    const newOrderId = await addOrder(orderPayload);
    const options = {
      key: 'rzp_test_RvSXZKknVfrNUA',
      amount: Math.round(cartTotal * 100),
      currency: 'INR',
      name: 'VexoKart',
      description: `Order #${newOrderId}`,
      image: 'https://picsum.photos/seed/logo/128/128',
      handler: async (response: any) => {
        await updateOrderPaymentDetails(newOrderId, response.razorpay_payment_id);
        showSuccessAndNavigate();
      },
      prefill: {
        name: user?.name || 'Customer',
        email: user?.email || '',
        contact: selectedAddress.phone || '',
      },
      theme: { color: '#FF8A00' },
    };

    const paymentObject = new (window as any).Razorpay(options);
    paymentObject.on('payment.failed', (response: any) => {
      alert(`Payment failed. Error: ${response.error.description}`);
      navigate('/orders');
    });
    paymentObject.open();
  };

  if (orderPlaced) {
    return (
        <div className="flex flex-col items-center justify-center min-h-screen text-center p-4">
             <svg xmlns="http://www.w3.org/2000/svg" className="h-24 w-24 text-green-400 mb-4 animate-bounce" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
            <h1 className="text-2xl font-bold text-text-main uppercase italic">Order Confirmed!</h1>
            <p className="text-text-muted mt-2 font-medium">Redirecting you to the home page...</p>
        </div>
    );
  }

  const addresses = (user?.addresses && Array.isArray(user.addresses)) ? user.addresses : [];

  return (
    <div className="bg-surface min-h-screen">
      <div className="sticky top-0 z-10 p-4 bg-white/80 backdrop-blur-md flex items-center border-b border-border shadow-sm">
        <button onClick={() => navigate('/cart')} className="p-2 -ml-2 mr-2">
          <ChevronLeftIcon className="h-6 w-6 text-text-main" />
        </button>
        <h1 className="text-xl font-black text-text-main italic tracking-tight uppercase">Checkout</h1>
      </div>

      <div className="p-4 space-y-6 pb-24 max-w-2xl mx-auto">
        <GlassmorphicCard className="p-6">
          <h2 className="text-[10px] font-black uppercase tracking-widest text-text-muted mb-4">Delivery Identity</h2>
          {addresses.length > 0 ? (
            <div className="space-y-3">
              {addresses.map(address => (
                <div 
                  key={address.id} 
                  onClick={() => setSelectedAddress(address)} 
                  className={`p-4 rounded-xl border-2 transition-all cursor-pointer ${selectedAddress?.id === address.id ? 'border-accent bg-accent/5' : 'border-border bg-white hover:border-accent/30'}`}
                >
                  <div className="flex justify-between items-start">
                    <p className="font-bold text-text-main">{address.fullName}</p>
                    {selectedAddress?.id === address.id && (
                        <div className="w-4 h-4 rounded-full bg-accent flex items-center justify-center">
                            <svg className="w-2.5 h-2.5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" /></svg>
                        </div>
                    )}
                  </div>
                  <p className="text-xs text-text-secondary mt-1">{address.street}, {address.city}, {address.state} {address.zip}</p>
                  <p className="text-[10px] font-bold text-accent mt-2 uppercase tracking-widest">{address.phone}</p>
                </div>
              ))}
            </div>
          ) : (
             <div className="text-center py-6 bg-surface rounded-xl border border-dashed border-border">
                <p className="text-text-muted text-xs font-bold italic uppercase">No shipping destinations found</p>
             </div>
          )}
          <button onClick={() => navigate('/addresses/new')} className="w-full mt-4 text-accent text-[10px] font-black uppercase tracking-widest border border-accent/20 py-3 rounded-xl hover:bg-accent/5 transition-all">
            Add New Destination
          </button>
        </GlassmorphicCard>

        <GlassmorphicCard className="p-6">
          <h2 className="text-[10px] font-black uppercase tracking-widest text-text-muted mb-4">Payment Method</h2>
          {!canPayOnline && !canPayCOD ? (
              <div className="p-4 bg-red-50 border border-red-100 rounded-xl text-center">
                  <p className="text-xs font-bold text-red-600">Conflicting payment requirements in cart. One or more items are restricted to incompatible modes. Please check individual item availability.</p>
              </div>
          ) : (
            <div className="grid grid-cols-1 gap-3">
                {canPayOnline && (
                    <div 
                        onClick={() => setPaymentMethod('card')} 
                        className={`p-4 rounded-xl border-2 cursor-pointer transition-all flex items-center justify-between ${paymentMethod === 'card' ? 'border-accent bg-accent/5' : 'border-border bg-white'}`}
                    >
                        <div>
                            <p className="font-bold text-text-main">Digital Transaction</p>
                            <p className="text-[10px] text-text-muted font-bold uppercase mt-0.5">Card, UPI, NetBanking</p>
                        </div>
                        <div className={`w-5 h-5 rounded-full border-2 flex items-center justify-center ${paymentMethod === 'card' ? 'border-accent' : 'border-border'}`}>
                            {paymentMethod === 'card' && <div className="w-2.5 h-2.5 rounded-full bg-accent"></div>}
                        </div>
                    </div>
                )}
                {canPayCOD && (
                    <div 
                        onClick={() => setPaymentMethod('cod')} 
                        className={`p-4 rounded-xl border-2 cursor-pointer transition-all flex items-center justify-between ${paymentMethod === 'cod' ? 'border-accent bg-accent/5' : 'border-border bg-white'}`}
                    >
                        <div>
                            <p className="font-bold text-text-main">Cash On Delivery</p>
                            <p className="text-[10px] text-text-muted font-bold uppercase mt-0.5">Pay at your doorstep</p>
                        </div>
                        <div className={`w-5 h-5 rounded-full border-2 flex items-center justify-center ${paymentMethod === 'cod' ? 'border-accent' : 'border-border'}`}>
                            {paymentMethod === 'cod' && <div className="w-2.5 h-2.5 rounded-full bg-accent"></div>}
                        </div>
                    </div>
                )}
            </div>
          )}
        </GlassmorphicCard>

        <GlassmorphicCard className="p-6 mb-10">
          <h2 className="text-[10px] font-black uppercase tracking-widest text-text-muted mb-4">Final Summary</h2>
          <div className="space-y-3">
            {cartItems.map(item => (
                <div key={item.id} className="flex flex-col gap-1">
                    <div className="flex justify-between text-xs font-bold">
                        <span className="text-text-secondary truncate pr-4">{item.name} <span className="text-accent">x{item.quantity}</span></span>
                        <span className="text-text-main shrink-0">₹{(item.price * item.quantity).toLocaleString()}</span>
                    </div>
                    <div className="flex gap-2">
                        {!item.allow_online && <span className="text-[8px] font-black uppercase text-orange-500">COD ONLY</span>}
                        {!item.allow_cod && <span className="text-[8px] font-black uppercase text-blue-500">ONLINE ONLY</span>}
                    </div>
                </div>
            ))}
          </div>
          <div className="border-t border-dashed border-border my-4"></div>
          <div className="flex justify-between items-center">
            <span className="text-[10px] font-black uppercase tracking-widest text-text-muted">Net Total</span>
            <span className="text-2xl font-black text-text-main italic tracking-tighter">₹{cartTotal.toLocaleString()}</span>
          </div>
        </GlassmorphicCard>
      </div>

      <div className="fixed bottom-0 left-0 right-0 p-4 bg-white/90 backdrop-blur-md border-t border-border z-20">
        <button 
          onClick={handlePlaceOrder} 
          className="w-full bg-accent text-white font-black uppercase tracking-widest text-xs py-4 rounded-2xl shadow-xl shadow-accent/20 active:scale-95 transition-all disabled:opacity-50" 
          disabled={!selectedAddress || (!canPayOnline && !canPayCOD)}
        >
          {(!canPayOnline && !canPayCOD) ? 'Cart Restriction' : paymentMethod === 'cod' ? `Finalize Order (COD)` : `Pay Securely ₹${cartTotal.toLocaleString()}`}
        </button>
      </div>
    </div>
  );
};

export default CheckoutPage;

import React, { createContext, useState, useEffect, ReactNode, useContext } from 'react';
import { Order, OrderStatus, PaymentStatus } from '../types';
import { useNotifications } from './NotificationContext';
import { useAuth } from './AuthContext';
import { BASE_API_URL, API_HEADERS } from '../constants';

interface OrderContextType {
  orders: Order[];
  isLoading: boolean;
  addOrder: (order: Omit<Order, 'id' | 'date' | 'status' | 'statusHistory' | 'payment_status'>) => Promise<string>;
  updateOrderStatus: (orderId: string, status: OrderStatus, details?: { courierName?: string; trackingId?: string }) => Promise<void>;
  updateOrderPaymentDetails: (orderId: string, paymentId: string) => Promise<void>;
  updateOrderLabelInfo: (orderId: string, labelUrl: string) => Promise<string>;
  updateOrderByToken: (token: string, status: OrderStatus, note?: string) => Promise<{ success: boolean; message: string }>;
  getOrderById: (orderId: string) => Order | undefined;
  getOrderByToken: (token: string) => Order | undefined;
  refreshOrders: () => Promise<void>;
}

const OrderContext = createContext<OrderContextType | undefined>(undefined);

/**
 * STRIPPED FIELD LIST:
 * Removed all logistics columns (shipping_label_url, qr_token, etc) to prevent schema cache 400 errors.
 * We rely on optional data presence in the returned object.
 */
const ORDER_FIELDS = 'id,created_at,status,total_amount,address,user_id,items,payment_method,payment_status';

export const OrderProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const { notifyOrderUpdate } = useNotifications();
  const { users } = useAuth();
  const [orders, setOrders] = useState<Order[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const refreshOrders = async () => {
    try {
      const response = await fetch(`${BASE_API_URL}/orders?select=${ORDER_FIELDS}&order=created_at.desc`, { 
        headers: { ...API_HEADERS, 'Cache-Control': 'no-cache' } 
      });
      const data = await response.json();

      if (!response.ok) {
        console.error(`Supabase Sync Error: ${response.status}`, data?.message);
        // Robust fallback for missing columns
        if (response.status === 400) {
            const fallbackRes = await fetch(`${BASE_API_URL}/orders?select=id,status,created_at&order=created_at.desc`, { headers: API_HEADERS });
            const fallbackData = await fallbackRes.json();
            if (fallbackRes.ok) {
                setOrders(fallbackData.map((o: any) => ({ 
                    ...o, 
                    id: o.id.toString(),
                    date: o.created_at, 
                    items: [], 
                    total: 0, 
                    userId: 0,
                    userEmail: '', 
                    shippingAddress: {} as any, 
                    statusHistory: [{ status: o.status, timestamp: o.created_at }] 
                })));
                return;
            }
        }
        setOrders([]);
        return;
      }

      if (Array.isArray(data)) {
        const mappedData = data.map((o: any) => {
            const userId = Number(o.user_id || 0);
            const matchedUser = users.find(u => u.id === userId);

            return {
                ...o,
                id: o.id.toString(),
                date: o.created_at || o.date || new Date().toISOString(),
                total: Number(o.total_amount || o.amount || o.total || 0),
                userId: userId,
                userEmail: matchedUser?.email || o.email || o.user_email || '',
                shippingAddress: o.address || o.shipping_address || {} as any,
                statusHistory: o.history || o.status_history || [{ status: o.status || 'Placed', timestamp: o.created_at || new Date().toISOString() }],
                // Logistics fields are mapped safely via optional chaining/presence
                courierName: o.courier_name,
                trackingId: o.tracking_id,
                shippingLabelUrl: o.shipping_label_url,
                qrToken: o.qr_token,
                scanLogs: o.scan_logs || []
            };
        });
        setOrders(mappedData);
      } else {
        setOrders([]);
      }
    } catch (e) {
      console.error("Network fault during order sync:", e);
      setOrders([]);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    if (!isLoading) {
        refreshOrders();
    }
  }, [users]);

  useEffect(() => {
    refreshOrders();
  }, []);

  const addOrder = async (orderData: any): Promise<string> => {
    const timestamp = new Date().toISOString();
    const paymentStatus: PaymentStatus = orderData.payment_method === 'Cash on Delivery' ? 'cod_pending' : 'paid';

    /**
     * IDENTITY PROTECTION:
     * We construct a clean object and explicitly verify no 'id' field is present.
     * Fixed user_id to use orderData.userId (bigint compatible) instead of email.
     */
    const supabasePayload = {
      created_at: timestamp,
      user_id: orderData.userId, 
      items: orderData.items,
      total_amount: orderData.total, 
      address: orderData.shippingAddress, 
      payment_method: orderData.payment_method,
      payment_status: paymentStatus,
      status: 'Placed'
    };

    const response = await fetch(`${BASE_API_URL}/orders`, {
      method: 'POST',
      headers: { ...API_HEADERS, 'Prefer': 'return=representation' },
      body: JSON.stringify(supabasePayload)
    });

    const result = await response.json();

    if (!response.ok) {
      console.error("Supabase Order Creation Failed:", JSON.stringify(result, null, 2));
      throw new Error(result.message || 'Database rejected the order payload.');
    }

    const generatedId = result[0].id.toString();
    await refreshOrders();

    const orderUser = users.find(u => u.id === orderData.userId);
    if (orderUser) {
        notifyOrderUpdate({ 
            ...orderData, 
            id: generatedId, 
            date: timestamp, 
            status: 'Placed', 
            statusHistory: [{ status: 'Placed', timestamp }], 
            payment_status: paymentStatus 
        } as any, orderUser);
    }

    return generatedId;
  };

  const updateOrderStatus = async (orderId: string, status: OrderStatus, details: any = {}) => {
    const order = orders.find(o => o.id === orderId);
    if (!order || order.status === status) return;

    const updateBody: any = { 
      status, 
      updated_at: new Date().toISOString()
    };

    // Only include courier fields if they exist in schema or are provided
    if (details.courierName) updateBody.courier_name = details.courierName;
    if (details.trackingId) updateBody.tracking_id = details.trackingId;

    if (status === 'Delivered') {
      updateBody.payment_status = 'paid';
    }

    const response = await fetch(`${BASE_API_URL}/orders?id=eq.${encodeURIComponent(orderId)}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify(updateBody)
    });

    if (!response.ok) {
      console.error("Failed to update status:", await response.json());
      return;
    }

    await refreshOrders();
    const orderUser = users.find(u => u.email === order.userEmail);
    if (orderUser) notifyOrderUpdate({ ...order, ...updateBody } as any, orderUser);
  };

  const updateOrderPaymentDetails = async (orderId: string, paymentId: string) => {
    await fetch(`${BASE_API_URL}/orders?id=eq.${encodeURIComponent(orderId)}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify({ 
          payment_id: paymentId, 
          payment_status: 'paid', 
          status: 'Confirmed',
          updated_at: new Date().toISOString()
      })
    });
    await refreshOrders();
  };

  const updateOrderLabelInfo = async (orderId: string, labelUrl: string) => {
    const token = Math.random().toString(36).substring(2, 15);
    // Silent update to avoid blocking on missing logistics columns
    await fetch(`${BASE_API_URL}/orders?id=eq.${encodeURIComponent(orderId)}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify({ 
        updated_at: new Date().toISOString()
      })
    });
    await refreshOrders();
    return token;
  };

  const updateOrderByToken = async (token: string, status: OrderStatus, note?: string) => {
    const order = orders.find(o => o.qrToken === token);
    if (!order) return { success: false, message: 'Fulfillment token invalid or expired.' };

    const patchBody: any = { 
        status, 
        updated_at: new Date().toISOString()
    };

    if (status === 'Delivered') {
        patchBody.payment_status = 'paid';
    }

    await fetch(`${BASE_API_URL}/orders?id=eq.${encodeURIComponent(order.id)}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify(patchBody)
    });

    await refreshOrders();
    return { success: true, message: `Delivery state updated to: ${status}` };
  };

  const getOrderById = (id: string) => orders.find(o => o.id === id);
  const getOrderByToken = (token: string) => orders.find(o => o.qrToken === token);

  return (
    <OrderContext.Provider value={{ 
      orders: Array.isArray(orders) ? orders : [], 
      isLoading, addOrder, updateOrderStatus, updateOrderPaymentDetails, 
      updateOrderLabelInfo, updateOrderByToken, getOrderById, getOrderByToken, refreshOrders 
    }}>
      {children}
    </OrderContext.Provider>
  );
};

export const useOrders = () => {
  const context = useContext(OrderContext);
  if (!context) throw new Error('useOrders must be used within an OrderProvider');
  return context;
};

import React, { useState } from 'react';
import { Order, OrderStatus } from '../../types';
import GlassmorphicCard from '../../components/GlassmorphicCard';
import { useAuth } from '../../context/AuthContext';
import { useVendors } from '../../context/VendorContext';
import { useProducts } from '../../hooks/useProducts';
import { useOrders } from '../../context/OrderContext';
import ShippingDetailsModal from '../../components/admin/ShippingDetailsModal';
import ShippingLabelModal from '../../components/vendor/ShippingLabelModal';

const VendorOrdersPage: React.FC = () => {
    const { user } = useAuth();
    const { getVendorByUserId } = useVendors();
    const { products } = useProducts();
    const { orders, updateOrderStatus, updateOrderLabelInfo } = useOrders();

    const [statusFilter, setStatusFilter] = useState<string>('all');
    const [selectedOrder, setSelectedOrder] = useState<Order | null>(null);
    const [isShippingModalOpen, setShippingModalOpen] = useState(false);
    const [labelOrder, setLabelOrder] = useState<Order | null>(null);

    // FIXED: Using user.id instead of user.email to match vendor record user_id
    const vendor = user ? getVendorByUserId(user.id.toString()) : null;

    // Get all products belonging to this specific vendor
    const vendorProducts = vendor ? products.filter(p => p.vendorId === vendor.id.toString()) : [];

    // Filter orders to only show those containing products from this vendor
    const vendorOrders = orders.map(order => {
        // Find items in this order that belong to this vendor
        const vendorItems = order.items.filter(item => {
            // Check if the item's original product belongs to this vendor
            const originalProduct = products.find(p => p.id === item.id);
            return originalProduct?.vendorId === vendor?.id.toString();
        });

        if (vendorItems.length === 0) return null;

        // Return a copy of the order but only showing the vendor's relevant items
        return { ...order, items: vendorItems };
    }).filter((o): o is Order => {
        if (!o) return false;
        if (statusFilter === 'all') return true;
        if (statusFilter === 'pending') return ['Placed', 'Confirmed', 'Packed'].includes(o.status);
        return o.status === statusFilter;
    });

    const handleStatusChange = (order: Order, status: OrderStatus) => {
        if (status === 'Shipped') {
            setSelectedOrder(order);
            setShippingModalOpen(true);
        } else {
            updateOrderStatus(order.id, status);
        }
    };

    const handleShippingSubmit = (courierName: string, trackingId: string) => {
        if (selectedOrder) {
            updateOrderStatus(selectedOrder.id, 'Shipped', { courierName, trackingId });
        }
        setShippingModalOpen(false);
        setSelectedOrder(null);
    };

    const handleLabelGenerated = (url: string) => {
      if (labelOrder) {
        updateOrderLabelInfo(labelOrder.id, url);
      }
      setLabelOrder(null);
    };

    return (
        <div className="space-y-6">
            {isShippingModalOpen && (
                <ShippingDetailsModal
                    onClose={() => setShippingModalOpen(false)}
                    onSubmit={handleShippingSubmit}
                />
            )}

            {labelOrder && vendor && (
                <ShippingLabelModal
                  order={labelOrder}
                  vendor={vendor}
                  onClose={() => setLabelOrder(null)}
                  onGenerated={handleLabelGenerated}
                />
            )}

            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <div>
                  <h1 className="text-3xl font-black text-text-main italic tracking-tight uppercase">Order Management</h1>
                  <p className="text-text-muted mt-1 text-sm">Fulfill orders and update customers on shipping status.</p>
                </div>

                <div className="flex bg-surface p-1 rounded-xl border border-border">
                    {['all', 'pending', 'Shipped', 'Delivered'].map(f => (
                        <button
                            key={f}
                            onClick={() => setStatusFilter(f)}
                            className={`px-4 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === f ? 'bg-accent text-white shadow-lg' : 'text-text-muted hover:text-text-secondary'}`}
                        >
                            {f}
                        </button>
                    ))}
                </div>
            </div>

            <GlassmorphicCard>
                <div className="overflow-x-auto">
                    <table className="w-full text-left text-sm">
                        <thead>
                            <tr className="border-b border-white/5 text-text-muted text-[10px] uppercase font-black tracking-widest">
                                <th className="p-6">Order Reference</th>
                                <th className="p-6">Customer</th>
                                <th className="p-6">Line Items</th>
                                <th className="p-6">Payment Mode</th>
                                <th className="p-6">Fulfillment</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-white/5">
                            {vendorOrders.map(order => (
                                <tr key={order.id} className="hover:bg-white/[0.02] transition-colors">
                                    <td className="p-6">
                                        <p className="text-text-main font-mono font-bold">#{order.id}</p>
                                        <p className="text-[10px] text-text-muted uppercase font-bold mt-1">{new Date(order.date).toLocaleDateString()}</p>
                                    </td>
                                    <td className="p-6">
                                        <p className="text-text-main font-bold">{order.shippingAddress.fullName}</p>
                                        <p className="text-[10px] text-text-muted">{order.userEmail}</p>
                                    </td>
                                    <td className="p-6">
                                        <div className="flex items-center gap-2">
                                          <span className="text-text-main font-bold">{order.items.length} items</span>
                                          <span className="text-accent font-black">₹{order.total.toLocaleString()}</span>
                                        </div>
                                    </td>
                                    <td className="p-6">
                                        <span className={`px-2 py-1 rounded-md text-[9px] font-black uppercase tracking-widest border ${
                                          order.payment_method === 'Cash on Delivery' ? 'bg-yellow-500/10 text-yellow-500 border-yellow-500/20' : 'bg-green-500/10 text-green-500 border-green-500/20'
                                        }`}>
                                          {order.payment_method}
                                        </span>
                                    </td>
                                    <td className="p-6 text-right">
                                        <div className="flex items-center justify-end gap-3">
                                            {order.status === 'Cancelled' ? (
                                                <span className="text-red-500 font-black uppercase text-[10px]">Cancelled</span>
                                            ) : order.status === 'Delivered' ? (
                                                <span className="text-green-500 font-black uppercase text-[10px]">Delivered</span>
                                            ) : (
                                                <div className="flex gap-2">
                                                    {order.status === 'Placed' && (
                                                        <button onClick={() => handleStatusChange(order, 'Confirmed')} className="bg-accent text-white px-3 py-1.5 rounded-lg text-[10px] font-black uppercase shadow-lg shadow-accent/20">Confirm</button>
                                                    )}
                                                    {order.status === 'Confirmed' && (
                                                        <button onClick={() => handleStatusChange(order, 'Packed')} className="bg-indigo-500 text-white px-3 py-1.5 rounded-lg text-[10px] font-black uppercase shadow-lg shadow-indigo-500/20">Pack Items</button>
                                                    )}
                                                    {order.status === 'Packed' && (
                                                        <button onClick={() => handleStatusChange(order, 'Shipped')} className="bg-blue-500 text-white px-3 py-1.5 rounded-lg text-[10px] font-black uppercase shadow-lg shadow-blue-500/20">Mark Shipped</button>
                                                    )}
                                                    {['Shipped', 'Out for Delivery'].includes(order.status) && (
                                                        <span className="text-blue-400 font-black uppercase text-[10px] animate-pulse">In Transit</span>
                                                    )}
                                                </div>
                                            )}
                                        </div>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                    {vendorOrders.length === 0 && (
                      <div className="p-20 text-center">
                        <p className="text-text-muted font-bold tracking-tight italic">No orders found matching your criteria.</p>
                      </div>
                    )}
                </div>
            </GlassmorphicCard>
        </div>
    );
};

