import React, { createContext, useState, useEffect, ReactNode, useContext } from 'react';
import { Order, OrderStatus, PaymentStatus } from '../types';
import { useNotifications } from './NotificationContext';
import { useAuth } from './AuthContext';
import { BASE_API_URL, API_HEADERS } from '../constants';

interface OrderContextType {
  orders: Order[];
  isLoading: boolean;
  addOrder: (order: Omit<Order, 'id' | 'date' | 'status' | 'statusHistory' | 'payment_status'>) => Promise<string>;
  updateOrderStatus: (orderId: string, status: OrderStatus, details?: { courierName?: string; trackingId?: string; label_url?: string }) => Promise<void>;
  updateOrderPaymentDetails: (orderId: string, paymentId: string) => Promise<void>;
  updateOrderLabelInfo: (orderId: string, labelUrl: string) => Promise<string>;
  updateOrderByToken: (token: string, status: OrderStatus, note?: string) => Promise<{ success: boolean; message: string }>;
  getOrderById: (orderId: string) => Order | undefined;
  getOrderByToken: (token: string) => Order | undefined;
  refreshOrders: () => Promise<void>;
}

const OrderContext = createContext<OrderContextType | undefined>(undefined);

const ORDER_FIELDS = 'id,created_at,status,total_amount,address,user_id,items,payment_method,payment_status,courier_name,tracking_id,label_url,history';

export const OrderProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const { notifyOrderUpdate } = useNotifications();
  const { user, users } = useAuth();
  const [orders, setOrders] = useState<Order[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const refreshOrders = async () => {
    try {
      // Role-based visibility logic
      let url = `${BASE_API_URL}/orders?select=${ORDER_FIELDS}&order=created_at.desc`;

      // Part 1.1: Standard users only fetch their own orders
      if (user && user.role === 'user') {
        url += `&user_id=eq.${user.id}`;
      }

      const response = await fetch(url, { 
        headers: { ...API_HEADERS, 'Cache-Control': 'no-cache' } 
      });
      const data = await response.json();

      if (!response.ok) {
        console.error(`Order Fetch Error: ${response.status}`, data?.message);
        setOrders([]);
        return;
      }

      if (Array.isArray(data)) {
        const mappedData = data.map((o: any) => {
            const userId = Number(o.user_id || 0);
            const matchedUser = users.find(u => u.id === userId);

            return {
                ...o,
                id: o.id.toString(),
                date: o.created_at || new Date().toISOString(),
                total: Number(o.total_amount || 0),
                userId: userId,
                userEmail: matchedUser?.email || o.email || '',
                shippingAddress: o.address || {} as any,
                statusHistory: o.history || [{ status: o.status || 'Placed', timestamp: o.created_at }],
                courierName: o.courier_name,
                trackingId: o.tracking_id,
                label_url: o.label_url,
                scanLogs: o.scan_logs || []
            };
        });
        setOrders(mappedData);
      } else {
        setOrders([]);
      }
    } catch (e) {
      console.error("Network fault during order sync:", e);
      setOrders([]);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    if (user) {
        refreshOrders();
    }
  }, [user, users]);

  const addOrder = async (orderData: any): Promise<string> => {
    const timestamp = new Date().toISOString();
    const paymentStatus: PaymentStatus = orderData.payment_method === 'Cash on Delivery' ? 'cod_pending' : 'paid';

    const supabasePayload = {
      created_at: timestamp,
      user_id: orderData.userId, 
      items: orderData.items,
      total_amount: orderData.total, 
      address: orderData.shippingAddress, 
      payment_method: orderData.payment_method,
      payment_status: paymentStatus,
      status: 'Placed',
      history: [{ status: 'Placed', timestamp }]
    };

    const response = await fetch(`${BASE_API_URL}/orders`, {
      method: 'POST',
      headers: { ...API_HEADERS, 'Prefer': 'return=representation' },
      body: JSON.stringify(supabasePayload)
    });

    const result = await response.json();
    if (!response.ok) throw new Error(result.message || 'Order creation failed');

    await refreshOrders();
    return result[0].id.toString();
  };

  const updateOrderStatus = async (orderId: string, status: OrderStatus, details: any = {}) => {
    const order = orders.find(o => o.id === orderId);
    if (!order) return;

    const timestamp = new Date().toISOString();
    const newHistory = [...(order.statusHistory || []), { status, timestamp }];

    const updateBody: any = { 
      status, 
      history: newHistory,
      updated_at: timestamp
    };

    if (details.courierName) updateBody.courier_name = details.courierName;
    if (details.trackingId) updateBody.tracking_id = details.trackingId;
    if (details.label_url) updateBody.label_url = details.label_url;

    const response = await fetch(`${BASE_API_URL}/orders?id=eq.${encodeURIComponent(orderId)}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify(updateBody)
    });

    if (!response.ok) throw new Error('Failed to update order status');

    await refreshOrders();
  };

  const updateOrderPaymentDetails = async (orderId: string, paymentId: string) => {
    await fetch(`${BASE_API_URL}/orders?id=eq.${encodeURIComponent(orderId)}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify({ 
          payment_id: paymentId, 
          payment_status: 'paid', 
          status: 'Confirmed'
      })
    });
    await refreshOrders();
  };

  const updateOrderLabelInfo = async (orderId: string, labelUrl: string) => {
    await updateOrderStatus(orderId, 'Packed', { label_url: labelUrl });
    return 'token_gen';
  };

  const updateOrderByToken = async (token: string, status: OrderStatus, note?: string) => {
    // Basic mock update logic for logistics flow
    return { success: true, message: `Status updated to ${status}` };
  };

  const getOrderById = (id: string) => orders.find(o => o.id === id);
  const getOrderByToken = (token: string) => undefined;

  return (
    <OrderContext.Provider value={{ 
      orders, isLoading, addOrder, updateOrderStatus, updateOrderPaymentDetails, 
      updateOrderLabelInfo, updateOrderByToken, getOrderById, getOrderByToken, refreshOrders 
    }}>
      {children}
    </OrderContext.Provider>
  );
};

export const useOrders = () => {
  const context = useContext(OrderContext);
  if (!context) throw new Error('useOrders must be used within an OrderProvider');
  return context;
};

import React, { useState, useEffect, useMemo } from 'react';
import { Order, OrderStatus, OrderItem } from '../../types';
import GlassmorphicCard from '../../components/GlassmorphicCard';
import { useAuth } from '../../context/AuthContext';
import { useVendors } from '../../context/VendorContext';
import { useOrders } from '../../context/OrderContext';
import ShippingDetailsModal from '../../components/admin/ShippingDetailsModal';
import ShippingLabelModal from '../../components/vendor/ShippingLabelModal';

interface VendorAugmentedOrder extends Order {
    vendorItems: OrderItem[];
    vendorSubtotal: number;
}

const VendorOrdersPage: React.FC = () => {
    const { user } = useAuth();
    const { currentVendor, fetchCurrentVendor } = useVendors();
    const { orders, isLoading, updateOrderStatus, updateOrderLabelInfo, refreshOrders } = useOrders();

    const [statusFilter, setStatusFilter] = useState<string>('all');
    const [selectedOrder, setSelectedOrder] = useState<Order | null>(null);
    const [isShippingModalOpen, setShippingModalOpen] = useState(false);
    const [labelOrder, setLabelOrder] = useState<Order | null>(null);
    const [isGeneratingLabel, setIsGeneratingLabel] = useState<string | null>(null);

    useEffect(() => {
        refreshOrders();
        if (user?.email && !currentVendor) {
            fetchCurrentVendor(user.email);
        }
    }, [user]);

    // Part 1.2: Frontend filtering for vendor specific orders and items
    const vendorOrders = useMemo(() => {
        if (!currentVendor) return [];

        console.log('[VendorOrders] Debug - All Orders:', orders);
        console.log('[VendorOrders] Debug - Current Vendor:', currentVendor);

        const filtered = orders.map(order => {
            const items = Array.isArray(order.items) ? order.items : [];

            // Filter only items belonging to THIS vendor
            const matchedItems = items.filter(item => {
                const itemVendorId = String(item.vendorId || (item as any).vendor_id || '');
                const itemVendorEmail = String((item as any).vendor_email || '');

                return itemVendorId === String(currentVendor.id) || 
                       itemVendorId === String(currentVendor.user_id) ||
                       (itemVendorEmail && itemVendorEmail.toLowerCase() === currentVendor.email.toLowerCase());
            });

            if (matchedItems.length === 0) return null;

            const vendorSubtotal = matchedItems.reduce((sum, item) => sum + (item.price * item.quantity), 0);

            return {
                ...order,
                vendorItems: matchedItems,
                vendorSubtotal: vendorSubtotal
            } as VendorAugmentedOrder;
        }).filter((o): o is VendorAugmentedOrder => {
            if (!o) return false;

            // Visibility: Only fulfillment stages
            const isValidStatus = ['Placed', 'Confirmed', 'Packed', 'Shipped', 'Out for Delivery', 'Delivered'].includes(o.status);
            if (!isValidStatus) return false;

            if (statusFilter === 'all') return true;
            if (statusFilter === 'pending') return ['Placed', 'Confirmed'].includes(o.status);
            return o.status === statusFilter;
        });

        console.log('[VendorOrders] Debug - Filtered Result:', filtered);
        return filtered;
    }, [orders, currentVendor, statusFilter]);

    const handlePackAndLabel = async (order: VendorAugmentedOrder) => {
        setIsGeneratingLabel(order.id);
        try {
            // Part 2: Simulate Supabase Storage Upload
            // In production, you'd use supabase.storage.from('shipping-labels').upload(...)
            // We'll generate a consistent mock URL that represents the file in storage
            const mockStorageUrl = `https://storage.vexokart.com/shipping-labels/order_${order.id}_label.pdf`;

            // Update status and save label URL
            await updateOrderLabelInfo(order.id, mockStorageUrl);

            alert('Order marked as Packed. Shipping label generated successfully.');
        } catch (err) {
            alert('Failed to generate shipping label. Please try again.');
        } finally {
            setIsGeneratingLabel(null);
        }
    };

    const handleStatusChange = (order: Order, status: OrderStatus) => {
        if (status === 'Shipped') {
            setSelectedOrder(order);
            setShippingModalOpen(true);
        } else {
            updateOrderStatus(order.id, status);
        }
    };

    const handleShippingSubmit = (courierName: string, trackingId: string) => {
        if (selectedOrder) {
            updateOrderStatus(selectedOrder.id, 'Shipped', { courierName, trackingId });
        }
        setShippingModalOpen(false);
        setSelectedOrder(null);
    };

    if (isLoading && vendorOrders.length === 0) {
        return (
            <div className="flex flex-col items-center justify-center p-20">
                <div className="w-10 h-10 border-4 border-accent border-t-transparent rounded-full animate-spin"></div>
                <p className="mt-4 text-text-muted font-black uppercase tracking-widest text-[10px]">Loading orders...</p>
            </div>
        );
    }

    return (
        <div className="space-y-6">
            {isShippingModalOpen && (
                <ShippingDetailsModal
                    onClose={() => setShippingModalOpen(false)}
                    onSubmit={handleShippingSubmit}
                />
            )}

            {labelOrder && currentVendor && (
                <ShippingLabelModal
                  order={labelOrder}
                  vendor={currentVendor}
                  onClose={() => setLabelOrder(null)}
                  onGenerated={() => {}}
                />
            )}

            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <div>
                  <h1 className="text-3xl font-black text-text-main italic tracking-tight uppercase">Vendor Orders</h1>
                  <p className="text-text-muted mt-1 text-sm">Fulfill orders and generate shipping documentation.</p>
                </div>

                <div className="flex bg-surface p-1 rounded-xl border border-border">
                    {['all', 'pending', 'Packed', 'Shipped', 'Delivered'].map(f => (
                        <button
                            key={f}
                            onClick={() => setStatusFilter(f)}
                            className={`px-4 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === f ? 'bg-accent text-white shadow-lg' : 'text-text-muted hover:text-text-secondary'}`}
                        >
                            {f}
                        </button>
                    ))}
                </div>
            </div>

            <GlassmorphicCard>
                <div className="overflow-x-auto">
                    <table className="w-full text-left text-sm">
                        <thead>
                            <tr className="border-b border-white/5 text-text-muted text-[10px] uppercase font-black tracking-widest">
                                <th className="p-6">Order ID</th>
                                <th className="p-6">Customer</th>
                                <th className="p-6">My Items</th>
                                <th className="p-6">Revenue</th>
                                <th className="p-6">Method</th>
                                <th className="p-6">Status</th>
                                <th className="p-6 text-right">Actions</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-white/5">
                            {vendorOrders.map(order => (
                                <tr key={order.id} className="hover:bg-white/[0.02] transition-colors">
                                    <td className="p-6">
                                        <p className="text-text-main font-mono font-bold">#{order.id}</p>
                                        <p className="text-[10px] text-text-muted uppercase font-bold mt-1">{new Date(order.date).toLocaleDateString()}</p>
                                    </td>
                                    <td className="p-6">
                                        <p className="text-text-main font-bold">{order.shippingAddress?.fullName || 'Customer'}</p>
                                        <p className="text-[10px] text-text-muted">{order.userEmail}</p>
                                        <p className="text-[9px] text-text-muted mt-1 truncate max-w-[140px] uppercase">{order.shippingAddress?.city}, {order.shippingAddress?.state}</p>
                                    </td>
                                    <td className="p-6">
                                        <div className="flex flex-col gap-1">
                                            {order.vendorItems.map((item, idx) => (
                                                <span key={idx} className="text-text-main font-bold text-xs truncate max-w-[150px]">
                                                    {item.name} <span className="text-accent">x{item.quantity}</span>
                                                </span>
                                            ))}
                                        </div>
                                    </td>
                                    <td className="p-6">
                                        <span className="text-accent font-black text-sm">₹{order.vendorSubtotal.toLocaleString()}</span>
                                    </td>
                                    <td className="p-6">
