                                          {order.payment_method === 'Cash on Delivery' ? 'COD' : 'Online'}
                                        </span>
                                    </td>
                                    <td className="p-6">
                                        <span className={`text-[10px] font-black uppercase ${
                                            order.status === 'Delivered' ? 'text-green-500' : 
