          };
        });
        setProducts(mappedProducts);
      }
    } catch (error) {
      console.error("Error refreshing products:", error);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    const init = async () => {
        const freshCats = await fetchCategories();
        await refreshProducts(freshCats);
    };
    init();
  }, []);

  const getProduct = (id: number) => products.find(p => p.id === id);

  /**
   * World-class resilient save with intelligent column fallback
   */
  const safeSupabaseSave = async (url: string, method: string, payload: any) => {
    console.log(`[ProductContext] Attempting ${method} with payload:`, payload);

    const response = await fetch(url, {
      method,
      headers: { ...API_HEADERS, 'Prefer': 'return=representation' },
      body: JSON.stringify(payload)
    });

    const result = await response.json();

    if (!response.ok) {
        // PGRST204: Column not found. Detect which columns are missing and retry.
        if (result.code === 'PGRST204') {
            console.warn("[ProductContext] Schema mismatch detected (PGRST204). Retrying with sanitized payload...");

            // Tier 1 Fallback: Remove recently added features that might not exist in the DB table
            const { category_id, images, allow_online, allow_cod, ...fallbackPayload } = payload;

            // If we removed category_id, ensure we have the string category name as a backup
            if (payload.category && !fallbackPayload.category) {
                (fallbackPayload as any).category = payload.category;
            }

            const fallbackRes = await fetch(url, {
                method,
                headers: { ...API_HEADERS, 'Prefer': 'return=representation' },
                body: JSON.stringify(fallbackPayload)
            });

            if (!fallbackRes.ok) {
                const finalErr = await fallbackRes.json();
                console.error("[ProductContext] Critical Fallback Failure:", finalErr);
                throw new Error(finalErr.message || 'Legacy database synchronization failed.');
            }
            return await fallbackRes.json();
        }
        throw new Error(result.message || 'Server rejected the product update.');
