export default AdminProductFormPage;

import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useProducts } from '../../hooks/useProducts';
import { useCategories } from '../../hooks/useCategories';
import GlassmorphicCard from '../../components/GlassmorphicCard';
import { Product } from '../../types';
import { useVendors } from '../../context/VendorContext';
import { useAuth } from '../../context/AuthContext';
import Toast from '../../components/Toast';
import { ChevronLeftIcon } from '../../components/icons/ChevronLeftIcon';
import ImageCropperModal from '../../components/ImageCropperModal';

const VendorProductFormPage: React.FC = () => {
  const { id } = useParams<{ id?: string }>();
  const navigate = useNavigate();
  const { getProduct, addProduct, updateProduct } = useProducts();
  const { categories } = useCategories();
  const { currentVendor, fetchCurrentVendor } = useVendors();
  const { user } = useAuth();

  const isEditing = id !== undefined;
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [toast, setToast] = useState({ show: false, message: '', type: 'success' as 'success' | 'info' });

  const [formData, setFormData] = useState<Omit<Product, 'id' | 'reviews' | 'rating' | 'reviewCount' | 'status' | 'vendorId'>>({
    name: '',
    category: '', 
    price: 0,
    originalPrice: 0,
    images: [],
    description: '',
    highlights: [],
    stock: 10,
    specifications: {},
    sellerInfo: '',
    returnPolicy: '30-Day Money Back Guarantee',
    warranty: '1 Year Standard Warranty',
    videoUrl: '',
    allow_online: true,
    allow_cod: true
  });

  const [highlightsText, setHighlightsText] = useState('');
  const [specsText, setSpecsText] = useState('');

  // Cropper States
  const [cropQueue, setCropQueue] = useState<string[]>([]);
  const [currentCropIndex, setCurrentCropIndex] = useState(0);
  const [totalInQueue, setTotalInQueue] = useState(0);

  const inputClasses = "w-full mt-1 bg-surface text-text-main border border-gray-600 rounded-lg p-3 transition focus:outline-none focus:border-accent focus:ring-2 focus:ring-accent/50";

  const showToast = (message: string, type: 'success' | 'info' = 'success') => {
    setToast({ show: true, message, type });
  };

  useEffect(() => {
    if (user?.email && !currentVendor) fetchCurrentVendor(user.email);
  }, [user, currentVendor]);

  useEffect(() => {
    if (isEditing) {
      const productToEdit = getProduct(parseInt(id));
      if (productToEdit) {
        const cat = categories.find(c => c.name === productToEdit.category);
        setFormData({ 
            ...productToEdit, 
            category: cat ? cat.id.toString() : '',
            allow_online: productToEdit.allow_online ?? true,
            allow_cod: productToEdit.allow_cod ?? true
        });
        setHighlightsText((productToEdit.highlights || []).join('\n'));
        setSpecsText(Object.entries(productToEdit.specifications || {}).map(([k, v]) => `${k}: ${v}`).join('\n'));
      }
    } else if (categories.length > 0) {
      setFormData(prev => ({...prev, category: categories[0].id.toString()}));
    }
  }, [id, isEditing, getProduct, categories]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target as any;
    if (type === 'checkbox') {
        setFormData(prev => ({ ...prev, [name]: (e.target as any).checked }));
    } else {
        setFormData(prev => ({ ...prev, [name]: ['price', 'originalPrice', 'stock'].includes(name) ? parseFloat(value) || 0 : value }));
    }
  };

  const validateImage = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
        const img = new Image();
        img.onload = () => {
            if (img.width < 600 || img.height < 600) {
                reject(`Visual "${file.name}" is low resolution (${img.width}x${img.height}). We require 600x600px minimum.`);
            } else {
                resolve(URL.createObjectURL(file));
            }
        };
        img.onerror = () => reject("Corrupted media file.");
        img.src = URL.createObjectURL(file);
    });
  };

  const handleImageChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const files = Array.from(e.target.files);
      const urls: string[] = [];

      if (formData.images.length + files.length > 5) {
          alert("Maximum 5 assets allowed per catalog entry.");
          return;
      }

      for (const file of files) {
          try {
              const url = await validateImage(file);
              urls.push(url);
          } catch (err: any) {
              alert(err);
          }
      }

      if (urls.length > 0) {
        setTotalInQueue(urls.length);
        setCurrentCropIndex(0);
        setCropQueue(urls);
      }

      e.target.value = '';
    }
  };

  const handleCropComplete = (croppedBase64: string) => {
    setFormData(prev => ({ ...prev, images: [...prev.images, croppedBase64] }));

    if (currentCropIndex < cropQueue.length - 1) {
        setCurrentCropIndex(prev => prev + 1);
    } else {
        setCropQueue([]);
    }
  };

  const removeImage = (index: number) => {
    setFormData(prev => ({ ...prev, images: prev.images.filter((_, i) => i !== index) }));
  };

  const setAsCover = (index: number) => {
    setFormData(prev => {
        const newImages = [...prev.images];
        const [cover] = newImages.splice(index, 1);
        return { ...prev, images: [cover, ...newImages] };
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentVendor) { alert("Vendor session expired."); return; }
    if (formData.images.length === 0) { alert("Visual assets are mandatory."); return; }
    if (!formData.allow_online && !formData.allow_cod) { alert("Select a supported payment mode."); return; }

    setIsSubmitting(true);
    try {
        const finalHighlights = highlightsText.split('\n').map(s => s.trim()).filter(Boolean);
        const finalSpecs: { [key: string]: string } = {};
        specsText.split('\n').forEach(line => {
          const parts = line.split(':');
          if (parts.length === 2) finalSpecs[parts[0].trim()] = parts[1].trim();
        });

        const finalData = { 
            ...formData, 
            vendor_id: currentVendor.id,
            highlights: finalHighlights, 
            specifications: finalSpecs 
        };

        if (isEditing) {
          await updateProduct({ ...finalData as any, id: parseInt(id), status: 'approved' });
          showToast("Catalog Updated Successfully!");
        } else {
          await addProduct({ ...finalData, status: 'approved' });
          showToast("Listing Published Successfully!");
        }
        setTimeout(() => navigate('/vendor/products'), 1500);
    } catch (err: any) {
        alert(err.message || "Network Error.");
    } finally {
        setIsSubmitting(false);
    }
  };

  return (
    <div className="pb-10 max-w-5xl mx-auto">
      <Toast isVisible={toast.show} message={toast.message} type={toast.type} onClose={() => setToast({ ...toast, show: false })} />

      {cropQueue.length > 0 && (
          <ImageCropperModal 
            image={cropQueue[currentCropIndex]} 
            queueCount={currentCropIndex + 1}
            totalInQueue={totalInQueue}
            title="Optimizing Image Quality"
            onCropComplete={handleCropComplete}
            onCancel={() => setCropQueue([])}
          />
      )}

      <div className="flex items-center gap-4 mb-8">
          <button onClick={() => navigate('/vendor/products')} className="p-3 bg-surface rounded-2xl hover:bg-white transition-all shadow-sm border border-border">
              <ChevronLeftIcon className="w-5 h-5" />
          </button>
          <h1 className="text-3xl font-black text-text-main italic tracking-tight uppercase">
            {isEditing ? 'Modify Listing' : 'Marketplace Entry'}
          </h1>
      </div>

      <form onSubmit={handleSubmit} className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 space-y-6">
            <GlassmorphicCard className="p-8">
                <h2 className="text-[10px] font-black uppercase tracking-widest text-text-muted mb-6 border-b border-border pb-2">Product Information</h2>
                <div className="space-y-4">
                    <div>
                        <label className="block text-[10px] font-black uppercase text-text-muted mb-1">Commercial Title</label>
                        <input type="text" name="name" value={formData.name} onChange={handleChange} required className={inputClasses} placeholder="e.g., Signature Suede Loafers" />
                    </div>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div>
                            <label className="block text-[10px] font-black uppercase text-text-muted mb-1">Product Category</label>
                            <select name="category" value={formData.category} onChange={handleChange} className={inputClasses}>
                                {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                            </select>
                        </div>
                        <div>
                            <label className="block text-[10px] font-black uppercase text-text-muted mb-1">Available Units</label>
                            <input type="number" name="stock" value={formData.stock} onChange={handleChange} required className={inputClasses} />
                        </div>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-[10px] font-black uppercase text-text-muted mb-1">Price (₹)</label>
                            <input type="number" name="price" value={formData.price} onChange={handleChange} required className={inputClasses} />
                        </div>
                        <div>
                            <label className="block text-[10px] font-black uppercase text-text-muted mb-1">Old Price (₹)</label>
                            <input type="number" name="originalPrice" value={formData.originalPrice} onChange={handleChange} className={inputClasses} />
                        </div>
                    </div>
                </div>
            </GlassmorphicCard>

            <GlassmorphicCard className="p-8">
                <h2 className="text-[10px] font-black uppercase tracking-widest text-text-muted mb-6 border-b border-border pb-2">Catalog Content</h2>
                <div className="space-y-4">
                    <div>
                        <label className="block text-[10px] font-black uppercase text-text-muted mb-1">Detailed Copy</label>
                        <textarea name="description" value={formData.description} onChange={handleChange} required rows={4} className={`${inputClasses} resize-none`} placeholder="Describe the item in detail..."></textarea>
                    </div>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div>
                            <label className="block text-[10px] font-black uppercase text-text-muted mb-1">Highlights (Per Line)</label>
                            <textarea value={highlightsText} onChange={(e) => setHighlightsText(e.target.value)} rows={4} className={`${inputClasses} resize-none font-medium`} placeholder="• Eco-friendly Material"></textarea>
                        </div>
                        <div>
                            <label className="block text-[10px] font-black uppercase text-text-muted mb-1">Specifications (K:V)</label>
                            <textarea value={specsText} onChange={(e) => setSpecsText(e.target.value)} rows={4} className={`${inputClasses} resize-none font-mono text-xs`} placeholder="Size: XL"></textarea>
                        </div>
                    </div>
                </div>
            </GlassmorphicCard>
        </div>

        <div className="space-y-6">
            <GlassmorphicCard className="p-8">
                <h2 className="text-[10px] font-black uppercase tracking-widest text-text-muted mb-6 border-b border-border pb-2">Verified Visuals</h2>
                <div className="space-y-4">
                    <div className="border-2 border-dashed border-border rounded-2xl p-6 text-center bg-surface/30 group hover:border-accent transition-colors">
                        <input type="file" id="imageUpload" multiple accept="image/*" onChange={handleImageChange} className="hidden" disabled={formData.images.length >= 5} />
                        <label htmlFor="imageUpload" className={`cursor-pointer block ${formData.images.length >= 5 ? 'opacity-50 cursor-not-allowed' : ''}`}>
                            <div className="w-12 h-12 bg-accent/10 rounded-full flex items-center justify-center mx-auto mb-3 group-hover:scale-110 transition-transform">
                                <svg className="w-6 h-6 text-accent" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
                            </div>
                            <p className="text-xs font-black uppercase tracking-tighter text-text-main">Add Assets</p>
                            <p className="text-[10px] text-text-muted mt-1">{5 - formData.images.length} slots remaining</p>
                        </label>
                    </div>

                    <div className="grid grid-cols-1 gap-3">
                        {formData.images.map((image, index) => (
                            <div key={index} className="relative group p-2 bg-surface rounded-xl border border-border flex items-center gap-3">
                                <img src={image} className="w-16 h-16 object-cover rounded-lg border border-border bg-white" alt={`product ${index}`} />
                                <div className="flex-grow text-left">
                                    <p className="text-[9px] font-black uppercase text-text-muted tracking-widest">{index === 0 ? 'Primary Cover' : `View ${index + 1}`}</p>
                                    <div className="flex gap-2 mt-1">
                                        {index !== 0 && (
                                            <button type="button" onClick={() => setAsCover(index)} className="text-[8px] font-black uppercase text-accent hover:underline">Mark Cover</button>
                                        )}
                                        <button type="button" onClick={() => removeImage(index)} className="text-[8px] font-black uppercase text-red-500 hover:underline">Remove</button>
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </GlassmorphicCard>

            <GlassmorphicCard className="p-8">
                <h2 className="text-[10px] font-black uppercase tracking-widest text-text-muted mb-6 border-b border-border pb-2">Trade Terms</h2>
                <div className="space-y-4">
                    <label className="flex items-center gap-3 cursor-pointer group p-3 bg-surface rounded-xl border border-border">
                        <input type="checkbox" name="allow_online" checked={formData.allow_online} onChange={handleChange} className="w-5 h-5 rounded border-gray-600 text-accent" />
                        <span className="text-xs font-bold text-text-main group-hover:text-accent transition-colors">Digital Transaction</span>
                    </label>
                    <label className="flex items-center gap-3 cursor-pointer group p-3 bg-surface rounded-xl border border-border">
                        <input type="checkbox" name="allow_cod" checked={formData.allow_cod} onChange={handleChange} className="w-5 h-5 rounded border-gray-600 text-accent" />
                        <span className="text-xs font-bold text-text-main group-hover:text-accent transition-colors">Cash On Delivery</span>
                    </label>
                </div>
                <div className="mt-8 flex flex-col gap-3">
                    <button type="submit" disabled={isSubmitting} className="w-full bg-accent text-white py-4 rounded-2xl font-black uppercase tracking-widest text-xs shadow-xl shadow-accent/30 hover:-translate-y-1 active:translate-y-0 transition-all disabled:opacity-50">
                        {isSubmitting ? 'Syncing...' : (isEditing ? 'Commit Changes' : 'Go Live Now')}
                    </button>
                </div>
            </GlassmorphicCard>
        </div>
      </form>
    </div>
  );
};

export default VendorProductFormPage;

export const createImage = (url: string): Promise<HTMLImageElement> =>
  new Promise((resolve, reject) => {
    const image = new Image();
    image.addEventListener('load', () => resolve(image));
    image.addEventListener('error', (error) => reject(error));
    image.setAttribute('crossOrigin', 'anonymous');
    image.src = url;
  });

export function getRadianAngle(degreeValue: number) {
  return (degreeValue * Math.PI) / 180;
}

/**
 * Returns the new bounding area of a rotated rectangle.
 */
export function rotateSize(width: number, height: number, rotation: number) {
  const rotRad = getRadianAngle(rotation);

  return {
    width:
      Math.abs(Math.cos(rotRad) * width) + Math.abs(Math.sin(rotRad) * height),
    height:
      Math.abs(Math.sin(rotRad) * width) + Math.abs(Math.cos(rotRad) * height),
  };
}

/**
 * This function takes an image source and pixel crop coordinates 
 * and returns the cropped image as an optimized base64 string.
 */
export async function getCroppedImg(
  imageSrc: string,
  pixelCrop: { x: number; y: number; width: number; height: number },
  rotation = 0,
  flip = { horizontal: false, vertical: false }
): Promise<string> {
  const image = await createImage(imageSrc);
  const canvas = document.createElement('canvas');
  const ctx = canvas.getContext('2d');

  if (!ctx) {
    throw new Error('No 2d context');
  }

  const rotRad = getRadianAngle(rotation);

  // Calculate bounding box of the rotated image
  const { width: bBoxWidth, height: bBoxHeight } = rotateSize(
    image.width,
    image.height,
    rotation
  );

  // Set canvas size to match the bounding box
  canvas.width = bBoxWidth;
  canvas.height = bBoxHeight;

  // Translate canvas context to a central point and draw image
  ctx.translate(bBoxWidth / 2, bBoxHeight / 2);
  ctx.rotate(rotRad);
  ctx.scale(flip.horizontal ? -1 : 1, flip.vertical ? -1 : 1);
  ctx.translate(-image.width / 2, -image.height / 2);

  // Draw rotated image
  ctx.drawImage(image, 0, 0);

  // Second canvas for the actual crop extraction
  const croppedCanvas = document.createElement('canvas');
  const croppedCtx = croppedCanvas.getContext('2d');

  if (!croppedCtx) {
    throw new Error('No 2d context for crop');
  }

  // Set the size of the final cropped canvas
  croppedCanvas.width = pixelCrop.width;
  croppedCanvas.height = pixelCrop.height;

  // Extract the cropped pixels from the main canvas
  const data = ctx.getImageData(
    pixelCrop.x,
    pixelCrop.y,
    pixelCrop.width,
    pixelCrop.height
  );

  croppedCtx.putImageData(data, 0, 0);

  // Optimization: Compress to JPEG 0.6 (60%) for better mobile storage/loading performance
  return new Promise((resolve) => {
    resolve(croppedCanvas.toDataURL('image/jpeg', 0.6));
  });
}

import React, { createContext, useState, useEffect, ReactNode, useContext } from 'react';
import { Product, Review, Category } from '../types';
import { BASE_API_URL, API_HEADERS } from '../constants';

interface ProductContextType {
  products: Product[];
  isLoading: boolean;
  getProduct: (id: number) => Product | undefined;
  addProduct: (product: any) => Promise<void>;
  updateProduct: (product: Product) => Promise<void>;
  deleteProduct: (productId: number) => Promise<void>;
  toggleProductStatus: (productId: number) => Promise<void>;
  approveProduct: (productId: number, approvedBy?: string) => Promise<void>;
  rejectProduct: (productId: number, reason: string) => Promise<void>;
  disableProduct: (productId: number) => Promise<void>;
  addReview: (productId: number, reviewData: Omit<Review, 'id' | 'date'>) => Promise<void>;
  refreshProducts: (providedCategories?: Category[]) => Promise<void>;
}

export const ProductContext = createContext<ProductContextType | undefined>(undefined);

export const ProductProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [products, setProducts] = useState<Product[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [categories, setCategories] = useState<Category[]>([]);

  const fetchCategories = async (): Promise<Category[]> => {
    try {
      const res = await fetch(`${BASE_API_URL}/categories?select=*`, { headers: API_HEADERS });
      const data = await res.json();
      if (Array.isArray(data)) {
        setCategories(data);
        return data;
      }
      return [];
    } catch (e) {
      console.error("Failed to fetch categories:", e);
      return [];
    }
  };

  const refreshProducts = async (providedCategories?: Category[]) => {
    try {
      const response = await fetch(`${BASE_API_URL}/products?select=*`, { 
        headers: { ...API_HEADERS, 'Cache-Control': 'no-cache' } 
      });
      const data = await response.json();
      const currentCats = providedCategories || categories;

      if (Array.isArray(data)) {
        const mappedProducts: Product[] = data.map((item: any) => {
          const cat = currentCats.find(c => Number(c.id) === Number(item.category_id));

          let productImages: string[] = [];
          if (Array.isArray(item.images) && item.images.length > 0) {
            productImages = item.images;
          } else if (item.images && typeof item.images === 'string') {
             try {
                const parsed = JSON.parse(item.images);
                if (Array.isArray(parsed)) productImages = parsed;
             } catch(e) {
                productImages = [item.images];
             }
          } else if (item.image) {
            productImages = [item.image];
          }

          return {
            id: item.id,
            name: item.name || 'Untitled Product',
            description: item.description || '',
            price: Number(item.price) || 0,
            originalPrice: Number(item.original_price || item.price || 0),
            stock: Number(item.stock) || 0,
            images: productImages,
            category: cat ? cat.name : (item.category || 'General'),
            vendorId: item.vendor_id ? item.vendor_id.toString() : 'internal',
            status: item.status || 'approved',
            rating: Number(item.rating) || 0,
            reviewCount: Number(item.review_count) || 0,
            reviews: item.reviews || [],
            highlights: item.highlights || [],
            specifications: item.specifications || {},
            sellerInfo: item.seller_info || 'VexoKart Partner',
            returnPolicy: item.return_policy || 'Standard Returns',
            warranty: item.warranty || 'No Warranty',
            videoUrl: item.video_url || '',
            approved_at: item.approved_at,
            approved_by: item.approved_by,
            rejectionReason: item.rejection_reason,
            allow_online: item.allow_online ?? true,
            allow_cod: item.allow_cod ?? true
          };
        });
        setProducts(mappedProducts);
      }
    } catch (error) {
      console.error("Error refreshing products:", error);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    const init = async () => {
        const freshCats = await fetchCategories();
        await refreshProducts(freshCats);
    };
    init();
  }, []);

  const getProduct = (id: number) => products.find(p => p.id === id);

  /**
   * ADAPTIVE SAVE UTILITY
   * Handles column stripping and schema adaptation when Supabase throws errors.
   */
  const safeSupabaseSave = async (url: string, method: string, payload: any) => {
    let currentPayload = { ...payload };
    if (currentPayload.id) delete currentPayload.id;

    let attempts = 0;
    const maxAttempts = 12;

    while (attempts < maxAttempts) {
      try {
        const response = await fetch(url, {
          method,
          headers: { ...API_HEADERS, 'Prefer': 'return=representation' },
          body: JSON.stringify(currentPayload)
        });

        const result = await response.json();

        if (response.ok) {
          return result;
        }

        // Schema Cache Mismatch (Column Missing)
        if (result.code === 'PGRST204') {
          console.warn(`[Supabase Adaptation] ${result.message}`);

          const match = result.message.match(/column ['"](.+?)['"]/i);
          const missingColumn = match ? match[1] : null;

          if (missingColumn && currentPayload.hasOwnProperty(missingColumn)) {
            console.warn(`[Supabase Adaptation] Removing missing column: ${missingColumn}`);
            delete currentPayload[missingColumn];
            attempts++;
            continue;
          }

          // Force-remove common suspect columns if automated detection fails
          const commonSuspects = ['category', 'images', 'vendor_id', 'allow_online', 'allow_cod', 'status', 'approved_by', 'approved_at', 'original_price'];
          let stripped = false;
          for (const key of commonSuspects) {
              if (currentPayload.hasOwnProperty(key)) {
                  delete currentPayload[key];
                  stripped = true;
                  break; 
              }
          }

          if (!stripped) throw new Error(`Schema mismatch: ${JSON.stringify(result)}`);
          attempts++;
        } else {
          console.error("[Supabase Error]", JSON.stringify(result));
          throw new Error(result.message || 'Database error');
        }
      } catch (err: any) {
        console.error("[Save Critical Failure]", err.message);
        throw err;
      }
    }
    throw new Error("Unable to synchronize with database schema.");
  };

  const addProduct = async (productData: any) => {
    let selectedCategoryId = null;
    let matchedCategoryName = 'General';

    if (!isNaN(Number(productData.category))) {
        selectedCategoryId = Number(productData.category);
        matchedCategoryName = categories.find(c => Number(c.id) === selectedCategoryId)?.name || 'General';
    } else {
        const found = categories.find(c => c.name === productData.category);
        selectedCategoryId = found ? Number(found.id) : null;
        matchedCategoryName = productData.category || 'General';
    }

    const supabasePayload: any = {
      name: productData.name,
      description: productData.description,
      price: productData.price,
      stock: productData.stock || 0,
      image: productData.images?.[0] || '', 
      images: productData.images || [], 
      status: 'approved',
      vendor_id: Number(productData.vendor_id) || null, 
      created_at: new Date().toISOString(),
      allow_online: productData.allow_online ?? true,
      allow_cod: productData.allow_cod ?? true,
      category_id: selectedCategoryId,
      category: matchedCategoryName
    };

    await safeSupabaseSave(`${BASE_API_URL}/products`, 'POST', supabasePayload);
    await refreshProducts();
  };

  const updateProduct = async (product: Product) => {
    let selectedCategoryId = null;
    let matchedCategoryName = 'General';

    if (!isNaN(Number(product.category))) {
        selectedCategoryId = Number(product.category);
        matchedCategoryName = categories.find(c => Number(c.id) === selectedCategoryId)?.name || 'General';
    } else {
        const found = categories.find(c => c.name === product.category);
        selectedCategoryId = found ? Number(found.id) : null;
        matchedCategoryName = product.category || 'General';
    }

    const supabaseUpdate: any = {
      name: product.name,
      description: product.description,
      price: product.price,
      stock: product.stock,
      image: product.images?.[0] || '',
      images: product.images || [],
      allow_online: product.allow_online,
      allow_cod: product.allow_cod,
      category_id: selectedCategoryId,
      category: matchedCategoryName
    };

    await safeSupabaseSave(`${BASE_API_URL}/products?id=eq.${product.id}`, 'PATCH', supabaseUpdate);
    await refreshProducts();
  };

  const deleteProduct = async (productId: number) => {
    await fetch(`${BASE_API_URL}/products?id=eq.${productId}`, {
      method: 'DELETE',
      headers: API_HEADERS
    });
    await refreshProducts();
  };

  const toggleProductStatus = async (productId: number) => {
    const p = getProduct(productId);
    if (!p) return;
    const newStatus = p.status === 'approved' ? 'disabled' : 'approved';
    await fetch(`${BASE_API_URL}/products?id=eq.${productId}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify({ status: newStatus })
    });
    await refreshProducts();
  };

  const approveProduct = async (productId: number, approvedBy?: string) => {
    await fetch(`${BASE_API_URL}/products?id=eq.${productId}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify({ 
        status: 'approved', 
        approved_by: approvedBy, 
        approved_at: new Date().toISOString() 
      })
    });
    await refreshProducts();
  };

  const rejectProduct = async (productId: number, reason: string) => {
    await fetch(`${BASE_API_URL}/products?id=eq.${productId}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify({ status: 'rejected', rejection_reason: reason })
    });
    await refreshProducts();
  };

  const disableProduct = async (productId: number) => {
    await fetch(`${BASE_API_URL}/products?id=eq.${productId}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify({ status: 'disabled' })
    });
    await refreshProducts();
  };

  const addReview = async (productId: number, reviewData: any) => {
    const p = getProduct(productId);
    if (!p) return;
    const newReview = { ...reviewData, id: Math.random().toString(36).substr(2, 9), date: new Date().toISOString() };
    const updatedReviews = [newReview, ...(p.reviews || [])];
    const newCount = updatedReviews.length;
    const newRating = Number(((p.rating * (p.reviewCount || 0) + reviewData.rating) / newCount).toFixed(1));

    try {
        await fetch(`${BASE_API_URL}/products?id=eq.${productId}`, {
          method: 'PATCH',
          headers: API_HEADERS,
          body: JSON.stringify({ 
              reviews: updatedReviews, 
              review_count: newCount, 
              rating: newRating 
          })
        });
        await refreshProducts();
    } catch (e) {
        console.warn("Review storage failed.");
    }
  };

  return (
    <ProductContext.Provider value={{ 
      products, isLoading, getProduct, addProduct, updateProduct, 
      deleteProduct, toggleProductStatus, approveProduct, rejectProduct, 
      disableProduct, addReview, refreshProducts 
    }}>
      {children}
    </ProductContext.Provider>
  );
};

export const useProducts = () => {
  const context = useContext(ProductContext);
  if (!context) throw new Error("useProducts must be used within ProductProvider");
  return context;
};

import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useProducts } from '../../hooks/useProducts';
import { useCategories } from '../../hooks/useCategories';
import GlassmorphicCard from '../../components/GlassmorphicCard';
import { Product } from '../../types';
import { useVendors } from '../../context/VendorContext';
import { useAuth } from '../../context/AuthContext';
import Toast from '../../components/Toast';
import { ChevronLeftIcon } from '../../components/icons/ChevronLeftIcon';
import ImageCropperModal from '../../components/ImageCropperModal';

const VendorProductFormPage: React.FC = () => {
  const { id } = useParams<{ id?: string }>();
  const navigate = useNavigate();
  const { getProduct, addProduct, updateProduct } = useProducts();
  const { categories } = useCategories();
  const { currentVendor, fetchCurrentVendor } = useVendors();
  const { user } = useAuth();

  const isEditing = id !== undefined;
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [toast, setToast] = useState({ show: false, message: '', type: 'success' as 'success' | 'info' });

  const [formData, setFormData] = useState<Omit<Product, 'id' | 'reviews' | 'rating' | 'reviewCount' | 'status' | 'vendorId'>>({
    name: '',
    category: '', 
    price: 0,
    originalPrice: 0,
    images: [],
    description: '',
    highlights: [],
    stock: 10,
    specifications: {},
    sellerInfo: '',
    returnPolicy: '30-Day Money Back Guarantee',
    warranty: '1 Year Standard Warranty',
    videoUrl: '',
    allow_online: true,
    allow_cod: true
  });

  const [highlightsText, setHighlightsText] = useState('');
  const [specsText, setSpecsText] = useState('');

  // Cropper States
  const [cropQueue, setCropQueue] = useState<string[]>([]);
  const [currentCropIndex, setCurrentCropIndex] = useState(0);
  const [totalInQueue, setTotalInQueue] = useState(0);

  const inputClasses = "w-full mt-1 bg-surface text-text-main border border-gray-600 rounded-lg p-3 transition focus:outline-none focus:border-accent focus:ring-2 focus:ring-accent/50 disabled:opacity-50";

  const showToast = (message: string, type: 'success' | 'info' = 'success') => {
    setToast({ show: true, message, type });
  };

  useEffect(() => {
    if (user?.email && !currentVendor) fetchCurrentVendor(user.email);
  }, [user, currentVendor]);

  useEffect(() => {
    if (isEditing) {
      const productToEdit = getProduct(parseInt(id));
      if (productToEdit) {
        const cat = categories.find(c => c.name === productToEdit.category);
        setFormData({ 
            ...productToEdit, 
            category: cat ? cat.id.toString() : '',
            allow_online: productToEdit.allow_online ?? true,
            allow_cod: productToEdit.allow_cod ?? true
        });
        setHighlightsText((productToEdit.highlights || []).join('\n'));
        setSpecsText(Object.entries(productToEdit.specifications || {}).map(([k, v]) => `${k}: ${v}`).join('\n'));
      }
    } else if (categories.length > 0) {
      setFormData(prev => ({...prev, category: categories[0].id.toString()}));
    }
  }, [id, isEditing, getProduct, categories]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target as any;
    if (type === 'checkbox') {
        setFormData(prev => ({ ...prev, [name]: (e.target as any).checked }));
    } else {
        setFormData(prev => ({ ...prev, [name]: ['price', 'originalPrice', 'stock'].includes(name) ? parseFloat(value) || 0 : value }));
    }
  };

  const validateImage = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
        const img = new Image();
        img.onload = () => {
            if (img.width < 100 || img.height < 100) {
                reject(`Visual "${file.name}" is too small. We require 100x100px minimum.`);
            } else {
                resolve(URL.createObjectURL(file));
            }
        };
        img.onerror = () => reject("Corrupted media file.");
        img.src = URL.createObjectURL(file);
    });
  };

  const handleImageChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const files = Array.from(e.target.files);
      const urls: string[] = [];

      if (formData.images.length + files.length > 5) {
          alert("Maximum 5 assets allowed per catalog entry.");
          return;
      }

      for (const file of files) {
          try {
              const url = await validateImage(file);
              urls.push(url);
          } catch (err: any) {
              alert(err);
          }
      }

      if (urls.length > 0) {
        setTotalInQueue(urls.length);
        setCurrentCropIndex(0);
        setCropQueue(urls);
      }

      e.target.value = '';
    }
  };

  const handleCropComplete = (croppedBase64: string) => {
    setFormData(prev => ({ ...prev, images: [...prev.images, croppedBase64] }));

    if (currentCropIndex < cropQueue.length - 1) {
        setCurrentCropIndex(prev => prev + 1);
    } else {
        setCropQueue([]);
    }
  };

  const removeImage = (index: number) => {
    setFormData(prev => ({ ...prev, images: prev.images.filter((_, i) => i !== index) }));
  };

  const setAsCover = (index: number) => {
    setFormData(prev => {
        const newImages = [...prev.images];
        const [cover] = newImages.splice(index, 1);
        return { ...prev, images: [cover, ...newImages] };
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentVendor) { alert("Vendor session expired."); return; }
    if (formData.images.length === 0) { alert("Please provide at least one product image."); return; }
    if (!formData.allow_online && !formData.allow_cod) { alert("Select a supported payment mode."); return; }

    setIsSubmitting(true);
    try {
        const finalHighlights = highlightsText.split('\n').map(s => s.trim()).filter(Boolean);
        const finalSpecs: { [key: string]: string } = {};
        specsText.split('\n').forEach(line => {
          const parts = line.split(':');
          if (parts.length === 2) finalSpecs[parts[0].trim()] = parts[1].trim();
        });

        const finalData = { 
            ...formData, 
            vendor_id: currentVendor.id,
            highlights: finalHighlights, 
            specifications: finalSpecs 
        };

        if (isEditing) {
          await updateProduct({ ...finalData as any, id: parseInt(id), status: 'approved' });
          showToast("Changes synced successfully.");
        } else {
          await addProduct({ ...finalData, status: 'approved' });
          showToast("Listing published to marketplace.");
        }
        setTimeout(() => navigate('/vendor/products'), 1500);
    } catch (err: any) {
        console.error("[Listing Error]", err);
        alert(`Failed to save listing: ${err.message || "Network Error"}`);
    } finally {
        setIsSubmitting(false);
    }
  };

  return (
    <div className="pb-10 max-w-5xl mx-auto">
      <Toast isVisible={toast.show} message={toast.message} type={toast.type} onClose={() => setToast({ ...toast, show: false })} />

      {cropQueue.length > 0 && (
          <ImageCropperModal 
            image={cropQueue[currentCropIndex]} 
            queueCount={currentCropIndex + 1}
            totalInQueue={totalInQueue}
            title="Standardize Product Visual"
            onCropComplete={handleCropComplete}
            onCancel={() => setCropQueue([])}
          />
      )}

      <div className="flex items-center gap-4 mb-8">
          <button onClick={() => navigate('/vendor/products')} className="p-3 bg-surface rounded-2xl hover:bg-white transition-all shadow-sm border border-border">
              <ChevronLeftIcon className="w-5 h-5" />
          </button>
          <h1 className="text-3xl font-black text-text-main italic tracking-tight uppercase">
            {isEditing ? 'Modify Listing' : 'Marketplace Entry'}
          </h1>
      </div>

      <form onSubmit={handleSubmit} className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 space-y-6">
            <GlassmorphicCard className="p-8">
                <h2 className="text-[10px] font-black uppercase tracking-widest text-text-muted mb-6 border-b border-border pb-2">Listing Attributes</h2>
                <div className="space-y-4">
                    <div>
                        <label className="block text-[10px] font-black uppercase text-text-muted mb-1">Commercial Title</label>
                        <input type="text" name="name" value={formData.name} onChange={handleChange} required disabled={isSubmitting} className={inputClasses} placeholder="e.g., Signature Suede Loafers" />
                    </div>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div>
                            <label className="block text-[10px] font-black uppercase text-text-muted mb-1">Product Category</label>
                            <select name="category" value={formData.category} onChange={handleChange} disabled={isSubmitting} className={inputClasses}>
                                {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                            </select>
                        </div>
                        <div>
                            <label className="block text-[10px] font-black uppercase text-text-muted mb-1">Units in Stock</label>
                            <input type="number" name="stock" value={formData.stock} onChange={handleChange} required disabled={isSubmitting} className={inputClasses} />
                        </div>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-[10px] font-black uppercase text-text-muted mb-1">Market Price (₹)</label>
                            <input type="number" name="price" value={formData.price} onChange={handleChange} required disabled={isSubmitting} className={inputClasses} />
                        </div>
                        <div>
                            <label className="block text-[10px] font-black uppercase text-text-muted mb-1">Old Price (₹)</label>
                            <input type="number" name="originalPrice" value={formData.originalPrice} onChange={handleChange} disabled={isSubmitting} className={inputClasses} />
                        </div>
                    </div>
                </div>
            </GlassmorphicCard>

            <GlassmorphicCard className="p-8">
                <h2 className="text-[10px] font-black uppercase tracking-widest text-text-muted mb-6 border-b border-border pb-2">Content Strategy</h2>
                <div className="space-y-4">
                    <div>
                        <label className="block text-[10px] font-black uppercase text-text-muted mb-1">Detailed Description</label>
                        <textarea name="description" value={formData.description} onChange={handleChange} required rows={4} disabled={isSubmitting} className={`${inputClasses} resize-none`} placeholder="Describe the item's unique value..."></textarea>
                    </div>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div>
                            <label className="block text-[10px] font-black uppercase text-text-muted mb-1">Key Highlights</label>
                            <textarea value={highlightsText} onChange={(e) => setHighlightsText(e.target.value)} rows={4} disabled={isSubmitting} className={`${inputClasses} resize-none font-medium`} placeholder="• Eco-friendly Material"></textarea>
                        </div>
                        <div>
                            <label className="block text-[10px] font-black uppercase text-text-muted mb-1">Technical Specs (K:V)</label>
                            <textarea value={specsText} onChange={(e) => setSpecsText(e.target.value)} rows={4} disabled={isSubmitting} className={`${inputClasses} resize-none font-mono text-xs`} placeholder="Size: XL"></textarea>
                        </div>
                    </div>
                </div>
            </GlassmorphicCard>
        </div>

        <div className="space-y-6">
            <GlassmorphicCard className="p-8">
                <h2 className="text-[10px] font-black uppercase tracking-widest text-text-muted mb-6 border-b border-border pb-2">Visual Catalog</h2>
                <div className="space-y-4">
                    <div className="border-2 border-dashed border-border rounded-2xl p-6 text-center bg-surface/30 group hover:border-accent transition-colors">
                        <input type="file" id="imageUpload" multiple accept="image/*" onChange={handleImageChange} className="hidden" disabled={isSubmitting || formData.images.length >= 5} />
                        <label htmlFor="imageUpload" className={`cursor-pointer block ${formData.images.length >= 5 || isSubmitting ? 'opacity-50 cursor-not-allowed' : ''}`}>
                            <div className="w-12 h-12 bg-accent/10 rounded-full flex items-center justify-center mx-auto mb-3 group-hover:scale-110 transition-transform">
                                <svg className="w-6 h-6 text-accent" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
                            </div>
                            <p className="text-xs font-black uppercase tracking-tighter text-text-main">Add Visuals</p>
                            <p className="text-[10px] text-text-muted mt-1">{5 - formData.images.length} slots remaining</p>
                        </label>
                    </div>

                    <div className="grid grid-cols-1 gap-3">
                        {formData.images.map((image, index) => (
                            <div key={index} className="relative group p-2 bg-surface rounded-xl border border-border flex items-center gap-3">
                                <img src={image} className="w-16 h-16 object-cover rounded-lg border border-border bg-white" alt={`product ${index}`} />
                                <div className="flex-grow text-left">
                                    <p className="text-[9px] font-black uppercase text-text-muted tracking-widest">{index === 0 ? 'Primary Cover' : `Angle ${index + 1}`}</p>
                                    <div className="flex gap-2 mt-1">
                                        {!isSubmitting && index !== 0 && (
                                            <button type="button" onClick={() => setAsCover(index)} className="text-[8px] font-black uppercase text-accent hover:underline">Set Cover</button>
                                        )}
                                        {!isSubmitting && (
                                            <button type="button" onClick={() => removeImage(index)} className="text-[8px] font-black uppercase text-red-500 hover:underline">Discard</button>
                                        )}
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </GlassmorphicCard>

            <GlassmorphicCard className="p-8">
                <h2 className="text-[10px] font-black uppercase tracking-widest text-text-muted mb-6 border-b border-border pb-2">Trade Policy</h2>
                <div className="space-y-4">
                    <label className="flex items-center gap-3 cursor-pointer group p-3 bg-surface rounded-xl border border-border">
                        <input type="checkbox" name="allow_online" checked={formData.allow_online} onChange={handleChange} disabled={isSubmitting} className="w-5 h-5 rounded border-gray-600 text-accent" />
                        <span className="text-xs font-bold text-text-main group-hover:text-accent transition-colors">Pay via Card/UPI</span>
                    </label>
                    <label className="flex items-center gap-3 cursor-pointer group p-3 bg-surface rounded-xl border border-border">
                        <input type="checkbox" name="allow_cod" checked={formData.allow_cod} onChange={handleChange} disabled={isSubmitting} className="w-5 h-5 rounded border-gray-600 text-accent" />
                        <span className="text-xs font-bold text-text-main group-hover:text-accent transition-colors">Cash On Delivery</span>
                    </label>
                </div>
                <div className="mt-8 flex flex-col gap-3">
                    <button type="submit" disabled={isSubmitting} className="w-full bg-accent text-white py-4 rounded-2xl font-black uppercase tracking-widest text-xs shadow-xl shadow-accent/30 hover:-translate-y-1 active:translate-y-0 transition-all disabled:opacity-50">
                        {isSubmitting ? 'Syncing...' : (isEditing ? 'Commit Changes' : 'Go Live Now')}
                    </button>
                </div>
            </GlassmorphicCard>
        </div>
      </form>
    </div>
  );
};

