    } else if (categories.length > 0) {
        setFormData(prev => ({...prev, category: categories[0].id.toString()}));
    }
  }, [id, isEditing, getProduct, categories]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target as any;
    if (type === 'checkbox') {
        setFormData(prev => ({ ...prev, [name]: (e.target as any).checked }));
    } else {
        setFormData(prev => ({ ...prev, [name]: ['price', 'originalPrice', 'stock'].includes(name) ? parseFloat(value) || 0 : value }));
    }
  };

  const validateImage = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
        const img = new Image();
        img.onload = () => {
            if (img.width < 600 || img.height < 600) {
                reject(`Image "${file.name}" is too small (${img.width}x${img.height}). Min required: 600x600.`);
            } else {
                resolve(URL.createObjectURL(file));
            }
        };
        img.onerror = () => reject("Corrupted image file.");
        img.src = URL.createObjectURL(file);
    });
  };

  // Fixed handleImageChange to avoid unknown type error
  const handleImageChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const files = Array.from(e.target.files) as File[];
      const urls: string[] = [];

      for (const file of files) {
          try {
              const url = await validateImage(file);
              urls.push(url);
          } catch (err: any) {
              alert(err);
          }
      }

      if (urls.length > 0) {
        setTotalInQueue(urls.length);
        setCurrentCropIndex(0);
        setCropQueue(urls);
      }

      // Reset input so same file can be picked again
      e.target.value = '';
    }
  };

  const handleCropComplete = (croppedBase64: string) => {
    setFormData(prev => ({ ...prev, images: [...prev.images, croppedBase64] }));

    if (currentCropIndex < cropQueue.length - 1) {
        setCurrentCropIndex(prev => prev + 1);
    } else {
        setCropQueue([]);
    }
  };

  const removeImage = (index: number) => {
    setFormData(prev => ({ ...prev, images: prev.images.filter((_, i) => i !== index) }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if(formData.images.length === 0) { alert("Please upload at least one image."); return; }
    if (!formData.allow_online && !formData.allow_cod) { alert("Select at least one payment method."); return; }

    const finalHighlights = highlightsText.split('\n').map(s => s.trim()).filter(Boolean);
    const finalSpecs: { [key: string]: string } = {};
    specsText.split('\n').forEach(line => {
      const parts = line.split(':');
      if (parts.length === 2) finalSpecs[parts[0].trim()] = parts[1].trim();
    });

    const finalData = { ...formData, highlights: finalHighlights, specifications: finalSpecs };

    if (isEditing) {
      updateProduct({ ...finalData as any, id: parseInt(id) } as Product);
    } else {
      const { status, ...productData } = finalData;
      addProduct(productData as any);
    }
    navigate('/admin/products');
  };

  return (
    <div>
      {cropQueue.length > 0 && (
          <ImageCropperModal 
            image={cropQueue[currentCropIndex]} 
            queueCount={currentCropIndex + 1}
            totalInQueue={totalInQueue}
            title="Standardize Product Image"
            onCropComplete={handleCropComplete}
            onCancel={() => setCropQueue([])}
          />
      )}

      <h1 className="text-3xl font-black text-text-main uppercase italic mb-6">{isEditing ? 'Edit Catalog Entry' : 'Create New Inventory'}</h1>
      <GlassmorphicCard className="p-6">
        <form onSubmit={handleSubmit} className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div><label className="block text-[10px] font-black uppercase text-text-muted">Product Name</label><input type="text" name="name" value={formData.name} onChange={handleChange} required className={inputClasses} /></div>
                <div><label className="block text-[10px] font-black uppercase text-text-muted">Category</label><select name="category" value={formData.category} onChange={handleChange} className={inputClasses}>{categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}</select></div>
            </div>

            <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                <div><label className="block text-[10px] font-black uppercase text-text-muted">Price (₹)</label><input type="number" name="price" value={formData.price} onChange={handleChange} required className={inputClasses} /></div>
                <div><label className="block text-[10px] font-black uppercase text-text-muted">Original (₹)</label><input type="number" name="originalPrice" value={formData.originalPrice} onChange={handleChange} className={inputClasses} /></div>
                 <div><label className="block text-[10px] font-black uppercase text-text-muted">Stock Level</label><input type="number" name="stock" value={formData.stock} onChange={handleChange} required className={inputClasses} /></div>
            </div>

            <div><label className="block text-[10px] font-black uppercase text-text-muted">Description</label><textarea name="description" value={formData.description} onChange={handleChange} required rows={4} className={inputClasses}></textarea></div>

            <div className="p-4 bg-surface rounded-2xl border border-border">
                <label className="block text-[10px] font-black uppercase text-text-muted mb-3">Product Gallery</label>
                <div className="flex flex-wrap gap-4">
                    {formData.images.map((image, index) => (
                        <div key={index} className="relative group">
                            <img src={image} alt={`preview ${index}`} className="w-24 h-24 object-cover rounded-xl border-2 border-white shadow-md"/>
                            <button type="button" onClick={() => removeImage(index)} className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full w-6 h-6 flex items-center justify-center text-xs font-bold shadow-lg hover:scale-110 transition-transform">&times;</button>
                        </div>
                    ))}
                    <div className="relative">
                        <input type="file" id="imageUpload" multiple accept="image/*" onChange={handleImageChange} className="hidden" />
                        <label htmlFor="imageUpload" className="w-24 h-24 cursor-pointer bg-white border-2 border-dashed border-accent/30 rounded-xl flex flex-col items-center justify-center text-accent hover:bg-accent/5 transition-all group">
                             <svg className="w-6 h-6 group-hover:scale-110 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4v16m8-8H4" /></svg>
                             <span className="text-[8px] font-black uppercase mt-1">Add Visuals</span>
                        </label>
                    </div>
                </div>
                <p className="text-[9px] text-text-muted mt-3 italic">* Minimum resolution: 600x600px. High quality 1:1 ratio images only.</p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                    <label className="block text-[10px] font-black uppercase text-text-muted mb-4 border-b border-border pb-1">Payment Options</label>
                    <div className="flex gap-6">
                        <label className="flex items-center gap-2 cursor-pointer"><input type="checkbox" name="allow_online" checked={formData.allow_online} onChange={handleChange} className="w-4 h-4 rounded border-gray-600 text-accent focus:ring-accent bg-surface"/><span className="text-xs font-bold text-text-main">Digital</span></label>
                        <label className="flex items-center gap-2 cursor-pointer"><input type="checkbox" name="allow_cod" checked={formData.allow_cod} onChange={handleChange} className="w-4 h-4 rounded border-gray-600 text-accent focus:ring-accent bg-surface"/><span className="text-xs font-bold text-text-main">COD</span></label>
                    </div>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div><label className="block text-[10px] font-black uppercase text-text-muted">Highlights (per line)</label><textarea value={highlightsText} onChange={(e) => setHighlightsText(e.target.value)} rows={4} className={inputClasses} placeholder="e.g.&#10;Premium Design"></textarea></div>
                <div><label className="block text-[10px] font-black uppercase text-text-muted">Specifications (Key: Value)</label><textarea value={specsText} onChange={(e) => setSpecsText(e.target.value)} rows={4} className={inputClasses} placeholder="e.g.&#10;Color: Black"></textarea></div>
            </div>

            <div className="flex justify-end gap-4 pt-4">
                <button type="button" onClick={() => navigate('/admin/products')} className="px-6 py-2 rounded-xl text-[10px] font-black uppercase text-text-secondary hover:bg-surface">Cancel</button>
                <button type="submit" className="bg-accent text-white px-8 py-3 rounded-xl font-black uppercase tracking-widest text-xs shadow-xl shadow-accent/20 hover:-translate-y-1 transition-all">{isEditing ? 'Sync Changes' : 'Go Live'}</button>
            </div>
        </form>
      </GlassmorphicCard>
    </div>
  );
};

export default AdminProductFormPage;

import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useProducts } from '../../hooks/useProducts';
import { useCategories } from '../../hooks/useCategories';
import GlassmorphicCard from '../../components/GlassmorphicCard';
import { Product } from '../../types';
import { useVendors } from '../../context/VendorContext';
import { useAuth } from '../../context/AuthContext';
import Toast from '../../components/Toast';
import { ChevronLeftIcon } from '../../components/icons/ChevronLeftIcon';
import ImageCropperModal from '../../components/ImageCropperModal';

const VendorProductFormPage: React.FC = () => {
  const { id } = useParams<{ id?: string }>();
  const navigate = useNavigate();
  const { getProduct, addProduct, updateProduct } = useProducts();
  const { categories } = useCategories();
  const { currentVendor, fetchCurrentVendor } = useVendors();
  const { user } = useAuth();

  const isEditing = id !== undefined;
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [toast, setToast] = useState({ show: false, message: '', type: 'success' as 'success' | 'info' });

  const [formData, setFormData] = useState<Omit<Product, 'id' | 'reviews' | 'rating' | 'reviewCount' | 'status' | 'vendorId'>>({
    name: '',
    category: '', 
    price: 0,
    originalPrice: 0,
    images: [],
    description: '',
    highlights: [],
    stock: 10,
    specifications: {},
    sellerInfo: '',
    returnPolicy: '30-Day Money Back Guarantee',
    warranty: '1 Year Standard Warranty',
    videoUrl: '',
    allow_online: true,
    allow_cod: true
  });

  const [highlightsText, setHighlightsText] = useState('');
  const [specsText, setSpecsText] = useState('');

  // Cropper States
  const [cropQueue, setCropQueue] = useState<string[]>([]);
  const [currentCropIndex, setCurrentCropIndex] = useState(0);
  const [totalInQueue, setTotalInQueue] = useState(0);

  const inputClasses = "w-full mt-1 bg-surface text-text-main border border-gray-600 rounded-lg p-3 transition focus:outline-none focus:border-accent focus:ring-2 focus:ring-accent/50 disabled:opacity-50";

  const showToast = (message: string, type: 'success' | 'info' = 'success') => {
    setToast({ show: true, message, type });
  };

  useEffect(() => {
    if (user?.email && !currentVendor) fetchCurrentVendor(user.email);
  }, [user, currentVendor]);

  useEffect(() => {
    if (isEditing) {
      const productToEdit = getProduct(parseInt(id));
      if (productToEdit) {
        const cat = categories.find(c => c.name === productToEdit.category);
        setFormData({ 
            ...productToEdit, 
            category: cat ? cat.id.toString() : '',
            allow_online: productToEdit.allow_online ?? true,
            allow_cod: productToEdit.allow_cod ?? true
        });
        setHighlightsText((productToEdit.highlights || []).join('\n'));
        setSpecsText(Object.entries(productToEdit.specifications || {}).map(([k, v]) => `${k}: ${v}`).join('\n'));
      }
    } else if (categories.length > 0) {
      setFormData(prev => ({...prev, category: categories[0].id.toString()}));
    }
  }, [id, isEditing, getProduct, categories]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target as any;
    if (type === 'checkbox') {
        setFormData(prev => ({ ...prev, [name]: (e.target as any).checked }));
    } else {
        setFormData(prev => ({ ...prev, [name]: ['price', 'originalPrice', 'stock'].includes(name) ? parseFloat(value) || 0 : value }));
    }
  };

  const validateImage = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
        const img = new Image();
        img.onload = () => {
            if (img.width < 100 || img.height < 100) {
                reject(`Visual "${file.name}" is too small. We require 100x100px minimum.`);
            } else {
                resolve(URL.createObjectURL(file));
            }
        };
        img.onerror = () => reject("Corrupted media file.");
        img.src = URL.createObjectURL(file);
    });
  };

  // Fixed handleImageChange to avoid unknown type error
  const handleImageChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const files = Array.from(e.target.files) as File[];
      const urls: string[] = [];

      if (formData.images.length + files.length > 5) {
          alert("Maximum 5 assets allowed per catalog entry.");
          return;
      }

      for (const file of files) {
          try {
              const url = await validateImage(file);
              urls.push(url);
          } catch (err: any) {
              alert(err);
          }
      }

      if (urls.length > 0) {
        setTotalInQueue(urls.length);
        setCurrentCropIndex(0);
        setCropQueue(urls);
      }

      e.target.value = '';
    }
  };

  const handleCropComplete = (croppedBase64: string) => {
    setFormData(prev => ({ ...prev, images: [...prev.images, croppedBase64] }));

    if (currentCropIndex < cropQueue.length - 1) {
        setCurrentCropIndex(prev => prev + 1);
    } else {
        setCropQueue([]);
    }
  };

  const removeImage = (index: number) => {
    setFormData(prev => ({ ...prev, images: prev.images.filter((_, i) => i !== index) }));
  };

  const setAsCover = (index: number) => {
    setFormData(prev => {
        const newImages = [...prev.images];
        const [cover] = newImages.splice(index, 1);
        return { ...prev, images: [cover, ...newImages] };
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentVendor) { alert("Vendor session expired."); return; }
    if (formData.images.length === 0) { alert("Please provide at least one product image."); return; }
    if (!formData.allow_online && !formData.allow_cod) { alert("Select a supported payment mode."); return; }

    setIsSubmitting(true);
    try {
        const finalHighlights = highlightsText.split('\n').map(s => s.trim()).filter(Boolean);
        const finalSpecs: { [key: string]: string } = {};
        specsText.split('\n').forEach(line => {
          const parts = line.split(':');
          if (parts.length === 2) finalSpecs[parts[0].trim()] = parts[1].trim();
        });

        const finalData = { 
            ...formData, 
            vendor_id: currentVendor.id,
            highlights: finalHighlights, 
            specifications: finalSpecs 
        };

        if (isEditing) {
          await updateProduct({ ...finalData as any, id: parseInt(id), status: 'approved' });
          showToast("Changes synced successfully.");
        } else {
          await addProduct({ ...finalData, status: 'approved' });
          showToast("Listing published to marketplace.");
        }
        setTimeout(() => navigate('/vendor/products'), 1500);
    } catch (err: any) {
        console.error("[Listing Error]", err);
        alert(`Failed to save listing: ${err.message || "Network Error"}`);
    } finally {
        setIsSubmitting(false);
    }
  };

  return (
    <div className="pb-10 max-w-5xl mx-auto">
      <Toast isVisible={toast.show} message={toast.message} type={toast.type} onClose={() => setToast({ ...toast, show: false })} />

      {cropQueue.length > 0 && (
          <ImageCropperModal 
            image={cropQueue[currentCropIndex]} 
            queueCount={currentCropIndex + 1}
            totalInQueue={totalInQueue}
            title="Standardize Product Visual"
            onCropComplete={handleCropComplete}
            onCancel={() => setCropQueue([])}
          />
      )}

      <div className="flex items-center gap-4 mb-8">
          <button onClick={() => navigate('/vendor/products')} className="p-3 bg-surface rounded-2xl hover:bg-white transition-all shadow-sm border border-border">
              <ChevronLeftIcon className="w-5 h-5" />
          </button>
          <h1 className="text-3xl font-black text-text-main italic tracking-tight uppercase">
            {isEditing ? 'Modify Listing' : 'Marketplace Entry'}
          </h1>
      </div>

      <form onSubmit={handleSubmit} className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 space-y-6">
            <GlassmorphicCard className="p-8">
                <h2 className="text-[10px] font-black uppercase tracking-widest text-text-muted mb-6 border-b border-border pb-2">Listing Attributes</h2>
                <div className="space-y-4">
                    <div>
                        <label className="block text-[10px] font-black uppercase text-text-muted mb-1">Commercial Title</label>
                        <input type="text" name="name" value={formData.name} onChange={handleChange} required disabled={isSubmitting} className={inputClasses} placeholder="e.g., Signature Suede Loafers" />
                    </div>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div>
                            <label className="block text-[10px] font-black uppercase text-text-muted mb-1">Product Category</label>
                            <select name="category" value={formData.category} onChange={handleChange} disabled={isSubmitting} className={inputClasses}>
                                {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                            </select>
                        </div>
                        <div>
                            <label className="block text-[10px] font-black uppercase text-text-muted mb-1">Units in Stock</label>
                            <input type="number" name="stock" value={formData.stock} onChange={handleChange} required disabled={isSubmitting} className={inputClasses} />
                        </div>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-[10px] font-black uppercase text-text-muted mb-1">Market Price (₹)</label>
                            <input type="number" name="price" value={formData.price} onChange={handleChange} required disabled={isSubmitting} className={inputClasses} />
                        </div>
                        <div>
                            <label className="block text-[10px] font-black uppercase text-text-muted mb-1">Old Price (₹)</label>
                            <input type="number" name="originalPrice" value={formData.originalPrice} onChange={handleChange} disabled={isSubmitting} className={inputClasses} />
                        </div>
                    </div>
                </div>
            </GlassmorphicCard>

            <GlassmorphicCard className="p-8">
                <h2 className="text-[10px] font-black uppercase tracking-widest text-text-muted mb-6 border-b border-border pb-2">Content Strategy</h2>
                <div className="space-y-4">
                    <div>
                        <label className="block text-[10px] font-black uppercase text-text-muted mb-1">Detailed Description</label>
                        <textarea name="description" value={formData.description} onChange={handleChange} required rows={4} disabled={isSubmitting} className={`${inputClasses} resize-none`} placeholder="Describe the item's unique value..."></textarea>
                    </div>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div>
                            <label className="block text-[10px] font-black uppercase text-text-muted mb-1">Key Highlights</label>
                            <textarea value={highlightsText} onChange={(e) => setHighlightsText(e.target.value)} rows={4} disabled={isSubmitting} className={`${inputClasses} resize-none font-medium`} placeholder="• Eco-friendly Material"></textarea>
                        </div>
                        <div>
                            <label className="block text-[10px] font-black uppercase text-text-muted mb-1">Technical Specs (K:V)</label>
                            <textarea value={specsText} onChange={(e) => setSpecsText(e.target.value)} rows={4} disabled={isSubmitting} className={`${inputClasses} resize-none font-mono text-xs`} placeholder="Size: XL"></textarea>
                        </div>
                    </div>
                </div>
            </GlassmorphicCard>
        </div>

        <div className="space-y-6">
            <GlassmorphicCard className="p-8">
                <h2 className="text-[10px] font-black uppercase tracking-widest text-text-muted mb-6 border-b border-border pb-2">Visual Catalog</h2>
                <div className="space-y-4">
                    <div className="border-2 border-dashed border-border rounded-2xl p-6 text-center bg-surface/30 group hover:border-accent transition-colors">
                        <input type="file" id="imageUpload" multiple accept="image/*" onChange={handleImageChange} className="hidden" disabled={isSubmitting || formData.images.length >= 5} />
                        <label htmlFor="imageUpload" className={`cursor-pointer block ${formData.images.length >= 5 || isSubmitting ? 'opacity-50 cursor-not-allowed' : ''}`}>
                            <div className="w-12 h-12 bg-accent/10 rounded-full flex items-center justify-center mx-auto mb-3 group-hover:scale-110 transition-transform">
                                <svg className="w-6 h-6 text-accent" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
                            </div>
                            <p className="text-xs font-black uppercase tracking-tighter text-text-main">Add Visuals</p>
                            <p className="text-[10px] text-text-muted mt-1">{5 - formData.images.length} slots remaining</p>
                        </label>
                    </div>

                    <div className="grid grid-cols-1 gap-3">
                        {formData.images.map((image, index) => (
                            <div key={index} className="relative group p-2 bg-surface rounded-xl border border-border flex items-center gap-3">
                                <img src={image} className="w-16 h-16 object-cover rounded-lg border border-border bg-white" alt={`product ${index}`} />
                                <div className="flex-grow text-left">
                                    <p className="text-[9px] font-black uppercase text-text-muted tracking-widest">{index === 0 ? 'Primary Cover' : `Angle ${index + 1}`}</p>
                                    <div className="flex gap-2 mt-1">
                                        {!isSubmitting && index !== 0 && (
                                            <button type="button" onClick={() => setAsCover(index)} className="text-[8px] font-black uppercase text-accent hover:underline">Set Cover</button>
                                        )}
                                        {!isSubmitting && (
                                            <button type="button" onClick={() => removeImage(index)} className="text-[8px] font-black uppercase text-red-500 hover:underline">Discard</button>
                                        )}
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </GlassmorphicCard>

            <GlassmorphicCard className="p-8">
                <h2 className="text-[10px] font-black uppercase tracking-widest text-text-muted mb-6 border-b border-border pb-2">Trade Policy</h2>
                <div className="space-y-4">
                    <label className="flex items-center gap-3 cursor-pointer group p-3 bg-surface rounded-xl border border-border">
                        <input type="checkbox" name="allow_online" checked={formData.allow_online} onChange={handleChange} disabled={isSubmitting} className="w-5 h-5 rounded border-gray-600 text-accent" />
                        <span className="text-xs font-bold text-text-main group-hover:text-accent transition-colors">Pay via Card/UPI</span>
                    </label>
                    <label className="flex items-center gap-3 cursor-pointer group p-3 bg-surface rounded-xl border border-border">
                        <input type="checkbox" name="allow_cod" checked={formData.allow_cod} onChange={handleChange} disabled={isSubmitting} className="w-5 h-5 rounded border-gray-600 text-accent" />
                        <span className="text-xs font-bold text-text-main group-hover:text-accent transition-colors">Cash On Delivery</span>
                    </label>
                </div>
                <div className="mt-8 flex flex-col gap-3">
                    <button type="submit" disabled={isSubmitting} className="w-full bg-accent text-white py-4 rounded-2xl font-black uppercase tracking-widest text-xs shadow-xl shadow-accent/30 hover:-translate-y-1 active:translate-y-0 transition-all disabled:opacity-50">
                        {isSubmitting ? 'Syncing...' : (isEditing ? 'Commit Changes' : 'Go Live Now')}
                    </button>
                </div>
            </GlassmorphicCard>
        </div>
      </form>
    </div>
  );
};

export default VendorProductFormPage;

export interface Review {
  id: string;
  author: string;
  userId: string;
  orderId: string;
  rating: number;
  comment: string;
  date: string;
  images?: string[];
  vendorReply?: string;
}

export type ProductStatus = 'approved' | 'disabled' | 'archived' | 'live' | 'pending' | 'rejected';

export interface Product {
  id: number;
  name: string;
  category: string;
  price: number;
  originalPrice?: number;
